def allowed_restaurant_poster_filename(
    filename,
):

    if (
        not filename
        or "." not in filename
    ):
        return False

    extension = (
        filename
        .rsplit(
            ".",
            1,
        )[1]
        .lower()
    )

    return (
        extension
        in RESTAURANT_POSTER_ALLOWED_EXTENSIONS
    )
