def get_restaurant_analytics_session_id():

    session_id = session.get(
        RESTAURANT_ANALYTICS_SESSION_KEY
    )

    if not session_id:

        session_id = (
            uuid4().hex
        )

        session[
            RESTAURANT_ANALYTICS_SESSION_KEY
        ] = session_id

    return session_id



