def cloudinary_reels_configured():

    return all(
        [
            CLOUDINARY_CLOUD_NAME,
            CLOUDINARY_API_KEY,
            CLOUDINARY_API_SECRET,
        ]
    )






def _yoco_amount_in_cents(amount):
    try:
        value = Decimal(str(amount)) * 100
        if value != value.to_integral_value():
            return None
        return int(value)
    except (InvalidOperation, TypeError, ValueError):
        return None


def _yoco_payment_used_elsewhere(payment_id, kind, row_id):
    organizer_match = (
        SubscriptionPayment.query
        .filter_by(yoco_payment_id=payment_id)
        .first()
    )

    restaurant_match = (
        RestaurantSubscriptionPayment.query
        .filter_by(yoco_payment_id=payment_id)
        .first()
    )

    if organizer_match and not (
        kind == "organizer" and organizer_match.id == row_id
    ):
        return True

    if restaurant_match and not (
        kind == "restaurant" and restaurant_match.id == row_id
    ):
        return True

    return False



# ============================================================
# PROCESS YOCO PAYMENTS
# ORGANIZER SUBSCRIPTIONS
# RESTAURANT SUBSCRIPTIONS
# RESTAURANT SPECIALS
# ============================================================

def process_yoco_subscription_payment(event):
    """
    Process a verified Yoco webhook event.

    Supports:
        1. Organizer subscription payments.
        2. Restaurant subscription payments.
        3. Restaurant special payments.

    Security:
        - Called only after webhook signature verification.
        - Independently retrieves candidate checkouts from Yoco.
        - Never activates a payment using webhook data alone.
        - Never treats a payment ID as a checkout ID.
        - Requires exactly one matching local payment record.

    Idempotency:
        Subscription payments continue through the existing
        subscription verification function.

        Restaurant specials use their dedicated verification
        and activation function.
    """

    # ========================================================
    # VALIDATE EVENT
    # ========================================================

    if not isinstance(event, dict):

        return "invalid"

    # ========================================================
    # EXTRACT WEBHOOK IDENTIFIERS
    # ========================================================

    try:

        identifiers = extract_yoco_webhook_identifiers(
            event
        )

    except YocoWebhookError:

        current_app.logger.warning(
            "[Yoco] Could not extract webhook identifiers."
        )

        return "invalid"

    event_type = identifiers.get(
        "event_type"
    )

    checkout_id = identifiers.get(
        "checkout_id"
    )

    yoco_payment_id = identifiers.get(
        "payment_id"
    )

    # ========================================================
    # IGNORE UNRELATED EVENTS
    # ========================================================

    if event_type != "payment.succeeded":

        return "ignored"

    # ========================================================
    # LOCAL HELPER: FIND CHECKOUT OWNERS
    # ========================================================

    def find_checkout_owners(target_checkout_id):
        """
        Find every local payment record associated with a
        checkout ID.

        A checkout must belong to exactly one payment record
        across all three supported payment types.
        """

        if (
            not isinstance(target_checkout_id, str)
            or not target_checkout_id.strip()
        ):

            return []

        owners = []

        # ----------------------------------------------------
        # ORGANIZER SUBSCRIPTION
        # ----------------------------------------------------

        organizer_payments = (
            SubscriptionPayment.query
            .filter_by(
                yoco_checkout_id=target_checkout_id,
                payment_method="yoco",
            )
            .all()
        )

        for payment in organizer_payments:

            owners.append((
                "organizer",
                payment.id,
            ))

        # ----------------------------------------------------
        # RESTAURANT SUBSCRIPTION
        # ----------------------------------------------------

        restaurant_payments = (
            RestaurantSubscriptionPayment.query
            .filter_by(
                yoco_checkout_id=target_checkout_id,
                payment_method="yoco",
            )
            .all()
        )

        for payment in restaurant_payments:

            owners.append((
                "restaurant",
                payment.id,
            ))

        # ----------------------------------------------------
        # RESTAURANT SPECIAL
        # ----------------------------------------------------

        special_payments = (
            RestaurantSpecialPayment.query
            .filter_by(
                yoco_checkout_id=target_checkout_id,
                payment_method="yoco",
            )
            .all()
        )

        for payment in special_payments:

            owners.append((
                "restaurant_special",
                payment.id,
            ))

        return owners

    # ========================================================
    # LOCAL HELPER: DISPATCH PAYMENT VERIFICATION
    # ========================================================

    def verify_matched_payment(kind, payment_id):
        """
        Send the matched payment to its dedicated verifier.
        """

        if kind == "organizer":

            return verify_and_activate_yoco_subscription(
                kind="organizer",
                payment_id=payment_id,
                source="webhook",
            )

        if kind == "restaurant":

            return verify_and_activate_yoco_subscription(
                kind="restaurant",
                payment_id=payment_id,
                source="webhook",
            )

        if kind == "restaurant_special":

            return verify_and_activate_restaurant_special_payment(
                payment_id=payment_id,
                source="webhook",
            )

        return "invalid"

    # ========================================================
    # PATH 1: WEBHOOK CONTAINS CHECKOUT ID
    # ========================================================

    if checkout_id:

        owners = find_checkout_owners(
            checkout_id
        )

        # ----------------------------------------------------
        # NO MATCH
        # ----------------------------------------------------

        if not owners:

            db.session.rollback()

            current_app.logger.warning(
                "[Yoco] Checkout ID has no local payment record."
            )

            return "unmatched"

        # ----------------------------------------------------
        # MULTIPLE MATCHES
        # ----------------------------------------------------

        if len(owners) != 1:

            db.session.rollback()

            current_app.logger.error(
                (
                    "[Yoco] Checkout ID is associated with "
                    "multiple local payment records."
                )
            )

            return "invalid"

        # ----------------------------------------------------
        # VERIFY MATCHED PAYMENT
        # ----------------------------------------------------

        matched_kind, matched_payment_id = owners[0]

        # Capture IDs before releasing the read transaction.
        db.session.rollback()

        return verify_matched_payment(
            matched_kind,
            matched_payment_id,
        )

    # ========================================================
    # PATH 2: WEBHOOK CONTAINS PAYMENT ID ONLY
    # ========================================================

    if (
        not isinstance(yoco_payment_id, str)
        or not yoco_payment_id.strip()
    ):

        current_app.logger.warning(
            (
                "[Yoco] Successful payment event contains "
                "neither a checkout ID nor a payment ID."
            )
        )

        return "unmatched"

    # ========================================================
    # FIND PENDING CHECKOUT CANDIDATES
    # ========================================================

    candidates = []

    # --------------------------------------------------------
    # ORGANIZER SUBSCRIPTION CANDIDATES
    # --------------------------------------------------------

    organizer_candidates = (
        SubscriptionPayment.query
        .filter_by(
            payment_method="yoco",
            payment_status="pending",
        )
        .filter(
            SubscriptionPayment.yoco_checkout_id.isnot(
                None
            )
        )
        .order_by(
            SubscriptionPayment.created_at.desc()
        )
        .limit(100)
        .all()
    )

    for payment in organizer_candidates:

        if payment.yoco_checkout_id:

            candidates.append((
                "organizer",
                payment.id,
                payment.yoco_checkout_id,
            ))

    # --------------------------------------------------------
    # RESTAURANT SUBSCRIPTION CANDIDATES
    # --------------------------------------------------------

    restaurant_candidates = (
        RestaurantSubscriptionPayment.query
        .filter_by(
            payment_method="yoco",
            payment_status="pending",
        )
        .filter(
            RestaurantSubscriptionPayment.yoco_checkout_id.isnot(
                None
            )
        )
        .order_by(
            RestaurantSubscriptionPayment.created_at.desc()
        )
        .limit(100)
        .all()
    )

    for payment in restaurant_candidates:

        if payment.yoco_checkout_id:

            candidates.append((
                "restaurant",
                payment.id,
                payment.yoco_checkout_id,
            ))

    # --------------------------------------------------------
    # RESTAURANT SPECIAL CANDIDATES
    # --------------------------------------------------------

    special_candidates = (
        RestaurantSpecialPayment.query
        .filter_by(
            payment_method="yoco",
            payment_status="pending",
        )
        .filter(
            RestaurantSpecialPayment.yoco_checkout_id.isnot(
                None
            )
        )
        .order_by(
            RestaurantSpecialPayment.created_at.desc()
        )
        .limit(100)
        .all()
    )

    for payment in special_candidates:

        if payment.yoco_checkout_id:

            candidates.append((
                "restaurant_special",
                payment.id,
                payment.yoco_checkout_id,
            ))

    # --------------------------------------------------------
    # RELEASE THE READ TRANSACTION
    # --------------------------------------------------------

    db.session.rollback()

    # ========================================================
    # ASK YOCO WHICH CHECKOUT MATCHES THE PAYMENT ID
    # ========================================================

    matching_candidates = []

    verification_errors = 0

    for (
        kind,
        payment_id,
        candidate_checkout_id,
    ) in candidates:

        try:

            checkout = get_yoco_checkout(
                candidate_checkout_id
            )

        except YocoError:

            verification_errors += 1

            current_app.logger.warning(
                (
                    "[Yoco] Could not retrieve candidate "
                    "checkout during payment reconciliation."
                )
            )

            continue

        if not isinstance(checkout, dict):

            continue

        # ----------------------------------------------------
        # VERIFY STORED CHECKOUT ID
        # ----------------------------------------------------

        if (
            checkout.get("id")
            != candidate_checkout_id
        ):

            continue

        # ----------------------------------------------------
        # VERIFY COMPLETED STATUS
        # ----------------------------------------------------

        if (
            str(
                checkout.get("status", "")
            ).lower()
            != "completed"
        ):

            continue

        # ----------------------------------------------------
        # VERIFY PAYMENT ID
        # ----------------------------------------------------

        checkout_payment_id = checkout.get(
            "paymentId"
        )

        if not isinstance(
            checkout_payment_id,
            str,
        ):

            continue

        if (
            checkout_payment_id.strip()
            != yoco_payment_id
        ):

            continue

        # ----------------------------------------------------
        # MATCH FOUND
        # ----------------------------------------------------

        matching_candidates.append((
            kind,
            payment_id,
        ))

    # ========================================================
    # REQUIRE EXACTLY ONE MATCH
    # ========================================================

    if len(matching_candidates) != 1:

        if len(matching_candidates) > 1:

            current_app.logger.error(
                (
                    "[Yoco] Payment ID matched multiple "
                    "local checkout records."
                )
            )

            return "invalid"

        if verification_errors:

            current_app.logger.warning(
                (
                    "[Yoco] Payment reconciliation incomplete "
                    "because one or more Yoco requests failed."
                )
            )

            return "pending"

        current_app.logger.warning(
            (
                "[Yoco] No matching checkout found for "
                "the successful payment event."
            )
        )

        return "unmatched"

    # ========================================================
    # VERIFY THE MATCHED PAYMENT
    # ========================================================

    matched_kind, matched_payment_id = (
        matching_candidates[0]
    )

    return verify_matched_payment(
        matched_kind,
        matched_payment_id,
    )


# ============================================================
# KALXA - SHARED YOCO SUBSCRIPTION VERIFICATION SERVICE
# ============================================================
#
# Supports:
#   - Organizer subscriptions
#   - Restaurant subscriptions
#   - Verified Yoco webhooks
#   - Authenticated server-side reconciliation
#
# IMPORTANT:
#   Never call this service with a checkout supplied
#   directly by an unauthenticated browser.
#
# PostgreSQL is required for row-level locking.
#
# ============================================================


class YocoSubscriptionVerificationError(Exception):
    pass


def _yoco_matching_id(value, expected):
    if isinstance(value, bool) or value is None:
        return False

    return str(value) == str(expected)


def _yoco_checkout_matches_payment(
    checkout,
    payment,
    kind,
):
    if not isinstance(checkout, dict):
        return False

    if checkout.get("id") != payment.yoco_checkout_id:
        return False

    if checkout.get("status") != "completed":
        return False

    if checkout.get("currency") != "ZAR":
        return False

    amount = checkout.get("amount")

    if (
        isinstance(amount, bool)
        or not isinstance(amount, int)
        or amount <= 0
        or amount != _yoco_amount_in_cents(payment.amount)
    ):
        return False

    payment_id = checkout.get("paymentId")

    if not isinstance(payment_id, str) or not payment_id.strip():
        return False

    metadata = checkout.get("metadata")

    if not isinstance(metadata, dict):
        return False

    if (
        metadata.get("kalxa_payment_reference")
        != payment.payment_reference
    ):
        return False

    if not _yoco_matching_id(
        metadata.get("organizer_id"),
        payment.organizer_id,
    ):
        return False

    if not _yoco_matching_id(
        metadata.get("period_days"),
        payment.period_days,
    ):
        return False

    if kind == "organizer":
        if metadata.get("payment_type") != "organizer_subscription":
            return False

        if not _yoco_matching_id(
            metadata.get("subscription_payment_id"),
            payment.id,
        ):
            return False

    elif kind == "restaurant":
        if metadata.get("payment_type") != "restaurant_subscription":
            return False

        if not _yoco_matching_id(
            metadata.get("restaurant_subscription_payment_id"),
            payment.id,
        ):
            return False

        if not _yoco_matching_id(
            metadata.get("restaurant_advert_id"),
            payment.restaurant_advert_id,
        ):
            return False

        if metadata.get("plan_tier") != payment.plan_tier:
            return False

        if (
            str(payment.currency or "").upper()
            != checkout.get("currency")
        ):
            return False

    else:
        return False

    return True


def _yoco_lock_subscription_payment(kind, payment_id):
    if kind == "organizer":
        model = SubscriptionPayment
    elif kind == "restaurant":
        model = RestaurantSubscriptionPayment
    else:
        return None

    return (
        db.session.query(model)
        .filter(model.id == payment_id)
        .with_for_update()
        .first()
    )


def _yoco_find_checkout_payment(
    checkout_id,
):
    """
    Find a local subscription payment by Yoco
    checkout ID.

    Supported payment types:
        organizer
        restaurant

    Returns:
        ("organizer", payment_id)
        ("restaurant", payment_id)
        (None, None)

    SECURITY:
        The same checkout ID must never resolve
        to two different subscription payments.
    """

    # ========================================================
    # VALIDATE CHECKOUT ID
    # ========================================================

    if not isinstance(checkout_id, str):

        return None, None

    checkout_id = (
        checkout_id.strip()
    )

    if not checkout_id:

        return None, None

    # ========================================================
    # ORGANIZER PAYMENT LOOKUP
    # ========================================================

    organizer_payment = (
        SubscriptionPayment.query
        .filter_by(
            yoco_checkout_id=checkout_id,
            payment_method="yoco",
        )
        .first()
    )

    # ========================================================
    # RESTAURANT PAYMENT LOOKUP
    # ========================================================

    restaurant_payment = (
        RestaurantSubscriptionPayment.query
        .filter_by(
            yoco_checkout_id=checkout_id,
            payment_method="yoco",
        )
        .first()
    )

    # ========================================================
    # AMBIGUOUS CHECKOUT
    # ========================================================

    if (
        organizer_payment is not None
        and restaurant_payment is not None
    ):

        current_app.logger.error(
            "[Yoco] Checkout ID exists in both "
            "organizer and restaurant payment tables."
        )

        return None, None

    # ========================================================
    # ORGANIZER PAYMENT FOUND
    # ========================================================

    if organizer_payment is not None:

        return (
            "organizer",
            organizer_payment.id,
        )

    # ========================================================
    # RESTAURANT PAYMENT FOUND
    # ========================================================

    if restaurant_payment is not None:

        return (
            "restaurant",
            restaurant_payment.id,
        )

    # ========================================================
    # NO MATCH
    # ========================================================

    return None, None


def verify_and_activate_yoco_subscription(
    *,
    kind,
    payment_id,
    source="reconciliation",
):
    """
    Independently verify an existing Yoco checkout and
    atomically activate the associated Kalxa subscription.

    Supported subscription types:
        - organizer
        - restaurant

    Supported verification sources:
        - webhook
        - reconciliation

    Returns:
        - activated
        - already_processed
        - pending
        - invalid
        - unmatched

    SECURITY:
        - Never trust a browser redirect as payment proof.
        - Never activate using webhook data alone.
        - Retrieve checkout details directly from Yoco.
        - Verify checkout ID, amount, currency and metadata.
        - Require a verified Yoco payment identifier.
        - Reject mismatched subscription ownership.
        - Reject reuse of a payment identifier.

    IDEMPOTENCY:
        A successfully processed payment must never
        extend the same subscription twice.

    TRANSACTIONS:
        Payment status and subscription activation are
        committed in one database transaction.
    """

    # ========================================================
    # 1. VALIDATE SUBSCRIPTION TYPE
    # ========================================================

    if kind not in (
        "organizer",
        "restaurant",
    ):
        return "invalid"

    # ========================================================
    # 2. VALIDATE VERIFICATION SOURCE
    # ========================================================

    if source not in (
        "webhook",
        "reconciliation",
    ):
        return "invalid"

    # ========================================================
    # 3. SELECT PAYMENT MODEL
    # ========================================================

    model = (
        SubscriptionPayment
        if kind == "organizer"
        else RestaurantSubscriptionPayment
    )

    # ========================================================
    # 4. INITIAL PAYMENT LOOKUP
    # ========================================================

    initial = db.session.get(
        model,
        payment_id,
    )

    if initial is None:

        db.session.rollback()

        return "unmatched"

    if initial.payment_method != "yoco":

        db.session.rollback()

        return "invalid"

    # ========================================================
    # 5. SNAPSHOT IDENTIFIERS
    # ========================================================

    checkout_id = (
        initial.yoco_checkout_id
    )

    organizer_id = (
        initial.organizer_id
    )

    initial_payment_status = (
        initial.payment_status
    )

    initial_yoco_payment_id = (
        initial.yoco_payment_id
    )

    if not checkout_id:

        db.session.rollback()

        current_app.logger.warning(
            (
                "[Yoco] Payment record has no checkout ID. "
                "kind=%s payment_id=%s"
            ),
            kind,
            payment_id,
        )

        return "invalid"

    # ========================================================
    # 6. END INITIAL LOOKUP TRANSACTION
    # ========================================================

    db.session.rollback()

    # ========================================================
    # 7. RETRIEVE CHECKOUT DIRECTLY FROM YOCO
    # ========================================================

    # YocoError is intentionally allowed to propagate.
    #
    # The webhook route should return HTTP 500 when Yoco
    # verification is temporarily unavailable, allowing
    # the webhook provider to retry delivery.
    #
    # The customer return route should catch YocoError
    # and display a temporary verification message.

    checkout = get_yoco_checkout(
        checkout_id
    )

    if not isinstance(checkout, dict):

        current_app.logger.warning(
            (
                "[Yoco] Invalid checkout response. "
                "kind=%s payment_id=%s"
            ),
            kind,
            payment_id,
        )

        return "invalid"

    # ========================================================
    # 8. VALIDATE CHECKOUT ID
    # ========================================================

    returned_checkout_id = (
        checkout.get("id")
    )

    if returned_checkout_id != checkout_id:

        current_app.logger.warning(
            (
                "[Yoco] Checkout ID mismatch. "
                "kind=%s payment_id=%s"
            ),
            kind,
            payment_id,
        )

        return "invalid"

    # ========================================================
    # 9. VALIDATE CHECKOUT STATUS
    # ========================================================

    checkout_status = str(
        checkout.get("status") or ""
    ).strip().lower()

    if checkout_status != "completed":

        current_app.logger.info(
            (
                "[Yoco] Checkout not completed. "
                "kind=%s payment_id=%s status=%s"
            ),
            kind,
            payment_id,
            checkout_status,
        )

        return "pending"

    # ========================================================
    # 10. VERIFY PAYMENT ENVIRONMENT
    # ========================================================
    #
    # KALXA CURRENT CONFIGURATION:
    # TEST MODE ONLY.
    #
    # Do not remove this restriction until the live
    # payment configuration has been deliberately enabled
    # and tested.
    # ========================================================

    processing_mode = str(
        checkout.get("processingMode") or ""
    ).strip().lower()

    if processing_mode != "test":

        current_app.logger.warning(
            (
                "[Yoco] Checkout processing mode rejected. "
                "kind=%s payment_id=%s mode=%s"
            ),
            kind,
            payment_id,
            processing_mode,
        )

        return "invalid"

    # ========================================================
    # 11. VALIDATE VERIFIED PAYMENT ID
    # ========================================================

    yoco_payment_id = (
        checkout.get("paymentId")
    )

    if (
        not isinstance(yoco_payment_id, str)
        or not yoco_payment_id.strip()
    ):

        current_app.logger.warning(
            (
                "[Yoco] Completed checkout has no "
                "valid payment ID. "
                "kind=%s payment_id=%s"
            ),
            kind,
            payment_id,
        )

        return "invalid"

    yoco_payment_id = (
        yoco_payment_id.strip()
    )

    # ========================================================
    # 12. BEGIN DATABASE ACTIVATION TRANSACTION
    # ========================================================

    try:

        # ====================================================
        # LOCK ORGANIZER
        # ====================================================
        #
        # Locking the organizer serializes subscription
        # updates for payments owned by that organizer.
        # ====================================================

        organizer = (
            db.session.query(
                Organizer
            )
            .filter(
                Organizer.id == organizer_id
            )
            .with_for_update()
            .first()
        )

        if organizer is None:

            db.session.rollback()

            return "invalid"

        # ====================================================
        # LOCK PAYMENT RECORD
        # ====================================================

        payment = (
            _yoco_lock_subscription_payment(
                kind,
                payment_id,
            )
        )

        if payment is None:

            db.session.rollback()

            return "unmatched"

        # ====================================================
        # 13. RECHECK OWNERSHIP UNDER LOCK
        # ====================================================

        if (
            payment.organizer_id != organizer.id
            or payment.payment_method != "yoco"
            or payment.yoco_checkout_id != checkout_id
        ):

            db.session.rollback()

            current_app.logger.warning(
                (
                    "[Yoco] Payment ownership mismatch. "
                    "kind=%s payment_id=%s"
                ),
                kind,
                payment_id,
            )

            return "invalid"

        # ====================================================
        # 14. VERIFY CHECKOUT AGAINST LOCAL PAYMENT
        # ====================================================

        if not _yoco_checkout_matches_payment(
            checkout,
            payment,
            kind,
        ):

            db.session.rollback()

            current_app.logger.warning(
                (
                    "[Yoco] Checkout verification mismatch. "
                    "kind=%s payment_id=%s"
                ),
                kind,
                payment_id,
            )

            return "invalid"

        # ====================================================
        # 15. PREVENT PAYMENT ID REUSE
        # ====================================================

        if _yoco_payment_used_elsewhere(
            yoco_payment_id,
            kind,
            payment.id,
        ):

            db.session.rollback()

            current_app.logger.warning(
                (
                    "[Yoco] Payment ID already belongs "
                    "to another subscription payment. "
                    "kind=%s payment_id=%s"
                ),
                kind,
                payment_id,
            )

            return "invalid"

        # ====================================================
        # 16. IDEMPOTENCY
        # ====================================================

        if payment.payment_status == "paid":

            if (
                payment.yoco_payment_id
                == yoco_payment_id
            ):

                db.session.rollback()

                current_app.logger.info(
                    (
                        "[Yoco] Payment already processed. "
                        "kind=%s payment_id=%s"
                    ),
                    kind,
                    payment_id,
                )

                return "already_processed"

            db.session.rollback()

            return "invalid"

        # ====================================================
        # 17. REQUIRE PENDING PAYMENT
        # ====================================================

        if payment.payment_status != "pending":

            db.session.rollback()

            return "invalid"

        # ====================================================
        # 18. PREVENT PAYMENT ID REPLACEMENT
        # ====================================================

        if payment.yoco_payment_id not in (
            None,
            yoco_payment_id,
        ):

            db.session.rollback()

            return "invalid"

        # ====================================================
        # 19. VALIDATE SUBSCRIPTION PERIOD
        # ====================================================

        period_days = (
            payment.period_days
        )

        if (
            isinstance(period_days, bool)
            or not isinstance(period_days, int)
            or period_days <= 0
        ):

            db.session.rollback()

            return "invalid"

        # ====================================================
        # 20. CURRENT TIME
        # ====================================================

        now = datetime.utcnow()

        # ====================================================
        # 21. ORGANIZER SUBSCRIPTION ACTIVATION
        # ====================================================

        if kind == "organizer":

            # ================================================
            # REJECT SUSPENDED ORGANIZERS
            # ================================================

            if organizer.subscription_status == "suspended":

                db.session.rollback()

                return "invalid"

            # ================================================
            # EXISTING SUBSCRIPTION EXPIRY
            # ================================================

            current_expiry = (
                organizer.subscription_expires_at
            )

            # ================================================
            # DETERMINE SUBSCRIPTION START
            # ================================================

            if (
                current_expiry is not None
                and current_expiry > now
            ):

                start = current_expiry

            else:

                start = now

            # ================================================
            # DETERMINE SUBSCRIPTION END
            # ================================================

            end = (
                start
                +
                timedelta(
                    days=period_days
                )
            )

            # ================================================
            # ACTIVATE ORGANIZER
            # ================================================

            organizer.active = True

            organizer.subscription_status = (
                "active"
            )

            organizer.subscription_started_at = (
                start
            )

            organizer.subscription_expires_at = (
                end
            )

        # ====================================================
        # 22. RESTAURANT SUBSCRIPTION ACTIVATION
        # ====================================================

        else:

            # ================================================
            # LOCK RESTAURANT
            # ================================================

            advert = (
                db.session.query(
                    RestaurantAdvert
                )
                .filter(
                    RestaurantAdvert.id
                    == payment.restaurant_advert_id,

                    RestaurantAdvert.organizer_id
                    == organizer.id,
                )
                .with_for_update()
                .first()
            )

            if advert is None:

                db.session.rollback()

                return "invalid"

            # ================================================
            # VERIFY ORGANIZER STATUS
            # ================================================

            if not organizer.active:

                db.session.rollback()

                return "invalid"

            if organizer.subscription_status == "suspended":

                db.session.rollback()

                return "invalid"

            # ================================================
            # VERIFY RESTAURANT ACCOUNT TYPE
            # ================================================

            account_type = str(
                getattr(
                    organizer,
                    "account_type",
                    None,
                )
                or "event"
            ).strip().lower()

            if account_type != "restaurant":

                db.session.rollback()

                return "invalid"

            # ================================================
            # VALIDATE RESTAURANT PLAN
            # ================================================

            plan_tier = str(
                payment.plan_tier or ""
            ).strip().lower()

            if plan_tier not in RESTAURANT_PAYABLE_PLANS:

                db.session.rollback()

                return "invalid"

            # ================================================
            # VALIDATE PLAN PRICE
            # ================================================
            #
            # The checkout amount has already been compared
            # against the local payment amount by
            # _yoco_checkout_matches_payment().
            #
            # This additional check prevents an incorrectly
            # priced local payment record from activating
            # a paid plan.
            # ================================================

            configured_plan = (
                RESTAURANT_PAYABLE_PLANS[
                    plan_tier
                ]
            )

            configured_price = Decimal(
                str(
                    configured_plan["price"]
                )
            )

            payment_amount = Decimal(
                str(
                    payment.amount
                )
            )

            if payment_amount != configured_price:

                db.session.rollback()

                current_app.logger.warning(
                    (
                        "[Yoco] Restaurant plan price mismatch. "
                        "payment_id=%s plan=%s"
                    ),
                    payment_id,
                    plan_tier,
                )

                return "invalid"

            # ================================================
            # EXISTING RESTAURANT SUBSCRIPTION
            # ================================================

            current_tier = str(
                advert.subscription_tier or "free"
            ).strip().lower()

            current_expiry = (
                advert.subscription_expires_at
            )

            # ================================================
            # SAME ACTIVE PAID PLAN
            # ================================================

            same_active_tier = (
                current_tier == plan_tier
                and current_expiry is not None
                and current_expiry > now
            )

            # ================================================
            # DETERMINE SUBSCRIPTION START
            # ================================================

            if same_active_tier:

                start = current_expiry

            else:

                start = now

            # ================================================
            # DETERMINE SUBSCRIPTION END
            # ================================================

            end = (
                start
                +
                timedelta(
                    days=period_days
                )
            )

            # ================================================
            # ACTIVATE RESTAURANT PLAN
            # ================================================

            advert.subscription_tier = (
                plan_tier
            )

            advert.subscription_status = (
                "active"
            )

            advert.subscription_started_at = (
                start
            )

            advert.subscription_expires_at = (
                end
            )

        # ====================================================
        # 23. MARK PAYMENT VERIFIED
        # ====================================================

        payment.payment_status = (
            "paid"
        )

        payment.payment_method = (
            "yoco"
        )

        payment.yoco_payment_id = (
            yoco_payment_id
        )

        payment.yoco_payment_status = (
            "succeeded"
        )

        payment.payment_verified_at = (
            now
        )

        payment.paid_at = (
            now
        )

        payment.confirmed_at = (
            now
        )

        payment.confirmed_by = (
            "yoco_webhook"
            if source == "webhook"
            else "yoco_reconciliation"
        )

        payment.subscription_start = (
            start
        )

        payment.subscription_end = (
            end
        )

        # ====================================================
        # 24. COMMIT PAYMENT AND SUBSCRIPTION TOGETHER
        # ====================================================

        db.session.commit()

        # ====================================================
        # 25. LOG SUCCESS
        # ====================================================

        current_app.logger.info(
            (
                "[Yoco] Subscription activated. "
                "kind=%s "
                "payment_id=%s "
                "source=%s "
                "subscription_end=%s"
            ),
            kind,
            payment_id,
            source,
            end,
        )

        return "activated"

    # ========================================================
    # 26. ERROR HANDLING
    # ========================================================

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Yoco] Subscription activation failed. "
                "kind=%s payment_id=%s"
            ),
            kind,
            payment_id,
        )

        raise

def allowed_event_reel_filename(filename):

    if (
        not filename
        or "." not in filename
    ):
        return False

    extension = (
        filename
        .rsplit(".", 1)[1]
        .lower()
    )

    return (
        extension
        in EVENT_REEL_ALLOWED_EXTENSIONS
    )


def get_verified_organizer_paystack_split(organizer):
    """
    Return the verified Paystack split code for an organiser.

    This function deliberately fails closed.

    A ticket checkout must not proceed unless:
        - The organiser exists.
        - The organiser is approved.
        - Payout verification is complete.
        - Payouts are enabled.
        - A valid split code is configured.

    IMPORTANT:
        This helper checks local configuration only.

        The onboarding process must separately verify
        the organiser's subaccount and split configuration
        against Paystack.
    """

    if organizer is None:
        raise RuntimeError(
            "Event organiser is missing."
        )

    if not event_organizer_is_approved(organizer):
        raise RuntimeError(
            "Event organiser is not approved."
        )

    verification_status = getattr(
        organizer,
        "payout_verification_status",
        None,
    )

    payout_enabled = getattr(
        organizer,
        "payout_enabled",
        False,
    )

    split_code = getattr(
        organizer,
        "paystack_split_code",
        None,
    )

    if verification_status != "verified":
        raise RuntimeError(
            "Organiser payout verification is incomplete."
        )

    if payout_enabled is not True:
        raise RuntimeError(
            "Organiser payouts are not enabled."
        )

    if (
        not isinstance(split_code, str)
        or not split_code.strip()
    ):
        raise RuntimeError(
            "Organiser Paystack split code is missing."
        )

    split_code = split_code.strip()

    if not split_code.startswith("SPL_"):
        raise RuntimeError(
            "Invalid organiser Paystack split code."
        )

    return split_code

# ============================================================
# RECORD RESTAURANT ANALYTICS EVENT
# ============================================================
"""KALXA Paystack ticket finalisation service.

Requires existing application imports/globals: db, TicketOrder, EntryPass,
generate_entry_code, current_app, datetime, Decimal, ROUND_HALF_UP.
Only pass `transaction_data` obtained from authenticated server-side Paystack
transaction verification. This service does not initiate refunds or settlements.
"""

from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP
from flask import current_app


def finalize_paystack_ticket_order(order, transaction_data):
    """
    Atomically finalize a verified Paystack ticket payment.

    IMPORTANT:
        transaction_data MUST originate from an independent,
        trusted server-side Paystack verification request.

        Never pass unverified webhook or browser data here.

    INVENTORY:
        - Uses the same TicketEvent FOR UPDATE lock as checkout.
        - Recognizes active inventory reservations.
        - Rechecks capacity for expired or legacy reservations.
        - Checks General, ticket-type and sale-phase inventory.
        - Prevents duplicate pass issuance.

    PAYMENT:
        - Verifies reference, currency, amount and transaction ID.
        - Supports idempotent callbacks and webhooks.
        - Records KALXA's 4% expected commission.
        - Does not independently verify Paystack split settlement.

    TRANSACTION:
        Payment state, commission and EntryPass issuance
        are committed together.

    CRITICAL:
        The caller must verify the Paystack transaction
        independently before invoking this function.

        A successful Paystack payment that cannot be
        fulfilled must be escalated for reconciliation.
        It must never silently create excess tickets.
    """

    from collections import defaultdict
    from datetime import datetime
    from decimal import Decimal, InvalidOperation

    # ========================================================
    # 1. VALIDATE VERIFIED TRANSACTION DATA
    # ========================================================

    if not isinstance(transaction_data, dict):
        raise RuntimeError(
            "Invalid Paystack transaction data."
        )

    if transaction_data.get("status") != "success":
        raise RuntimeError(
            "Paystack transaction is not successful."
        )

    reference = transaction_data.get("reference")
    currency = transaction_data.get("currency")
    actual_amount = transaction_data.get("amount")
    transaction_id = transaction_data.get("id")

    if (
        not isinstance(reference, str)
        or not reference.strip()
        or len(reference.strip()) > 200
    ):
        raise RuntimeError(
            "Invalid Paystack payment reference."
        )

    reference = reference.strip()

    if currency != "ZAR":
        raise RuntimeError(
            "Unexpected Paystack currency."
        )

    if (
        isinstance(actual_amount, bool)
        or not isinstance(actual_amount, int)
        or actual_amount <= 0
    ):
        raise RuntimeError(
            "Invalid Paystack payment amount."
        )

    if (
        isinstance(transaction_id, bool)
        or not isinstance(transaction_id, (int, str))
        or not str(transaction_id).strip()
    ):
        raise RuntimeError(
            "Invalid Paystack transaction ID."
        )

    transaction_id = str(transaction_id).strip()

    if len(transaction_id) > 100:
        raise RuntimeError(
            "Paystack transaction ID is too long."
        )

    order_id = getattr(order, "id", None)

    if order_id is None:
        raise RuntimeError(
            "A persisted ticket order is required."
        )

    # ========================================================
    # 2. DEFINE LOCAL INVENTORY HELPERS
    # ========================================================

    def _positive_quantity(value, label):

        if (
            isinstance(value, bool)
            or not isinstance(value, int)
            or value <= 0
        ):
            raise RuntimeError(
                f"Invalid {label}."
            )

        return value

    def _money(value, label):

        try:
            result = Decimal(str(value))
        except (
            InvalidOperation,
            TypeError,
            ValueError,
        ) as exc:
            raise RuntimeError(
                f"Invalid {label}."
            ) from exc

        if not result.is_finite():
            raise RuntimeError(
                f"Invalid {label}."
            )

        if (
            result
            != result.quantize(Decimal("0.01"))
        ):
            raise RuntimeError(
                f"{label} contains fractional cents."
            )

        return result

    def _committed_quantity(
        *,
        event_id,
        ticket_type_id=None,
        sale_phase_id=None,
        general_only=False,
        exclude_order_id=None,
        now,
    ):
        """
        Count paid orders and active reservations.

        General orders may have TicketOrderItem records
        with NULL ticket_type_id or no order items.

        This function is called only while holding
        the event inventory lock.
        """

        query = (
            db.session.query(TicketOrder)
            .filter(
                TicketOrder.event_id == event_id,
            )
            .filter(
                db.or_(
                    TicketOrder.payment_status == "paid",
                    db.and_(
                        TicketOrder.payment_status.in_(
                            ["pending", "processing"]
                        ),
                        TicketOrder.reservation_expires_at > now,
                        TicketOrder.inventory_released_at.is_(None),
                    ),
                )
            )
        )

        if exclude_order_id is not None:
            query = query.filter(
                TicketOrder.id != exclude_order_id
            )

        total = 0

        for existing_order in query.all():

            existing_items = existing_order.order_items

            if general_only:

                if existing_items:

                    total += sum(
                        int(item.quantity or 0)
                        for item in existing_items
                        if item.ticket_type_id is None
                    )

                else:

                    total += int(
                        existing_order.quantity or 0
                    )

                continue

            if ticket_type_id is None:

                total += int(
                    existing_order.quantity or 0
                )

                continue

            for item in existing_items:

                if item.ticket_type_id != ticket_type_id:
                    continue

                if (
                    sale_phase_id is not None
                    and item.sale_phase_id != sale_phase_id
                ):
                    continue

                total += int(item.quantity or 0)

        return total

    # ========================================================
    # 3. BEGIN FINALIZATION TRANSACTION
    # ========================================================

    try:

        # ====================================================
        # 4. RESOLVE EVENT ID
        # ====================================================

        event_id = (
            db.session.query(TicketOrder.event_id)
            .filter(TicketOrder.id == order_id)
            .scalar()
        )

        if event_id is None:
            raise RuntimeError(
                "Ticket order no longer exists."
            )

        # ====================================================
        # 5. LOCK EVENT FIRST
        # ====================================================
        #
        # Lock ordering:
        #
        # 1. TicketEvent
        # 2. TicketOrder
        #
        # This matches inventory reservation checkout.
        # ====================================================

        locked_event = (
            db.session.query(TicketEvent)
            .filter(TicketEvent.id == event_id)
            .populate_existing()
            .with_for_update()
            .one_or_none()
        )

        if locked_event is None:
            raise RuntimeError(
                "Ticket event no longer exists."
            )

        # ====================================================
        # 6. LOCK ORDER
        # ====================================================

        locked_order = (
            db.session.query(TicketOrder)
            .filter(TicketOrder.id == order_id)
            .populate_existing()
            .with_for_update()
            .one_or_none()
        )

        if locked_order is None:
            raise RuntimeError(
                "Ticket order no longer exists."
            )

        order = locked_order

        if order.event_id != locked_event.id:
            raise RuntimeError(
                "Ticket order event mismatch."
            )

        # ====================================================
        # 7. VERIFY PAYMENT IDENTITY
        # ====================================================

        if order.payment_provider != "paystack":
            raise RuntimeError(
                "Ticket order does not use Paystack."
            )

        if order.payment_reference != reference:
            raise RuntimeError(
                "Paystack reference does not match this order."
            )

        checkout_value = (
            order.checkout_amount
            if order.checkout_amount is not None
            else order.total_amount
        )

        checkout_amount = _money(
            checkout_value,
            "checkout amount",
        )

        if checkout_amount <= 0:
            raise RuntimeError(
                "Invalid checkout amount."
            )

        expected_cents = int(
            checkout_amount * Decimal("100")
        )

        if actual_amount != expected_cents:

            current_app.logger.error(
                "[Paystack Finalization] "
                "Amount mismatch order_id=%s "
                "expected=%s actual=%s",
                order.id,
                expected_cents,
                actual_amount,
            )

            raise RuntimeError(
                "Paystack amount does not match the order."
            )

        # ====================================================
        # 8. PREVENT TRANSACTION REUSE
        # ====================================================

        duplicate = (
            db.session.query(TicketOrder.id)
            .filter(
                TicketOrder.paystack_transaction_id
                == transaction_id,
                TicketOrder.id != order.id,
            )
            .first()
        )

        if duplicate is not None:
            raise RuntimeError(
                "Paystack transaction belongs to another order."
            )

        # ====================================================
        # 9. IDEMPOTENT ALREADY-PAID HANDLING
        # ====================================================

        if order.payment_status == "paid":

            if (
                str(order.paystack_transaction_id or "")
                != transaction_id
            ):
                raise RuntimeError(
                    "Paid order transaction mismatch."
                )

            db.session.commit()

            return order

        if order.payment_status not in {
            "pending",
            "processing",
        }:
            raise RuntimeError(
                "Order is not eligible for finalization."
            )

        # ====================================================
        # 10. VALIDATE ORDER QUANTITY
        # ====================================================

        order_quantity = _positive_quantity(
            order.quantity,
            "order quantity",
        )

        items = list(order.order_items)

        if items:

            item_total = sum(
                _positive_quantity(
                    item.quantity,
                    "ticket line quantity",
                )
                for item in items
            )

            if item_total != order_quantity:
                raise RuntimeError(
                    "Order and ticket line quantities differ."
                )

        # ====================================================
        # 11. VALIDATE EXISTING ENTRY PASSES
        # ====================================================

        existing_passes = list(order.entry_passes)

        if len(existing_passes) > order_quantity:
            raise RuntimeError(
                "Order has too many entry passes."
            )

        valid_item_ids = {
            item.id for item in items
        }

        pass_counts = defaultdict(int)

        for entry_pass in existing_passes:

            if entry_pass.order_id != order.id:
                raise RuntimeError(
                    "Entry pass order mismatch."
                )

            if items:

                if (
                    entry_pass.order_item_id
                    not in valid_item_ids
                ):
                    raise RuntimeError(
                        "Entry pass references an invalid order item."
                    )

                pass_counts[
                    entry_pass.order_item_id
                ] += 1

            elif entry_pass.order_item_id is not None:

                raise RuntimeError(
                    "Legacy order has an unexpected order item pass."
                )

        for item in items:

            if pass_counts[item.id] > item.quantity:
                raise RuntimeError(
                    "Ticket item has too many entry passes."
                )

        # ====================================================
        # 12. CHECK RESERVATION STATE
        # ====================================================

        now = datetime.utcnow()

        reservation_active = bool(
            order.inventory_reserved_at is not None
            and order.reservation_expires_at is not None
            and order.reservation_expires_at > now
            and order.inventory_released_at is None
        )

        # ====================================================
        # 13. RECHECK CAPACITY
        # ====================================================
        #
        # Exclude this order from existing commitments.
        #
        # Then verify that its purchased quantity can
        # fit within current event, type and phase limits.
        #
        # This protects against:
        #
        # - Expired reservations.
        # - Legacy orders without reservations.
        # - Reduced ticket capacities.
        # - Competing active reservations.
        # ====================================================

        if items:

            requested_by_type = defaultdict(int)
            requested_by_phase = defaultdict(int)

            for item in items:

                if item.ticket_type_id is None:
                    raise RuntimeError(
                        "Ticket type order has an unassigned line."
                    )

                requested_by_type[
                    item.ticket_type_id
                ] += item.quantity

                if item.sale_phase_id is not None:
                    requested_by_phase[
                        (
                            item.ticket_type_id,
                            item.sale_phase_id,
                        )
                    ] += item.quantity

            for ticket_type_id, requested in (
                requested_by_type.items()
            ):

                ticket_type = db.session.get(
                    TicketType,
                    ticket_type_id,
                )

                if (
                    ticket_type is None
                    or ticket_type.event_id != event_id
                ):
                    raise RuntimeError(
                        "Ticket type no longer belongs to this event."
                    )

                if ticket_type.capacity is not None:

                    committed = _committed_quantity(
                        event_id=event_id,
                        ticket_type_id=ticket_type_id,
                        exclude_order_id=order.id,
                        now=now,
                    )

                    if (
                        committed + requested
                        > ticket_type.capacity
                    ):
                        raise RuntimeError(
                            "Ticket type capacity is exhausted. "
                            "Payment requires reconciliation."
                        )

            for (
                ticket_type_id,
                phase_id,
            ), requested in requested_by_phase.items():

                phase = db.session.get(
                    TicketSalePhase,
                    phase_id,
                )

                if (
                    phase is None
                    or phase.ticket_type_id != ticket_type_id
                ):
                    raise RuntimeError(
                        "Ticket sale phase no longer matches the order."
                    )

                if phase.quantity_limit is not None:

                    committed = _committed_quantity(
                        event_id=event_id,
                        ticket_type_id=ticket_type_id,
                        sale_phase_id=phase_id,
                        exclude_order_id=order.id,
                        now=now,
                    )

                    if (
                        committed + requested
                        > phase.quantity_limit
                    ):
                        raise RuntimeError(
                            "Sale phase capacity is exhausted. "
                            "Payment requires reconciliation."
                        )

        else:

            if locked_event.ticket_capacity is not None:

                committed = _committed_quantity(
                    event_id=event_id,
                    general_only=True,
                    exclude_order_id=order.id,
                    now=now,
                )

                if (
                    committed + order_quantity
                    > locked_event.ticket_capacity
                ):
                    raise RuntimeError(
                        "General ticket capacity is exhausted. "
                        "Payment requires reconciliation."
                    )

        # ====================================================
        # 14. RECORD VERIFIED PAYMENT
        # ====================================================

        order.payment_status = "paid"
        order.paid_at = now
        order.payment_verified_at = now
        order.paystack_transaction_id = transaction_id

        channel = transaction_data.get("channel")

        order.payment_channel = (
            channel.strip()[:50]
            if isinstance(channel, str)
            and channel.strip()
            else None
        )

        # ====================================================
        # 15. RECORD EXPECTED KALXA COMMISSION
        # ====================================================

        order.record_commission(
            rate=Decimal("0.04")
        )

        # ====================================================
        # 16. ISSUE TICKET-TYPE ENTRY PASSES
        # ====================================================

        if items:

            for item in items:

                existing_count = pass_counts[item.id]

                attendee_names = (
                    item.attendee_names
                    if isinstance(item.attendee_names, list)
                    else []
                )

                for attendee_index in range(
                    existing_count,
                    item.quantity,
                ):

                    attendee_name = (
                        attendee_names[attendee_index]
                        if attendee_index < len(attendee_names)
                        else order.customer_name
                    )

                    if (
                        not isinstance(attendee_name, str)
                        or not attendee_name.strip()
                    ):
                        attendee_name = order.customer_name

                    if (
                        not isinstance(attendee_name, str)
                        or not attendee_name.strip()
                    ):
                        raise RuntimeError(
                            "Missing attendee name."
                        )

                    db.session.add(
                        EntryPass(
                            order_id=order.id,
                            order_item_id=item.id,
                            attendee_name=attendee_name.strip(),
                            entry_code=generate_entry_code(),
                            status="valid",
                        )
                    )

        # ====================================================
        # 17. ISSUE LEGACY GENERAL ENTRY PASSES
        # ====================================================

        else:

            customer_name = order.customer_name

            if (
                not isinstance(customer_name, str)
                or not customer_name.strip()
            ):
                raise RuntimeError(
                    "Missing customer name."
                )

            for _ in range(
                order_quantity - len(existing_passes)
            ):

                db.session.add(
                    EntryPass(
                        order_id=order.id,
                        order_item_id=None,
                        attendee_name=customer_name.strip(),
                        entry_code=generate_entry_code(),
                        status="valid",
                    )
                )

        # ====================================================
        # 18. COMMIT PAYMENT AND PASSES ATOMICALLY
        # ====================================================

        db.session.commit()

        current_app.logger.info(
            "[Paystack Finalization] "
            "Paid order_id=%s reference=%s "
            "transaction_id=%s "
            "reservation_active=%s "
            "commission=%s",
            order.id,
            reference,
            transaction_id,
            reservation_active,
            order.commission_amount,
        )

        return order

    # ========================================================
    # 19. ROLLBACK ON FAILURE
    # ========================================================

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            "[Paystack Finalization] "
            "Failed order_id=%s reference=%s",
            order_id,
            reference,
        )

        raise


