def restaurant_notification_copy(
    advert,
):

    title = (
        "🍔 New around you"
    )


    if advert.headline:

        body = (
            f"{advert.business_name}: "
            f"{advert.headline}"
        )

    else:

        body = (
            f"{advert.business_name} "
            "just added something new on Kalxa."
        )


    if advert.area:

        body = (
            f"{body} · {advert.area}"
        )


    return (
        title[:120],
        body[:500],
    )

