# ============================================================
# AUTOMATIC RESTAURANT PUSH
# ============================================================

def send_automatic_restaurant_push(
    advert,
):

    # ========================================================
    # RESTAURANT REQUIRED
    # ========================================================

    if not advert:

        return None


    # ========================================================
    # RESTAURANT MUST BE ACTIVE
    # ========================================================

    if not advert.active:

        current_app.logger.info(
            (
                "[Restaurant Auto Push] "
                "Skipped because restaurant "
                "is inactive "
                "advert_id=%s"
            ),
            advert.id,
        )

        return None


    # ========================================================
    # RESTAURANT OWNER REQUIRED
    # ========================================================
    #
    # IMPORTANT:
    #
    # We require a valid restaurant owner account, but we
    # deliberately DO NOT require:
    #
    #     organizer.is_subscription_active
    #
    # That property belongs to the legacy Organizer SaaS
    # subscription system.
    #
    # Restaurant feature access is now controlled by the
    # RestaurantAdvert Free / Standard / Premium plan.
    # ========================================================

    organizer = (
        advert.organizer
    )


    if not organizer:

        current_app.logger.info(
            (
                "[Restaurant Auto Push] "
                "Skipped because restaurant "
                "has no organizer "
                "advert_id=%s"
            ),
            advert.id,
        )

        return None


    # ========================================================
    # ORGANIZER ACCOUNT MUST BE ACTIVE
    # ========================================================

    if not organizer.active:

        current_app.logger.info(
            (
                "[Restaurant Auto Push] "
                "Skipped because restaurant "
                "owner account is inactive "
                "advert_id=%s "
                "organizer_id=%s"
            ),
            advert.id,
            organizer.id,
        )

        return None


    # ========================================================
    # RESTAURANT ACCOUNT TYPE
    # ========================================================

    account_type = (
        getattr(
            organizer,
            "account_type",
            None,
        )
        or "event"
    )


    if (
        account_type
        != "restaurant"
    ):

        current_app.logger.info(
            (
                "[Restaurant Auto Push] "
                "Skipped because organizer "
                "is not a restaurant account "
                "advert_id=%s "
                "organizer_id=%s"
            ),
            advert.id,
            organizer.id,
        )

        return None


    # ========================================================
    # RESTAURANT PLAN MUST BE ACTIVE
    # ========================================================
    #
    # FREE:
    #
    #     active
    #     no expiry required
    #
    # STANDARD / PREMIUM:
    #
    #     active
    #     future expiry required
    #
    # This is controlled by RestaurantAdvert rather than the
    # old Organizer subscription.
    # ========================================================

    if not advert.is_restaurant_subscription_active:

        current_app.logger.info(
            (
                "[Restaurant Auto Push] "
                "Skipped because restaurant "
                "plan is inactive "
                "advert_id=%s "
                "plan=%s"
            ),
            advert.id,
            advert.normalized_subscription_tier,
        )

        return None


    # ========================================================
    # REEL / DISCOVERY FEATURE
    # ========================================================
    #
    # Restaurant discovery/reel is currently available on:
    #
    #     FREE
    #     STANDARD
    #     PREMIUM
    #
    # Using the feature property keeps this function safe if
    # the plan matrix changes later.
    # ========================================================

    if not advert.can_use_reel:

        current_app.logger.info(
            (
                "[Restaurant Auto Push] "
                "Skipped because restaurant "
                "plan does not allow reels "
                "advert_id=%s "
                "plan=%s"
            ),
            advert.id,
            advert.normalized_subscription_tier,
        )

        return None


    # ========================================================
    # CAMPAIGN START DATE
    # ========================================================

    now = (
        datetime.utcnow()
    )


    if (
        advert.starts_at
        and
        advert.starts_at > now
    ):

        current_app.logger.info(
            (
                "[Restaurant Auto Push] "
                "Skipped because restaurant "
                "campaign has not started "
                "advert_id=%s starts_at=%s"
            ),
            advert.id,
            advert.starts_at,
        )

        return None


    # ========================================================
    # CAMPAIGN END DATE
    # ========================================================

    if (
        advert.ends_at
        and
        advert.ends_at <= now
    ):

        current_app.logger.info(
            (
                "[Restaurant Auto Push] "
                "Skipped because restaurant "
                "campaign has expired "
                "advert_id=%s ends_at=%s"
            ),
            advert.id,
            advert.ends_at,
        )

        return None


    # ========================================================
    # FIREBASE REQUIRED
    # ========================================================

    if not firebase_admin_configured():

        current_app.logger.warning(
            (
                "[Restaurant Auto Push] "
                "Firebase Admin is not configured "
                "advert_id=%s"
            ),
            advert.id,
        )

        return None


    # ========================================================
    # AREA REQUIRED
    # ========================================================

    if not advert.area:

        current_app.logger.info(
            (
                "[Restaurant Auto Push] "
                "Skipped because advert has no area "
                "advert_id=%s"
            ),
            advert.id,
        )

        return None


    # ========================================================
    # PREVENT ACCIDENTAL DUPLICATE AUTO PUSH
    # ========================================================
    #
    # A restaurant advert should not automatically create
    # another push campaign if one has already been created
    # for this advert.
    # ========================================================

    existing_campaign = (
        PushCampaign.query

        .filter_by(
            restaurant_advert_id=(
                advert.id
            ),

            campaign_type=(
                "restaurant"
            ),

            created_by=(
                "restaurant_auto"
            ),
        )

        .filter(
            PushCampaign.status.in_(
                [
                    "draft",
                    "processing",
                    "completed",
                    "partial",
                ]
            )
        )

        .order_by(
            PushCampaign.created_at.desc()
        )

        .first()
    )


    if existing_campaign:

        current_app.logger.info(
            (
                "[Restaurant Auto Push] "
                "Already created "
                "advert_id=%s "
                "campaign_id=%s"
            ),
            advert.id,
            existing_campaign.id,
        )

        return existing_campaign


    # ========================================================
    # AUDIENCE
    # ========================================================

    subscriptions = (
        get_restaurant_push_subscriptions(
            advert
        )
    )


    if not subscriptions:

        current_app.logger.info(
            (
                "[Restaurant Auto Push] "
                "No matching subscribers "
                "advert_id=%s area=%s"
            ),
            advert.id,
            advert.area,
        )

        return None


    # ========================================================
    # NOTIFICATION COPY
    # ========================================================

    (
        title,
        body,
    ) = (
        restaurant_notification_copy(
            advert
        )
    )


    # ========================================================
    # CREATE PUSH CAMPAIGN
    # ========================================================

    campaign = PushCampaign(

        campaign_type=(
            "restaurant"
        ),

        restaurant_advert_id=(
            advert.id
        ),

        event_id=None,

        title=(
            title
        ),

        body=(
            body
        ),

        target_url=(
            url_for(
                "restaurant_page",

                advert_id=(
                    advert.id
                ),

                _external=True,
            )
        ),

        target_mode=(
            "area"
        ),

        target_area=(
            advert.area
        ),

        target_latitude=None,

        target_longitude=None,

        radius_km=None,

        status=(
            "draft"
        ),

        recipient_count=(
            len(
                subscriptions
            )
        ),

        created_by=(
            "restaurant_auto"
        ),
    )


    # ========================================================
    # SAVE CAMPAIGN BEFORE SENDING
    # ========================================================

    try:

        db.session.add(
            campaign
        )

        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Restaurant Auto Push] "
                "Campaign creation failed "
                "advert_id=%s "
                "error=%s"
            ),
            advert.id,
            error,
        )


        return None


    # ========================================================
    # SEND
    # ========================================================

    try:

        send_push_campaign(
            campaign,
            subscriptions,
        )


    except Exception as error:

        db.session.rollback()


        # ----------------------------------------------------
        # RELOAD CAMPAIGN
        # ----------------------------------------------------

        campaign = (
            db.session.get(
                PushCampaign,
                campaign.id,
            )
        )


        # ----------------------------------------------------
        # MARK AS FAILED
        # ----------------------------------------------------

        if campaign:

            campaign.status = (
                "failed"
            )


            try:

                db.session.commit()

            except Exception:

                db.session.rollback()


                current_app.logger.exception(
                    (
                        "[Restaurant Auto Push] "
                        "Unable to mark failed "
                        "campaign "
                        "advert_id=%s "
                        "campaign_id=%s"
                    ),
                    advert.id,
                    campaign.id,
                )


        current_app.logger.exception(
            (
                "[Restaurant Auto Push] "
                "Firebase send failed "
                "advert_id=%s "
                "campaign_id=%s "
                "error=%s"
            ),
            advert.id,
            (
                campaign.id
                if campaign
                else None
            ),
            error,
        )


        return campaign


    # ========================================================
    # FINISHED
    # ========================================================

    current_app.logger.info(
        (
            "[Restaurant Auto Push] "
            "Finished "
            "advert_id=%s "
            "campaign_id=%s "
            "success=%s "
            "failed=%s"
        ),
        advert.id,
        campaign.id,
        campaign.success_count,
        campaign.failure_count,
    )


    return campaign



# ============================================================
# FINALIZE RESTAURANT SUBSCRIPTION PAYMENT
# ============================================================

def finalize_restaurant_subscription_payment(
    payment,
    transaction_data,
):

    # ========================================================
    # PAYMENT REQUIRED
    # ========================================================

    if not payment:

        raise RuntimeError(
            "Restaurant subscription payment was not found."
        )


    # ========================================================
    # IDEMPOTENCY
    # ========================================================
    #
    # The callback and webhook may both try to finalize the
    # same transaction.
    #
    # Never extend the subscription twice.
    # ========================================================

    if payment.payment_status == "paid":

        return payment


    if payment.payment_status == "cancelled":

        raise RuntimeError(
            "This restaurant subscription payment was cancelled."
        )


    # ========================================================
    # TRANSACTION STATUS
    # ========================================================

    transaction_status = (
        str(
            transaction_data.get(
                "status",
                "",
            )
        )
        .strip()
        .lower()
    )


    if transaction_status != "success":

        raise RuntimeError(
            (
                "Paystack transaction is not successful. "
                f"status={transaction_status or 'unknown'}"
            )
        )


    # ========================================================
    # REFERENCE
    # ========================================================

    transaction_reference = (
        str(
            transaction_data.get(
                "reference",
                "",
            )
        )
        .strip()
    )


    if (
        not transaction_reference
        or transaction_reference
        != payment.payment_reference
    ):

        raise RuntimeError(
            "Paystack transaction reference does not match."
        )


    # ========================================================
    # CURRENCY
    # ========================================================

    transaction_currency = (
        str(
            transaction_data.get(
                "currency",
                "",
            )
        )
        .strip()
        .upper()
    )


    expected_currency = (
        payment.currency
        or "ZAR"
    ).strip().upper()


    if transaction_currency != expected_currency:

        raise RuntimeError(
            "Paystack transaction currency does not match."
        )


    # ========================================================
    # AMOUNT
    # ========================================================
    #
    # Paystack returns the amount in cents.
    #
    # R219.00 = 21900
    # R299.00 = 29900
    # ========================================================

    expected_amount_cents = int(
        (
            Decimal(
                str(
                    payment.amount
                )
            )
            * 100
        )
        .quantize(
            Decimal("1"),
            rounding=ROUND_UP,
        )
    )


    try:

        transaction_amount_cents = int(
            transaction_data.get(
                "amount"
            )
        )


    except (
        TypeError,
        ValueError,
    ):

        raise RuntimeError(
            "Paystack transaction amount is invalid."
        )


    if (
        transaction_amount_cents
        != expected_amount_cents
    ):

        raise RuntimeError(
            "Paystack transaction amount does not match."
        )


    # ========================================================
    # VALIDATE PLAN SNAPSHOT
    # ========================================================

    plan_tier = (
        payment.plan_tier
        or ""
    ).strip().lower()


    if plan_tier not in RESTAURANT_PAYABLE_PLANS:

        raise RuntimeError(
            "Restaurant subscription plan is invalid."
        )


    expected_plan = (
        RESTAURANT_PAYABLE_PLANS[
            plan_tier
        ]
    )


    expected_plan_amount = (
        Decimal(
            str(
                expected_plan[
                    "price"
                ]
            )
        )
    )


    payment_amount = (
        Decimal(
            str(
                payment.amount
            )
        )
    )


    if payment_amount != expected_plan_amount:

        raise RuntimeError(
            "Restaurant subscription plan price does not match."
        )


    # ========================================================
    # RESTAURANT
    # ========================================================

    advert = (
        RestaurantAdvert.query
        .filter_by(
            id=payment.restaurant_advert_id,
            organizer_id=payment.organizer_id,
        )
        .first()
    )


    if not advert:

        raise RuntimeError(
            "Restaurant linked to payment was not found."
        )


    # ========================================================
    # ORGANIZER
    # ========================================================

    organizer = (
        Organizer.query
        .filter_by(
            id=payment.organizer_id
        )
        .first()
    )


    if not organizer:

        raise RuntimeError(
            "Restaurant owner was not found."
        )


    if not organizer.active:

        raise RuntimeError(
            "Restaurant owner account is inactive."
        )


    account_type = (
        getattr(
            organizer,
            "account_type",
            None,
        )
        or "event"
    )


    if account_type != "restaurant":

        raise RuntimeError(
            "Payment does not belong to a restaurant account."
        )


    # ========================================================
    # PAYMENT TIME
    # ========================================================

    now = (
        datetime.utcnow()
    )


    # ========================================================
    # SUBSCRIPTION START
    # ========================================================
    #
    # RULE:
    #
    # If the restaurant is renewing the SAME paid plan while
    # still active or within grace, continue from the previous
    # paid expiry date.
    #
    # Example:
    #
    # Premium expired 1 Oct
    # Restaurant pays 3 Oct during grace
    #
    # New period:
    #     1 Oct -> 31 Oct
    #
    # This preserves the restaurant's billing cycle.
    #
    # For:
    #
    #     Free -> Standard
    #     Free -> Premium
    #     Standard -> Premium
    #
    # start a fresh period from payment time.
    # ========================================================

    same_paid_plan = (
        advert.normalized_subscription_tier
        == plan_tier
        and
        plan_tier
        in (
            RESTAURANT_PLAN_STANDARD,
            RESTAURANT_PLAN_PREMIUM,
        )
    )


    if (
        same_paid_plan
        and
        advert.subscription_expires_at
    ):

        subscription_start = (
            advert.subscription_expires_at
        )


    else:

        subscription_start = (
            now
        )


    # ========================================================
    # SUBSCRIPTION END
    # ========================================================

    subscription_end = (
        subscription_start
        +
        timedelta(
            days=payment.period_days
        )
    )


    # ========================================================
    # PAYSTACK AUDIT
    # ========================================================

    transaction_id = (
        transaction_data.get(
            "id"
        )
    )


    payment_channel = (
        transaction_data.get(
            "channel"
        )
    )


    # ========================================================
    # UPDATE PAYMENT
    # ========================================================

    payment.payment_status = (
        "paid"
    )

    payment.paystack_transaction_id = (
        str(transaction_id)
        if transaction_id is not None
        else None
    )

    payment.payment_channel = (
        str(payment_channel)
        if payment_channel
        else None
    )

    payment.payment_verified_at = (
        now
    )

    payment.paid_at = (
        now
    )

    payment.confirmed_at = (
        now
    )

    payment.confirmed_by = (
        "paystack"
    )

    payment.subscription_start = (
        subscription_start
    )

    payment.subscription_end = (
        subscription_end
    )


    # ========================================================
    # ACTIVATE RESTAURANT PLAN
    # ========================================================

    advert.subscription_tier = (
        plan_tier
    )

    advert.subscription_status = (
        "active"
    )

    advert.subscription_started_at = (
        subscription_start
    )

    advert.subscription_expires_at = (
        subscription_end
    )


    # ========================================================
    # COMMIT ATOMICALLY
    # ========================================================

    db.session.commit()


    current_app.logger.info(
        (
            "[Restaurant Subscription] "
            "Payment finalized "
            "restaurant_id=%s "
            "organizer_id=%s "
            "plan=%s "
            "reference=%s "
            "subscription_end=%s"
        ),
        advert.id,
        organizer.id,
        plan_tier,
        payment.payment_reference,
        subscription_end,
    )


    return payment
