def organizer_home_endpoint(
    organizer,
):

    if (
        organizer
        and organizer.account_type
        == "restaurant"
    ):

        return "admin_restaurants"


    return "admin_dashboard"
    
def require_restaurant_organizer():

    auth = (
        require_ticketing_organizer()
    )

    if auth:
        return auth


    organizer = (
        get_current_organizer()
    )


    if (
        not organizer
        or organizer.account_type
        != "restaurant"
    ):

        flash(
            (
                "This area is for "
                "restaurant advertisers."
            ),
            "error",
        )

        return redirect(
            url_for(
                "admin_dashboard"
            )
        )


    return None


def require_event_organizer():

    auth = (
        require_ticketing_organizer()
    )

    if auth:
        return auth


    organizer = (
        get_current_organizer()
    )


    if (
        not organizer
        or organizer.account_type
        != "event"
    ):

        return redirect(
            url_for(
                "admin_restaurants"
            )
        )


    return None
# ============================================================
# FEATURED LISTING HELPERS
# ============================================================

def featured_listing_plan(plan_code):

    plan = FEATURED_LISTING_PLANS.get(
        str(plan_code or "")
        .strip()
        .lower()
    )

    if not plan:
        raise ValueError(
            "Invalid featured listing plan."
        )

    return plan


def generate_featured_listing_reference():

    return (
        "KXFEATURED-"
        + secrets.token_hex(6).upper()
    )


def get_active_featured_listing(event_id):

    now = datetime.utcnow()

    return (
        FeaturedListing.query
        .filter(
            FeaturedListing.event_id
            == event_id,
            FeaturedListing.status
            == "active",
            FeaturedListing.starts_at
            <= now,
            FeaturedListing.ends_at
            > now,
        )
        .order_by(
            FeaturedListing.starts_at.desc()
        )
        .first()
    )


def validate_featured_image_upload(image_file):

    filename = secure_filename(
        image_file.filename or ""
    )

    if (
        not filename
        or "."
        not in filename
    ):
        raise ValueError(
            "Featured posters must be JPG, JPEG, PNG or WEBP images."
        )

    extension = (
        filename
        .rsplit(".", 1)[1]
        .lower()
    )

    mimetypes = {
        "jpg": "image/jpeg",
        "jpeg": "image/jpeg",
        "png": "image/png",
        "webp": "image/webp",
    }

    if extension not in mimetypes:
        raise ValueError(
            "Featured posters must be JPG, JPEG, PNG or WEBP images."
        )

    data = image_file.read()

    if not data:
        raise ValueError(
            "One of the featured poster images is empty."
        )

    if len(data) > FEATURED_IMAGE_MAX_BYTES:
        raise ValueError(
            "Each featured poster must be 5 MB or smaller."
        )

    return {
        "data": data,
        "mimetype": mimetypes[extension],
        "filename": filename,
    }


def finalize_featured_listing_payment(
    listing,
    transaction_data,
):

    if listing.is_active_now:
        return listing

    if (
        not isinstance(
            transaction_data,
            dict,
        )
        or transaction_data.get("status")
        != "success"
    ):
        raise RuntimeError(
            "Paystack featured-listing transaction is not successful."
        )

    reference = str(
        transaction_data.get(
            "reference",
            "",
        )
    ).strip()

    if reference != listing.payment_reference:
        raise RuntimeError(
            "Paystack featured-listing reference does not match."
        )

    expected_amount = int(
        (
            Decimal(
                str(listing.price)
            )
            * 100
        )
        .quantize(
            Decimal("1"),
            rounding=ROUND_UP,
        )
    )

    actual_amount = int(
        transaction_data.get(
            "amount"
        )
        or 0
    )

    if actual_amount != expected_amount:
        raise RuntimeError(
            "Paystack featured-listing amount does not match."
        )

    currency = str(
        transaction_data.get(
            "currency",
            "",
        )
    ).strip().upper()

    if (
        currency
        and currency != "ZAR"
    ):
        raise RuntimeError(
            "Paystack featured-listing currency does not match."
        )

    now = datetime.utcnow()

    listing.status = "active"
    listing.paid_at = now
    listing.payment_verified_at = now
    listing.starts_at = now
    listing.ends_at = (
        now
        + timedelta(
            days=listing.duration_days
        )
    )

    listing.paystack_transaction_id = (
        str(
            transaction_data.get(
                "id"
            )
            or ""
        )
        or None
    )

    listing.payment_channel = (
        transaction_data.get(
            "channel"
        )
        or None
    )

    db.session.commit()

    return listing


# ============================================================
# EVENT BOOST HELPERS
# ============================================================

def generate_event_boost_reference():

    return (
        "KXBOOST-"
        + secrets.token_hex(
            6
        ).upper()
    )


def event_local_datetime(
    event,
):

    if (
        not event.event_date
        or not event.event_time
    ):

        return None


    return datetime.combine(
        event.event_date,
        event.event_time,
    ).replace(
        tzinfo=
            ZoneInfo(
                "Africa/Johannesburg"
            )
    )


def event_datetime_utc_naive(
    event,
):

    local_datetime = (
        event_local_datetime(
            event
        )
    )


    if not local_datetime:

        return None


    return (
        local_datetime
        .astimezone(
            timezone.utc
        )
        .replace(
            tzinfo=None
        )
    )


def event_boost_plan(
    plan_code,
):

    plan = (
        EVENT_BOOST_PLANS.get(
            str(
                plan_code
                or ""
            )
            .strip()
            .lower()
        )
    )


    if not plan:

        raise ValueError(
            "Invalid event boost plan."
        )


    return plan


def build_event_boost_schedule(
    boost,
):

    event = (
        boost.event
    )


    if not event:

        raise RuntimeError(
            "Boost event is missing."
        )


    plan = (
        event_boost_plan(
            boost.plan_code
        )
    )


    now = (
        datetime.utcnow()
    )


    event_utc = (
        event_datetime_utc_naive(
            event
        )
    )


    reminder_times = {
        "launch":
            now,
    }


    if boost.plan_code == "pro":

        if not event_utc:

            raise RuntimeError(
                "Pro boost requires an event date and time."
            )


        event_local = (
            event_local_datetime(
                event
            )
        )


        # Same-day reminder:
        # - evening events: 17:00 SAST ("Tonight")
        # - daytime events: 09:00 SAST ("Today")
        # - very early events: one hour before start
        if event_local.hour >= 17:

            same_day_local = (
                event_local.replace(
                    hour=17,
                    minute=0,
                    second=0,
                    microsecond=0,
                )
            )

        else:

            same_day_local = (
                event_local.replace(
                    hour=9,
                    minute=0,
                    second=0,
                    microsecond=0,
                )
            )


        if same_day_local >= event_local:

            same_day_local = (
                event_local
                - timedelta(
                    hours=1
                )
            )


        same_day_utc = (
            same_day_local
            .astimezone(
                timezone.utc
            )
            .replace(
                tzinfo=None
            )
        )


        reminder_times.update(
            {
                "three_days":
                    event_utc
                    - timedelta(
                        days=3
                    ),

                "tomorrow":
                    event_utc
                    - timedelta(
                        days=1
                    ),

                "tonight":
                    same_day_utc,

                "happening_now":
                    event_utc,
            }
        )


    existing_types = {
        reminder.reminder_type
        for reminder in boost.reminders
    }


    for reminder_type in plan[
        "reminders"
    ]:

        if (
            reminder_type
            in existing_types
        ):

            continue


        scheduled_for = (
            reminder_times[
                reminder_type
            ]
        )


        status = (
            "pending"
        )


        # Never send a countdown that is already obsolete.
        if (
            reminder_type
            != "launch"
            and scheduled_for
            <= now
        ):

            status = (
                "skipped"
            )


        db.session.add(
            EventBoostReminder(
                boost_id=
                    boost.id,

                reminder_type=
                    reminder_type,

                scheduled_for=
                    scheduled_for,

                status=
                    status,

                error_message=(
                    "Scheduled time had already passed "
                    "when the boost was activated."
                    if status == "skipped"
                    else None
                ),
            )
        )


def format_boost_schedule_sast(
    scheduled_for,
):

    if not scheduled_for:

        return "—"


    aware_utc = (
        scheduled_for.replace(
            tzinfo=
                timezone.utc
        )
    )


    local_time = (
        aware_utc.astimezone(
            ZoneInfo(
                "Africa/Johannesburg"
            )
        )
    )


    return (
        local_time.strftime(
            "%d %b %Y %H:%M"
        )
        + " SAST"
    )


def build_local_audience_analytics(
    event,
    radius_km,
):

    if (
        event.notification_latitude is None
        or event.notification_longitude is None
    ):

        return {
            "total":
                0,
            "average_distance_km":
                None,
            "nearest_distance_km":
                None,
            "farthest_distance_km":
                None,
            "areas":
                [],
        }


    area_buckets = {}
    distances = []


    for subscription in (
        get_active_push_subscriptions()
    ):

        if (
            subscription.home_latitude is None
            or subscription.home_longitude is None
        ):

            continue


        distance = (
            haversine_distance_km(
                event.notification_latitude,
                event.notification_longitude,
                subscription.home_latitude,
                subscription.home_longitude,
            )
        )


        if distance > float(
            radius_km
        ):

            continue


        distances.append(
            distance
        )


        area_name = (
            subscription.home_area
            or subscription.home_location_display
            or "Unknown area"
        )


        bucket_key = (
            normalize_area_key(
                area_name
            )
            or "unknown-area"
        )


        bucket = (
            area_buckets.setdefault(
                bucket_key,
                {
                    "name":
                        area_name,
                    "count":
                        0,
                    "distances":
                        [],
                },
            )
        )


        bucket[
            "count"
        ] += 1

        bucket[
            "distances"
        ].append(
            distance
        )


    areas = []


    for bucket in (
        area_buckets.values()
    ):

        bucket_distances = (
            bucket[
                "distances"
            ]
        )


        areas.append(
            {
                "name":
                    bucket[
                        "name"
                    ],

                "count":
                    bucket[
                        "count"
                    ],

                "average_distance_km":
                    round(
                        (
                            sum(
                                bucket_distances
                            )
                            /
                            len(
                                bucket_distances
                            )
                        ),
                        1,
                    ),
            }
        )


    areas.sort(
        key=lambda row: (
            -row[
                "count"
            ],
            row[
                "average_distance_km"
            ],
            row[
                "name"
            ].casefold(),
        )
    )


    if not distances:

        return {
            "total":
                0,
            "average_distance_km":
                None,
            "nearest_distance_km":
                None,
            "farthest_distance_km":
                None,
            "areas":
                [],
        }


    return {
        "total":
            len(
                distances
            ),

        "average_distance_km":
            round(
                sum(
                    distances
                )
                /
                len(
                    distances
                ),
                1,
            ),

        "nearest_distance_km":
            round(
                min(
                    distances
                ),
                1,
            ),

        "farthest_distance_km":
            round(
                max(
                    distances
                ),
                1,
            ),

        "areas":
            areas,
    }


def event_boost_notification_copy(
    event,
    reminder_type,
):

    area = (
        event.notification_area
        or event.venue
        or "your area"
    )


    if reminder_type == "launch":

        return (
            f"🔥 {event.title}",
            (
                f"{event.title} is coming to {area}. "
                "Tap to view event details and tickets."
            ),
        )


    if reminder_type == "three_days":

        return (
            f"🔥 3 DAYS TO GO: {event.title}",
            (
                f"Only 3 days until {event.title} in {area}. "
                "Tap to get your ticket."
            ),
        )


    if reminder_type == "tomorrow":

        return (
            f"⏰ TOMORROW: {event.title}",
            (
                f"{event.title} is happening tomorrow in {area}. "
                "Tap for tickets and event details."
            ),
        )


    if reminder_type == "tonight":

        event_local = (
            event_local_datetime(
                event
            )
        )


        if (
            event_local
            and event_local.hour >= 17
        ):

            return (
                f"🌙 TONIGHT: {event.title}",
                (
                    f"{event.title} is happening tonight in {area}. "
                    "Tap for tickets and event details."
                ),
            )


        return (
            f"📍 TODAY: {event.title}",
            (
                f"{event.title} is happening today in {area}. "
                "Tap for tickets and event details."
            ),
        )


    if reminder_type == "happening_now":

        return (
            f"🔴 HAPPENING NOW: {event.title}",
            (
                f"{event.title} is happening now in {area}. "
                "Tap to open the event."
            ),
        )


    raise ValueError(
        "Unknown boost reminder type."
    )


def execute_event_boost_reminder(
    reminder,
):

    reminder_id = (
        reminder.id
    )


    # Atomically claim one pending reminder.
    # If two workers/cron calls overlap, only one is allowed
    # to change pending -> processing.
    claimed = (
        EventBoostReminder.query
        .filter(
            EventBoostReminder.id
            == reminder_id,
            EventBoostReminder.status
            == "pending",
        )
        .update(
            {
                EventBoostReminder.status:
                    "processing",

                EventBoostReminder.error_message:
                    None,
            },
            synchronize_session=
                False,
        )
    )


    db.session.commit()


    if not claimed:

        return (
            db.session.get(
                EventBoostReminder,
                reminder_id,
            )
        )


    reminder = (
        db.session.get(
            EventBoostReminder,
            reminder_id,
        )
    )


    boost = (
        reminder.boost
    )


    event = (
        boost.event
        if boost
        else None
    )


    if (
        not boost
        or not boost.is_active
        or not event
    ):

        reminder.status = (
            "skipped"
        )

        reminder.error_message = (
            "Boost or event is not active."
        )

        db.session.commit()

        return reminder


    if (
        event.status
        != "published"
        or not event.active
    ):

        reminder.status = (
            "skipped"
        )

        reminder.error_message = (
            "Event is not currently published."
        )

        db.session.commit()

        return reminder


    subscriptions = (
        get_local_push_subscriptions(
            event,
            float(
                boost.radius_km
            ),
        )
    )


    if not subscriptions:

        reminder.status = (
            "skipped"
        )

        reminder.error_message = (
            "No eligible local notification audience."
        )

        db.session.commit()

        return reminder


    (
        title,
        body,
    ) = (
        event_boost_notification_copy(
            event,
            reminder.reminder_type,
        )
    )


    campaign = PushCampaign(

        campaign_type=
            "event",

        restaurant_advert_id=
            None,

        event_id=
            event.id,

        title=
            title[:120],

        body=
            body[:500],

        target_url=
            url_for(
                "event_page",
                event_id=
                    event.id,
                _external=
                    True,
            ),

        target_mode=
            "radius",

        target_area=
            event.notification_area,

        target_latitude=
            event.notification_latitude,

        target_longitude=
            event.notification_longitude,

        radius_km=
            boost.radius_km,

        status=
            "draft",

        recipient_count=
            len(
                subscriptions
            ),

        created_by=(
            "event_boost:"
            + boost.plan_code
            + ":"
            + reminder.reminder_type
        ),
    )


    db.session.add(
        campaign
    )

    db.session.flush()


    reminder.campaign_id = (
        campaign.id
    )


    db.session.commit()


    try:

        send_push_campaign(
            campaign,
            subscriptions,
        )


    except Exception as error:

        db.session.rollback()


        reminder = (
            db.session.get(
                EventBoostReminder,
                reminder.id,
            )
        )


        if reminder:

            reminder.status = (
                "failed"
            )

            reminder.error_message = (
                str(
                    error
                )[:2000]
            )

            db.session.commit()


        raise


    reminder = (
        db.session.get(
            EventBoostReminder,
            reminder.id,
        )
    )


    reminder.status = (
        "sent"
    )

    reminder.sent_at = (
        datetime.utcnow()
    )

    reminder.error_message = (
        None
    )


    db.session.commit()


    return reminder


def process_due_event_boost_reminders(
    boost_id=None,
    limit=25,
):

    query = (
        EventBoostReminder.query
        .join(
            EventBoost,
            EventBoostReminder.boost_id
            == EventBoost.id,
        )
        .filter(
            EventBoost.status
            == "active"
        )
        .filter(
            EventBoostReminder.status
            == "pending"
        )
        .filter(
            EventBoostReminder.scheduled_for
            <= datetime.utcnow()
        )
    )


    if boost_id is not None:

        query = query.filter(
            EventBoostReminder.boost_id
            == boost_id
        )


    reminders = (
        query
        .order_by(
            EventBoostReminder.scheduled_for.asc()
        )
        .limit(
            limit
        )
        .all()
    )


    result = {
        "processed":
            0,

        "sent":
            0,

        "skipped":
            0,

        "failed":
            0,
    }


    for reminder in reminders:

        result[
            "processed"
        ] += 1


        try:

            execute_event_boost_reminder(
                reminder
            )


            db.session.refresh(
                reminder
            )


            if reminder.status == "sent":

                result[
                    "sent"
                ] += 1

            elif reminder.status == "skipped":

                result[
                    "skipped"
                ] += 1


        except Exception as error:

            result[
                "failed"
            ] += 1


            current_app.logger.exception(
                (
                    "[Event Boost] Reminder failed "
                    "reminder_id=%s error=%s"
                ),
                reminder.id,
                error,
            )


    return result


def finalize_event_boost_payment(
    boost,
    transaction_data,
):
    """
    Finalise a verified Paystack Event Boost payment.

    SECURITY:
        - Requires successful Paystack transaction.
        - Requires exact payment reference.
        - Requires exact amount in cents.
        - Requires ZAR currency.
        - Requires a valid transaction ID.
        - Rejects transaction ID reuse across boosts.

    IDEMPOTENCY:
        - Repeated verification of the same payment
          must not create duplicate reminders.

    IMPORTANT:
        This function must only receive transaction
        data retrieved directly from Paystack's
        transaction verification endpoint.

        Never trust payment data submitted by a browser.
    """

    # ========================================================
    # VALIDATE BOOST
    # ========================================================

    if boost is None:

        raise ValueError(
            "Event Boost record is required."
        )

    # ========================================================
    # VALIDATE PAYSTACK RESPONSE
    # ========================================================

    if not isinstance(
        transaction_data,
        dict,
    ):

        raise RuntimeError(
            "Invalid Paystack transaction data."
        )

    if transaction_data.get("status") != "success":

        raise RuntimeError(
            "Paystack boost transaction is not successful."
        )

    # ========================================================
    # VALIDATE REFERENCE
    # ========================================================

    reference = transaction_data.get(
        "reference"
    )

    if (
        not isinstance(reference, str)
        or reference.strip()
        != boost.payment_reference
    ):

        raise RuntimeError(
            "Paystack boost payment reference mismatch."
        )

    # ========================================================
    # VALIDATE CURRENCY
    # ========================================================

    if transaction_data.get("currency") != "ZAR":

        raise RuntimeError(
            "Event Boost payment currency must be ZAR."
        )

    # ========================================================
    # VALIDATE AMOUNT
    # ========================================================

    expected_amount = int(
        (
            Decimal(str(boost.price))
            * Decimal("100")
        ).quantize(
            Decimal("1"),
            rounding=ROUND_UP,
        )
    )

    actual_amount = transaction_data.get(
        "amount"
    )

    if (
        isinstance(actual_amount, bool)
        or not isinstance(actual_amount, int)
        or actual_amount != expected_amount
    ):

        raise RuntimeError(
            "Paystack Event Boost amount mismatch."
        )

    # ========================================================
    # VALIDATE TRANSACTION ID
    # ========================================================

    transaction_id = transaction_data.get(
        "id"
    )

    if (
        isinstance(transaction_id, bool)
        or not isinstance(transaction_id, (str, int))
        or not str(transaction_id).strip()
    ):

        raise RuntimeError(
            "Invalid Paystack transaction ID."
        )

    transaction_id = str(
        transaction_id
    ).strip()

    # ========================================================
    # CHECK TRANSACTION REUSE
    # ========================================================

    existing_boost = (
        EventBoost.query
        .filter(
            EventBoost.paystack_transaction_id
            == transaction_id,

            EventBoost.id
            != boost.id,
        )
        .first()
    )

    if existing_boost is not None:

        raise RuntimeError(
            "Paystack transaction is already assigned "
            "to another Event Boost."
        )

    # ========================================================
    # IDEMPOTENCY
    # ========================================================

    if boost.status == "active":

        if (
            boost.paystack_transaction_id
            != transaction_id
        ):

            raise RuntimeError(
                "Active boost payment transaction mismatch."
            )

        return boost

    if boost.status != "pending":

        raise RuntimeError(
            "Event Boost is not awaiting payment."
        )

    # ========================================================
    # ACTIVATE BOOST
    # ========================================================

    now = datetime.utcnow()

    boost.status = "active"

    boost.paid_at = now

    boost.activated_at = now

    boost.payment_verified_at = now

    boost.paystack_transaction_id = (
        transaction_id
    )

    boost.payment_channel = (
        transaction_data.get("channel")
        or None
    )

    # ========================================================
    # CREATE REMINDER SCHEDULE
    # ========================================================

    build_event_boost_schedule(
        boost
    )

    # ========================================================
    # SAVE
    # ========================================================

    db.session.commit()

    current_app.logger.info(
        (
            "[Event Boost] Payment finalised "
            "boost_id=%s reference=%s "
            "transaction_id=%s plan=%s"
        ),
        boost.id,
        boost.payment_reference,
        transaction_id,
        boost.plan_code,
    )

    return boost
