# ============================================================
# UNIQUE ENTRY CODE
# ============================================================

def generate_entry_code():
    """
    Generate a unique, cryptographically secure
    KALXA ticket entry code.

    Format:
        KX-XXXXXXXX-XXXXXXXX

    Example:
        KX-A7B2C9D4-E5F6G8H9

    Security:
        - Uses Python's secrets module.
        - Uses uppercase letters and numbers.
        - Checks existing database records.
        - Limits collision retries.

    IMPORTANT:
        The EntryPass.entry_code database UNIQUE
        constraint is the final protection against
        duplicate codes.

        This function does not reserve a code.
        Concurrent transactions must still handle
        database uniqueness errors.
    """

    # ========================================================
    # CODE ALPHABET
    # ========================================================

    alphabet = (
        string.ascii_uppercase
        + string.digits
    )

    # ========================================================
    # MAXIMUM GENERATION ATTEMPTS
    # ========================================================

    max_attempts = 10

    # ========================================================
    # GENERATE UNIQUE ENTRY CODE
    # ========================================================

    for _ in range(max_attempts):

        part_one = "".join(
            secrets.choice(alphabet)
            for _ in range(8)
        )

        part_two = "".join(
            secrets.choice(alphabet)
            for _ in range(8)
        )

        code = (
            f"KX-{part_one}-{part_two}"
        )

        # ====================================================
        # CHECK DATABASE
        # ====================================================

        exists = (
            db.session.query(EntryPass.id)
            .filter(
                EntryPass.entry_code == code
            )
            .first()
        )

        if exists is None:

            return code

    # ========================================================
    # COLLISION LIMIT EXCEEDED
    # ========================================================

    current_app.logger.error(
        (
            "[EntryPass] "
            "Unable to generate unique entry code "
            "after %s attempts."
        ),
        max_attempts,
    )

    raise RuntimeError(
        "Unable to generate a unique ticket code."
    )

# ============================================================
# SUPER ADMIN LOGIN
# ============================================================

@app.route(
    "/superadmin/login",
    methods=["GET", "POST"],
)
def superadmin_login():
    """
    Authenticate the KALXA super-admin.

    Successful authentication grants access to
    super-admin-only operations, including
    ticket refund administration.

    Security:
        - Server-configured credentials
        - Password hash verification
        - CSRF protection
        - Session reset after login
        - Secure session identity
    """

    if is_superadmin_authenticated():
        return redirect(
            url_for("superadmin_dashboard")
        )

    if request.method == "GET":
        session["superadmin_login_csrf"] = (
            secrets.token_urlsafe(32)
        )

        return render_template(
            "superadmin/login.html",
            csrf_token=session["superadmin_login_csrf"],
        )

    # ========================================================
    # VALIDATE LOGIN CSRF
    # ========================================================

    submitted_token = request.form.get(
        "csrf_token",
        "",
    )

    expected_token = session.get(
        "superadmin_login_csrf",
        "",
    )

    if (
        not isinstance(submitted_token, str)
        or not isinstance(expected_token, str)
        or not submitted_token
        or not expected_token
        or not secrets.compare_digest(
            submitted_token,
            expected_token,
        )
    ):
        abort(400)

    # ========================================================
    # READ CREDENTIALS
    # ========================================================

    email = normalize_email(
        request.form.get("email", "")
    )

    password = request.form.get(
        "password",
        "",
    )

    # ========================================================
    # CHECK SERVER CONFIGURATION
    # ========================================================

    if (
        not SUPERADMIN_EMAIL
        or not SUPERADMIN_PASSWORD_HASH
    ):
        current_app.logger.error(
            "[Super Admin] Credentials are not configured."
        )

        flash(
            "Super Admin credentials are not configured.",
            "error",
        )

        session["superadmin_login_csrf"] = (
            secrets.token_urlsafe(32)
        )

        return render_template(
            "superadmin/login.html",
            csrf_token=session["superadmin_login_csrf"],
        ), 503

    # ========================================================
    # VERIFY CREDENTIALS
    # ========================================================

    email_ok = secrets.compare_digest(
        email,
        SUPERADMIN_EMAIL,
    )

    password_ok = (
        check_password_hash(
            SUPERADMIN_PASSWORD_HASH,
            password,
        )
        if password
        else False
    )

    if not email_ok or not password_ok:
        current_app.logger.warning(
            "[Super Admin] Invalid login attempt."
        )

        flash(
            "Invalid Super Admin credentials.",
            "error",
        )

        session["superadmin_login_csrf"] = (
            secrets.token_urlsafe(32)
        )

        return render_template(
            "superadmin/login.html",
            csrf_token=session["superadmin_login_csrf"],
        ), 401

    # ========================================================
    # ESTABLISH AUTHENTICATED SESSION
    # ========================================================

    session.clear()

    session[SUPERADMIN_SESSION_KEY] = True

    session["superadmin_authenticated_at"] = (
        datetime.utcnow().isoformat()
    )

    session.permanent = True

    current_app.logger.info(
        "[Super Admin] Login successful."
    )

    return redirect(
        url_for("superadmin_dashboard")
    )

# ============================================================
# SUPER ADMIN LOGOUT
# ============================================================

@app.route(
    "/superadmin/logout",
    methods=["POST"],
)
def superadmin_logout():
    """
    End the KALXA super-admin session.

    POST-only logout prevents ordinary GET links
    from ending the session.
    """

    if not is_superadmin_authenticated():
        abort(403)

    expected_token = session.get(
        "superadmin_csrf_token",
        "",
    )

    submitted_token = (
        request.form.get("csrf_token")
        or request.headers.get("X-CSRF-Token")
        or ""
    )

    if (
        not expected_token
        or not submitted_token
        or not secrets.compare_digest(
            str(expected_token),
            str(submitted_token),
        )
    ):
        abort(400)

    session.clear()

    return redirect(
        url_for("superadmin_login")
    )


def kalxa_refund_superadmin_guard():
    """
    Authenticate refund administration requests.

    Returns:
        Super-admin identity when authenticated.
        None otherwise.

    Never trust role information supplied by
    request parameters or JSON.
    """

    if not is_superadmin_authenticated():
        return None

    if session.get(SUPERADMIN_SESSION_KEY) is not True:
        return None

    if not SUPERADMIN_EMAIL:
        return None

    return normalize_email(SUPERADMIN_EMAIL)

