# ============================================================
@app.route(
    "/superadmin/partners/new",
    methods=["GET", "POST"],
)
def superadmin_create_partner():

    # ========================================================
    # AUTHENTICATION
    # ========================================================

    auth = require_superadmin()

    if auth:
        return auth

    # ========================================================
    # PARTNER CONFIGURATION
    # ========================================================

    partner_configs = {

        "event": {
            "days": KALXA_PARTNER_ACCESS_DAYS,
            "plan_name": KALXA_PARTNER_PLAN_NAME,
            "label": "Event Organizer",
        },

        "restaurant": {
            "days": 90,
            "plan_name": (
                "Kalxa Restaurant Community "
                "Partner - Premium"
            ),
            "label": "Restaurant",
        },

    }

    # ========================================================
    # ACCOUNT TYPE
    # ========================================================

    if request.method == "POST":

        account_type = (
            request.form.get(
                "account_type",
                "event",
            )
            .strip()
            .lower()
        )

    else:

        account_type = (
            request.args.get(
                "account_type",
                "event",
            )
            .strip()
            .lower()
        )

    if account_type not in partner_configs:

        flash(
            "Invalid partner account type.",
            "error",
        )

        return redirect(
            url_for(
                "superadmin_create_partner",
                account_type="event",
            )
        )

    config = partner_configs[account_type]

    partner_days = config["days"]
    partner_plan_name = config["plan_name"]
    partner_label = config["label"]

    # ========================================================
    # POST REQUEST
    # ========================================================

    if request.method == "POST":

        name = (
            request.form.get("name", "")
            .strip()
        )

        business_name = (
            request.form.get("business_name", "")
            .strip()
        )

        email = normalize_email(
            request.form.get("email", "")
        )

        phone = (
            request.form.get("phone", "")
            .strip()
            or None
        )

        # ====================================================
        # VALIDATION
        # ========================================================

        if not name:

            flash(
                "Account holder name is required.",
                "error",
            )

            return render_template(
                "superadmin/partner_form.html",
                account_type=account_type,
            )

        if not business_name:

            flash(
                "Business name is required.",
                "error",
            )

            return render_template(
                "superadmin/partner_form.html",
                account_type=account_type,
            )

        if not email:

            flash(
                "Email address is required.",
                "error",
            )

            return render_template(
                "superadmin/partner_form.html",
                account_type=account_type,
            )

        # ====================================================
        # DUPLICATE ACCOUNT CHECK
        # ========================================================

        existing_organizer = (
            Organizer.query
            .filter_by(email=email)
            .first()
        )

        if existing_organizer:

            flash(
                "A Kalxa account already uses this email.",
                "error",
            )

            return redirect(
                url_for(
                    "superadmin_organizer_detail",
                    organizer_id=existing_organizer.id,
                )
            )

        # ====================================================
        # PARTNERSHIP PERIOD
        # ========================================================

        now = datetime.utcnow()

        subscription_end = (
            now + timedelta(days=partner_days)
        )

        temporary_password = (
            generate_partner_temporary_password()
        )

        # ====================================================
        # CREATE ACCOUNT
        # ========================================================

        organizer = Organizer(

            name=name,
            business_name=business_name,
            email=email,
            phone=phone,

            account_type=account_type,

            active=True,

            subscription_status="active",
            subscription_started_at=now,
            subscription_expires_at=subscription_end,

        )

        if account_type == "event":

            organizer.approval_status = "approved"
            organizer.approved_at = now

            organizer.approved_by = (
                "superadmin_partner_grant"
            )

        organizer.set_password(
            temporary_password
        )

        restaurant_advert = None

        # ====================================================
        # DATABASE TRANSACTION
        # ========================================================

        try:

            db.session.add(organizer)

            # Flush generates organizer.id.
            # The restaurant profile must use this ID.

            db.session.flush()

            # =================================================
            # COMPLIMENTARY PARTNER GRANT
            # =================================================

            partner_payment = SubscriptionPayment(

                organizer_id=organizer.id,

                plan_name=partner_plan_name,

                amount=Decimal("0.00"),

                period_days=partner_days,

                payment_reference=(
                    generate_subscription_payment_reference()
                ),

                payment_method="partner_grant",

                payment_status="paid",

                paid_at=now,

                confirmed_at=now,

                confirmed_by="superadmin_partner_grant",

                subscription_start=now,
                subscription_end=subscription_end,

            )

            db.session.add(partner_payment)

            # =================================================
            # RESTAURANT PARTNER — PREMIUM PROFILE
            # =================================================

            if account_type == "restaurant":

                restaurant_advert = RestaurantAdvert(

                    # CRITICAL:
                    # Assign ownership to the newly
                    # created restaurant account.

                    organizer_id=organizer.id,

                    business_name=business_name,

                    headline=None,
                    description=None,

                    phone_number=phone,
                    whatsapp_number=phone,

                    # Complimentary Premium entitlement.

                    subscription_tier=(
                        RESTAURANT_PLAN_PREMIUM
                    ),

                    subscription_status="active",

                    subscription_started_at=now,
                    subscription_expires_at=subscription_end,

                    # This controls public visibility.
                    # It must NOT prevent the owner
                    # from editing the profile.

                    active=False,

                    starts_at=now,

                    # Do not automatically remove the
                    # restaurant's public profile when
                    # Premium access expires.
                    #
                    # Premium feature expiry is controlled
                    # separately by subscription_expires_at.

                    ends_at=None,

                )

                db.session.add(restaurant_advert)
                db.session.flush()

                current_app.logger.info(
                    (
                        "[Restaurant Partner] "
                        "Linked premium restaurant profile "
                        "advert_id=%s organizer_id=%s"
                    ),
                    restaurant_advert.id,
                    organizer.id,
                )

            # =================================================
            # COMMIT
            # =================================================

            db.session.commit()

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                (
                    "[%s Partner] "
                    "Unable to create partner email=%s"
                ),
                partner_label,
                email,
            )

            flash(
                "Partner account could not be created.",
                "error",
            )

            return render_template(
                "superadmin/partner_form.html",
                account_type=account_type,
            )

        # ====================================================
        # SUCCESS
        # =================================================

        response = make_response(
            render_template(

                "superadmin/partner_created.html",

                organizer=organizer,
                restaurant_advert=restaurant_advert,

                temporary_password=temporary_password,

                subscription_end=subscription_end,

                account_type=account_type,
                partner_days=partner_days,
                partner_label=partner_label,

            )
        )

        response.headers["Cache-Control"] = (
            "no-store, no-cache, max-age=0, must-revalidate"
        )

        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
        response.headers["X-Content-Type-Options"] = "nosniff"
        response.headers["Referrer-Policy"] = "no-referrer"

        return response

    # ========================================================
    # GET REQUEST
    # ========================================================

    return render_template(
        "superadmin/partner_form.html",
        account_type=account_type,
    )
    
@app.route(
    "/admin/restaurants/<int:advert_id>/subscription/reconcile/<int:payment_id>",
    methods=["POST"],
)
def admin_reconcile_yoco_restaurant_subscription(
    advert_id,
    payment_id,
):
    auth = require_ticketing_organizer()

    if auth:
        return auth

    organizer = get_current_organizer()

    if organizer is None:
        return redirect(url_for("organizer_login"))

    payment = (
        RestaurantSubscriptionPayment.query
        .filter_by(
            id=payment_id,
            restaurant_advert_id=advert_id,
            organizer_id=organizer.id,
            payment_method="yoco",
        )
        .first_or_404()
    )

    try:
        result = verify_and_activate_yoco_subscription(
            kind="restaurant",
            payment_id=payment.id,
            source="reconciliation",
        )

    except Exception:
        db.session.rollback()

        current_app.logger.exception(
            "[Yoco] Restaurant reconciliation failed."
        )

        flash(
            "Could not verify your payment. "
            "Please try again later.",
            "error",
        )

    else:
        if result == "activated":
            flash(
                "Your restaurant subscription is active.",
                "success",
            )

        elif result == "already_processed":
            flash(
                "This payment was already confirmed.",
                "info",
            )

        elif result == "pending":
            flash(
                "Yoco has not completed this checkout.",
                "info",
            )

        else:
            flash(
                "Payment verification was unsuccessful.",
                "error",
            )

    return redirect(
        url_for(
            "admin_manage_restaurant",
            advert_id=advert_id,
        )
    )



