@app.route(
    "/superadmin"
)
def superadmin_dashboard():

    auth = (
        require_superadmin()
    )


    if auth:

        return auth


    now = (
        datetime.utcnow()
    )


    # ========================================================
    # ORGANIZERS
    # ========================================================

    total_organizers = (
        Organizer.query.count()
    )


    active_subscriptions = (
        Organizer.query

        .filter(
            Organizer.active.is_(
                True
            )
        )

        .filter(
            Organizer.subscription_status
            == "active"
        )

        .filter(
            Organizer.subscription_expires_at
            > now
        )

        .count()
    )


    suspended_organizers = (
        Organizer.query

        .filter(
            Organizer.subscription_status
            == "suspended"
        )

        .count()
    )


    inactive_or_expired = (
        total_organizers
        - active_subscriptions
        - suspended_organizers
    )


    recent_organizers = (
        Organizer.query

        .order_by(
            Organizer.created_at.desc()
        )

        .limit(10)

        .all()
    )


    # ========================================================
    # SUBSCRIPTION PAYMENTS
    # ========================================================

    pending_subscription_payments = (
        SubscriptionPayment.query

        .filter_by(
            payment_status=
                "pending"
        )

        .order_by(
            SubscriptionPayment.created_at.asc()
        )

        .limit(20)

        .all()
    )


    pending_subscription_count = (
        SubscriptionPayment.query

        .filter_by(
            payment_status=
                "pending"
        )

        .count()
    )


    # ========================================================
    # RESTAURANT EXPERIENCE POSTS WAITING FOR MODERATION
    # ========================================================

    pending_restaurant_experiences = (
        RestaurantExperiencePost.query

        .filter(
            RestaurantExperiencePost.moderation_status
            == "pending"
        )

        .order_by(
            RestaurantExperiencePost.created_at.asc()
        )

        .limit(20)

        .all()
    )


    pending_restaurant_experience_count = (
        RestaurantExperiencePost.query

        .filter(
            RestaurantExperiencePost.moderation_status
            == "pending"
        )

        .count()
    )


    # ========================================================
    # EVENTS READY FOR PUSH
    # ========================================================

    promoted_event_ids = (

        db.session.query(
            PushCampaign.event_id
        )

        .filter(
            PushCampaign.event_id.isnot(
                None
            )
        )

        .filter(
            PushCampaign.status.in_(
                [
                    "completed",
                    "partial",
                ]
            )
        )

        .distinct()

        .subquery()
    )


    notification_ready_events = (
        TicketEvent.query

        .filter(
            TicketEvent.status
            == "published"
        )

        .filter(
            TicketEvent.active.is_(
                True
            )
        )

        .filter(
            ~TicketEvent.id.in_(
                db.select(
                    promoted_event_ids.c.event_id
                )
            )
        )

        .order_by(
            TicketEvent.published_at.desc(),
            TicketEvent.created_at.desc(),
        )

        .limit(20)

        .all()
    )


    # ========================================================
    # RESTAURANT ADVERTS READY FOR PUSH
    # ========================================================

    promoted_restaurant_ids = (

        db.session.query(
            PushCampaign.restaurant_advert_id
        )

        .filter(
            PushCampaign.restaurant_advert_id.isnot(
                None
            )
        )

        .filter(
            PushCampaign.status.in_(
                [
                    "completed",
                    "partial",
                ]
            )
        )

        .distinct()

        .subquery()
    )


    notification_ready_restaurants = (

        RestaurantAdvert.query

        .join(
            Organizer,
            RestaurantAdvert.organizer_id
            == Organizer.id,
        )

        .filter(
            RestaurantAdvert.active.is_(
                True
            )
        )

        .filter(
            Organizer.subscription_status
            == "active"
        )

        .filter(
            Organizer.subscription_expires_at
            > now
        )

        .filter(
            ~RestaurantAdvert.id.in_(
                db.select(
                    promoted_restaurant_ids
                    .c
                    .restaurant_advert_id
                )
            )
        )

        .order_by(
            RestaurantAdvert.created_at.desc()
        )

        .limit(20)

        .all()
    )


    notification_ready_restaurant_count = (
        len(
            notification_ready_restaurants
        )
    )


    notification_ready_count = (
        len(
            notification_ready_events
        )
    )


    active_push_audience_count = (
        len(
            get_active_push_subscriptions()
        )
    )


    return render_template(
        "superadmin/dashboard.html",

        total_organizers=
            total_organizers,

        active_subscriptions=
            active_subscriptions,

        notification_ready_restaurants=
            notification_ready_restaurants,

        notification_ready_restaurant_count=
            notification_ready_restaurant_count,

        suspended_organizers=
            suspended_organizers,

        inactive_or_expired=
            max(
                0,
                inactive_or_expired,
            ),

        recent_organizers=
            recent_organizers,

        pending_subscription_payments=
            pending_subscription_payments,

        pending_subscription_count=
            pending_subscription_count,

        notification_ready_events=
            notification_ready_events,

        notification_ready_count=
            notification_ready_count,

        active_push_audience_count=
            active_push_audience_count,

        # NEW
        pending_restaurant_experiences=
            pending_restaurant_experiences,

        pending_restaurant_experience_count=
            pending_restaurant_experience_count,

        subscription_plan_name=
            KALXA_SUBSCRIPTION_PLAN_NAME,

        subscription_price=
            KALXA_SUBSCRIPTION_PRICE,
    )


# ============================================================
# SUPER ADMIN — SETTLEMENT RECONCILIATION
# Add to app.py after superadmin_dashboard()
# ============================================================

# Prevent overlapping manual runs within one Python process.
# Multiple Render/Gunicorn workers require an additional
# database-level or distributed lock for full protection.
_settlement_reconciliation_lock = threading.Lock()


def _kalxa_settlement_csrf_token():
    """
    Session-bound token for this specific admin action.

    If your app already has global Flask-WTF CSRF protection,
    use its existing csrf_token() mechanism instead.
    """
    token = session.get("_settlement_reconciliation_csrf")

    if not isinstance(token, str) or not token:
        token = secrets.token_urlsafe(32)
        session["_settlement_reconciliation_csrf"] = token

    return token


def _kalxa_verify_settlement_csrf():
    expected = session.get("_settlement_reconciliation_csrf")
    supplied = request.form.get("csrf_token", "")

    if (
        not isinstance(expected, str)
        or not isinstance(supplied, str)
        or not expected
        or not hmac.compare_digest(expected, supplied)
    ):
        abort(400, description="Invalid reconciliation request.")


def _kalxa_settlement_test_mode():
    """
    Never expose or log the secret key.

    Test-mode processing requires a Paystack test secret.
    """
    key = str(PAYSTACK_SECRET_KEY or "").strip()
    return key.startswith("sk_test_")


