# ============================================================
# SUPER ADMIN - PUSH NOTIFICATION CENTRE
# ============================================================

@app.route(
    "/superadmin/notifications"
)
def superadmin_notifications():

    auth = (
        require_superadmin()
    )


    if auth:

        return auth


    active_subscriptions = (
        get_active_push_subscriptions()
    )


    audience_count = (
        len(
            active_subscriptions
        )
    )


    opted_in_contacts = (
        AttendeeContact.query
        .filter(
            AttendeeContact.notification_consent
            .is_(True)
        )
        .filter(
            AttendeeContact.opted_out_at
            .is_(None)
        )
        .count()
    )


    published_events = (
        TicketEvent.query
        .filter_by(
            status=
                "published",

            active=
                True,
        )
        .order_by(
            TicketEvent.published_at.desc(),
            TicketEvent.created_at.desc(),
        )
        .limit(50)
        .all()
    )

# ========================================================
# ACTIVE RESTAURANT ADVERTS
# ========================================================

    now = (
        datetime.utcnow()
    )


    restaurant_adverts = (
        RestaurantAdvert.query

        .join(
          Organizer,
          RestaurantAdvert.organizer_id
          == Organizer.id,
        )

        .filter(
          RestaurantAdvert.active.is_(
            True
          )
        )

        .filter(
          Organizer.active.is_(
            True
          )
        )

        .filter(
          Organizer.subscription_status
          == "active"
        )

        .filter(
          Organizer.subscription_expires_at
          > now
        )

        .filter(
          or_(
            RestaurantAdvert.starts_at.is_(
                None
            ),

            RestaurantAdvert.starts_at
            <= now,
          )
        )

        .filter(
          or_(
            RestaurantAdvert.ends_at.is_(
                None
            ),

            RestaurantAdvert.ends_at
            > now,
          )
        )

        .order_by(
          RestaurantAdvert.created_at.desc()
        )

        .limit(50)

        .all()
    )

    restaurant_audience_counts = {

      advert.id:
        len(
            get_restaurant_push_subscriptions(
                advert
            )
        )

      for advert in restaurant_adverts
    }

    selected_restaurant = None


    selected_restaurant_id = (
      request.args.get(
        "restaurant_id",
        type=int,
      )
    )


    if selected_restaurant_id:

      selected_restaurant = (
        RestaurantAdvert.query

        .join(
            Organizer,
            RestaurantAdvert.organizer_id
            == Organizer.id,
        )

        .filter(
            RestaurantAdvert.id
            == selected_restaurant_id
        )

        .filter(
            RestaurantAdvert.active.is_(
                True
            )
        )

        .filter(
            Organizer.subscription_status
            == "active"
        )

        .filter(
            Organizer.subscription_expires_at
            > datetime.utcnow()
        )

        .first()
      )


    campaigns = (
        PushCampaign.query
        .order_by(
            PushCampaign.created_at.desc()
        )
        .limit(30)
        .all()
    )


    selected_event = None


    selected_event_id = request.args.get(
        "event_id",
        type=int,
    )


    if selected_event_id:

        selected_event = (
            TicketEvent.query
            .filter_by(
                id=
                    selected_event_id,

                status=
                    "published",

                active=
                    True,
            )
            .first()
        )


    local_audience_counts = {
        event.id:
            len(
                get_local_push_subscriptions(
                    event,
                    LOCAL_NOTIFICATION_RADIUS_KM,
                )
            )
        for event in published_events
    }

    selected_local_audience_count = (
        local_audience_counts.get(
            selected_event.id,
            0,
        )
        if selected_event
        else 0
    )

    selected_restaurant_audience_count = (

      restaurant_audience_counts.get(
        selected_restaurant.id,
        0,
      )

      if selected_restaurant
      else 0
    )


    return render_template(
        "superadmin/notifications.html",

        audience_count=
            audience_count,

        opted_in_contacts=
            opted_in_contacts,

        published_events=
            published_events,

        campaigns=
            campaigns,

        selected_event=
            selected_event,

        firebase_admin_ready=
            firebase_admin_configured(),

        local_audience_counts=
            local_audience_counts,

        selected_local_audience_count=
            selected_local_audience_count,

        restaurant_adverts=
            restaurant_adverts,

        selected_restaurant=
            selected_restaurant,

        restaurant_audience_counts=
            restaurant_audience_counts,

        selected_restaurant_audience_count=
            selected_restaurant_audience_count,

        local_notification_radius_km=
            LOCAL_NOTIFICATION_RADIUS_KM,
    )


# ============================================================
# SUPER ADMIN - SEND PUSH NOTIFICATION
# ============================================================

@app.route(
    "/superadmin/notifications/send",
    methods=[
        "POST",
    ],
)
def superadmin_send_notification():

    auth = (
        require_superadmin()
    )


    if auth:

        return auth


    if not firebase_admin_configured():

        flash(
            (
                "Server-side Firebase sending is not "
                "configured. Add "
                "FIREBASE_SERVICE_ACCOUNT_JSON "
                "to Render first."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications"
            )
        )


    event_id = request.form.get(
        "event_id",
        type=int,
    )


    title = (
        request.form.get(
            "title",
            "",
        )
        .strip()
    )


    body = (
        request.form.get(
            "body",
            "",
        )
        .strip()
    )


    if not event_id:

        flash(
            "Choose a published event.",
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications"
            )
        )


    event = (
        TicketEvent.query
        .filter_by(
            id=
                event_id,

            status=
                "published",

            active=
                True,
        )
        .first()
    )


    if not event:

        flash(
            (
                "The selected event is not "
                "currently published."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications"
            )
        )


    if not title:

        flash(
            "Notification title is required.",
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",
                event_id=
                    event.id,
            )
        )


    if not body:

        flash(
            "Notification message is required.",
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",
                event_id=
                    event.id,
            )
        )


    if len(title) > 120:

        flash(
            (
                "Notification title must be "
                "120 characters or fewer."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",
                event_id=
                    event.id,
            )
        )


    if len(body) > 500:

        flash(
            (
                "Notification message must be "
                "500 characters or fewer."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",
                event_id=
                    event.id,
            )
        )


    if (
        event.notification_latitude is None
        or event.notification_longitude is None
    ):

        flash(
            "This event does not have a resolved "
            "notification area yet. Edit the event first.",
            "error",
        )

        return redirect(
            url_for(
                "superadmin_notifications",
                event_id=event.id,
            )
        )

    subscriptions = (
        get_local_push_subscriptions(
            event,
            LOCAL_NOTIFICATION_RADIUS_KM,
        )
    )

    if not subscriptions:

        flash(
            (
                "No active notification subscribers are "
                f"within {LOCAL_NOTIFICATION_RADIUS_KM:g} km "
                "of this event."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",
                event_id=
                    event.id,
            )
        )


    target_url = (
        url_for(
            "event_page",
            event_id=
                event.id,

            _external=
                True,
        )
    )


    campaign = PushCampaign(

        campaign_type=
            "event",

        event_id=
            event.id,

        title=
            title,

        body=
            body,

        target_url=
            target_url,

        target_mode=
            "radius",

        target_area=
            event.notification_area,

        target_latitude=
            event.notification_latitude,

        target_longitude=
            event.notification_longitude,

        radius_km=
            Decimal(
                str(
                    LOCAL_NOTIFICATION_RADIUS_KM
                )
            ),

        status=
            "draft",

        recipient_count=
            len(
                subscriptions
            ),

        created_by=
            "superadmin",
    )


    try:

        db.session.add(
            campaign
        )

        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Push Campaign] Failed to "
                "create campaign event_id=%s "
                "error=%s"
            ),
            event.id,
            error,
        )


        flash(
            (
                "Notification campaign could not "
                "be created."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",
                event_id=
                    event.id,
            )
        )


    try:

        send_push_campaign(
            campaign,
            subscriptions,
        )


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Push Campaign] Send failed "
                "campaign_id=%s error=%s"
            ),
            campaign.id,
            error,
        )


        campaign = (
            db.session.get(
                PushCampaign,
                campaign.id,
            )
        )


        if campaign:

            campaign.status = (
                "failed"
            )


            try:

                db.session.commit()

            except Exception:

                db.session.rollback()


        flash(
            (
                "Firebase could not send the "
                "notification campaign. Check "
                "the Render logs for the error."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",
                event_id=
                    event.id,
            )
        )


    if campaign.failure_count:

        flash(
            (
                "Notification campaign finished. "
                f"{campaign.success_count} sent, "
                f"{campaign.failure_count} failed."
            ),
            "success",
        )


    else:

        flash(
            (
                "Notification sent successfully "
                f"to {campaign.success_count} "
                "browser subscription(s)."
            ),
            "success",
        )


    return redirect(
        url_for(
            "superadmin_notifications",
            event_id=
                event.id,
        )
    )


