# ============================================================
# SUPER ADMIN - ORGANIZER PROFILE
# ============================================================
@app.route(
    "/superadmin/organizers/<int:organizer_id>"
)
def superadmin_organizer_detail(
    organizer_id,
):
    auth = require_superadmin()

    if auth:
        return auth

    organizer = db.session.get(
        Organizer,
        organizer_id,
    )

    if not organizer:
        abort(404)

    events = (
        TicketEvent.query
        .filter_by(
            organizer_id=organizer.id,
            organizer_deleted=False,
        )
        .order_by(
            TicketEvent.created_at.desc()
        )
        .all()
    )

    orders = (
        TicketOrder.query
        .join(
            TicketEvent,
            TicketOrder.event_id
            == TicketEvent.id,
        )
        .filter(
            TicketEvent.organizer_id
            == organizer.id
        )
        .order_by(
            TicketOrder.created_at.desc()
        )
        .all()
    )

    paid_orders = sum(
        1
        for order in orders
        if order.payment_status == "paid"
    )

    paid_tickets = sum(
        (
            order.quantity
            or 0
        )
        for order in orders
        if order.payment_status == "paid"
    )

    subscription_payments = (
        SubscriptionPayment.query
        .filter_by(
            organizer_id=organizer.id
        )
        .order_by(
            SubscriptionPayment.created_at.desc()
        )
        .all()
    )

    # --------------------------------------------------------
    # RESTAURANT SUBSCRIPTION
    # --------------------------------------------------------
    #
    # Restaurant subscription plans belong to RestaurantAdvert.
    # They are separate from event-organizer subscriptions.
    # --------------------------------------------------------

    restaurant_advert = None

    if (
        organizer.normalized_account_type
        == "restaurant"
    ):
        restaurant_advert = (
            RestaurantAdvert.query
            .filter_by(
                organizer_id=organizer.id
            )
            .first()
        )

    return render_template(
        "superadmin/organizer_detail.html",

        organizer=organizer,

        events=events,

        orders=orders,

        paid_orders=paid_orders,

        paid_tickets=paid_tickets,

        subscription_payments=subscription_payments,

        subscription_plan_name=KALXA_SUBSCRIPTION_PLAN_NAME,

        subscription_price=KALXA_SUBSCRIPTION_PRICE,

        restaurant_advert=restaurant_advert,
    )


# ============================================================
# SUPER ADMIN: UPDATE RESTAURANT SUBSCRIPTION PLAN
# ============================================================

@app.route(
    "/superadmin/organizers/<int:organizer_id>/restaurant-plan",
    methods=["POST"],
)
def superadmin_update_restaurant_plan(
    organizer_id,
):
    auth = require_superadmin()

    if auth:
        return auth

    organizer = db.session.get(
        Organizer,
        organizer_id,
    )

    if not organizer:
        abort(404)

    # --------------------------------------------------------
    # RESTAURANT ACCOUNTS ONLY
    # --------------------------------------------------------

    if (
        organizer.normalized_account_type
        != "restaurant"
    ):
        abort(403)

    advert = (
        RestaurantAdvert.query
        .filter_by(
            organizer_id=organizer.id
        )
        .first()
    )

    if not advert:
        flash(
            "No restaurant profile exists for this account. "
            "Create its restaurant profile before assigning "
            "a restaurant subscription plan.",
            "error",
        )

        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=organizer.id,
            )
        )

    # --------------------------------------------------------
    # VALIDATE SELECTED PLAN
    # --------------------------------------------------------

    selected_plan = (
        request.form.get(
            "subscription_tier",
            "",
        )
        .strip()
        .lower()
    )

    allowed_plans = {
        RESTAURANT_PLAN_FREE,
        RESTAURANT_PLAN_STANDARD,
        RESTAURANT_PLAN_PREMIUM,
    }

    if selected_plan not in allowed_plans:
        flash(
            "Please select a valid restaurant subscription plan.",
            "error",
        )

        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=organizer.id,
            )
        )

    # --------------------------------------------------------
    # FREE PLAN
    # --------------------------------------------------------
    #
    # Free has no expiry date.
    # Existing restaurant content is preserved.
    # --------------------------------------------------------

    if selected_plan == RESTAURANT_PLAN_FREE:

        advert.subscription_tier = (
            RESTAURANT_PLAN_FREE
        )

        advert.subscription_status = "active"

        advert.subscription_started_at = (
            datetime.utcnow()
        )

        advert.subscription_expires_at = None

        try:
            db.session.commit()

            flash(
                f"{advert.business_name} has been "
                "successfully changed to the Free plan.",
                "success",
            )

        except Exception:
            db.session.rollback()

            current_app.logger.exception(
                "Failed to update restaurant subscription. "
                "organizer_id=%s advert_id=%s",
                organizer.id,
                advert.id,
            )

            flash(
                "The restaurant plan could not be updated. "
                "Please try again.",
                "error",
            )

        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=organizer.id,
            )
        )

    # --------------------------------------------------------
    # STANDARD / PREMIUM
    # --------------------------------------------------------
    #
    # Paid plans require an expiry date and time.
    #
    # datetime-local submits YYYY-MM-DDTHH:MM.
    # This parses the value into a naive datetime, consistent
    # with the existing model's datetime.utcnow() convention.
    # --------------------------------------------------------

    expiry_value = (
        request.form.get(
            "subscription_expires_at",
            "",
        )
        .strip()
    )

    if not expiry_value:
        flash(
            "Select an expiry date and time for the paid plan.",
            "error",
        )

        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=organizer.id,
            )
        )

    try:
        expiry_at = datetime.strptime(
            expiry_value,
            "%Y-%m-%dT%H:%M",
        )

    except (TypeError, ValueError):
        flash(
            "The expiry date or time is invalid.",
            "error",
        )

        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=organizer.id,
            )
        )

    # --------------------------------------------------------
    # SAVE PAID PLAN
    # --------------------------------------------------------

    advert.subscription_tier = selected_plan

    advert.subscription_status = "active"

    advert.subscription_started_at = (
        datetime.utcnow()
    )

    advert.subscription_expires_at = expiry_at

    try:
        db.session.commit()

        flash(
            f"{advert.business_name} has been changed "
            f"to the {selected_plan.title()} plan. "
            f"Expiry: {expiry_at.strftime('%d %B %Y %H:%M')}.",
            "success",
        )

        current_app.logger.info(
            "Super Admin updated restaurant subscription. "
            "organizer_id=%s advert_id=%s tier=%s expiry=%s",
            organizer.id,
            advert.id,
            selected_plan,
            expiry_at.isoformat(),
        )

    except Exception:
        db.session.rollback()

        current_app.logger.exception(
            "Failed to update restaurant subscription. "
            "organizer_id=%s advert_id=%s",
            organizer.id,
            advert.id,
        )

        flash(
            "The restaurant plan could not be updated. "
            "Please try again.",
            "error",
        )

    return redirect(
        url_for(
            "superadmin_organizer_detail",
            organizer_id=organizer.id,
        )
    )
# ============================================================
# ORGANIZER PASSWORD RESET HELPERS
# ============================================================

ORGANIZER_PASSWORD_RESET_SALT = (
    "kalxa-organizer-password-reset"
)


def get_password_reset_serializer():

    return URLSafeTimedSerializer(
        current_app.secret_key
    )



def create_organizer_password_reset_token(
    organizer,
):

    serializer = (
        get_password_reset_serializer()
    )


    return serializer.dumps(
        {
            "organizer_id":
                organizer.id,

            "email":
                organizer.email,
        },
        salt=
            ORGANIZER_PASSWORD_RESET_SALT,
    )



def verify_organizer_password_reset_token(
    token,
):

    serializer = (
        get_password_reset_serializer()
    )


    try:

        payload = (
            serializer.loads(
                token,

                salt=
                    ORGANIZER_PASSWORD_RESET_SALT,

                max_age=
                    PASSWORD_RESET_MAX_AGE_SECONDS,
            )
        )


    except SignatureExpired:

        return (
            None,
            "expired",
        )


    except BadSignature:

        return (
            None,
            "invalid",
        )


    if not isinstance(
        payload,
        dict,
    ):

        return (
            None,
            "invalid",
        )


    organizer_id = (
        payload.get(
            "organizer_id"
        )
    )


    email = (
        payload.get(
            "email"
        )
    )


    if (
        not organizer_id
        or not email
    ):

        return (
            None,
            "invalid",
        )


    organizer = (
        db.session.get(
            Organizer,
            organizer_id,
        )
    )


    if not organizer:

        return (
            None,
            "invalid",
        )


    if (
        normalize_email(
            organizer.email
        )
        !=
        normalize_email(
            email
        )
    ):

        return (
            None,
            "invalid",
        )


    return (
        organizer,
        None,
    )

# ============================================================
# SEND PASSWORD RESET EMAIL
# ============================================================

def send_organizer_password_reset_email(
    organizer,
    reset_url,
):

    if (
        not SMTP_HOST
        or not SMTP_FROM_EMAIL
    ):

        raise RuntimeError(
            (
                "Password reset email "
                "is not configured."
            )
        )


    message = EmailMessage()


    message[
        "Subject"
    ] = (
        "Reset your Kalxa password"
    )


    message[
        "From"
    ] = SMTP_FROM_EMAIL


    message[
        "To"
    ] = organizer.email


    message.set_content(
        (
            f"Hi {organizer.name},\n\n"

            "We received a request to reset "
            "your Kalxa password.\n\n"

            "Use the link below to choose "
            "a new password:\n\n"

            f"{reset_url}\n\n"

            "This link expires in 1 hour.\n\n"

            "If you did not request a password "
            "reset, you can ignore this email.\n\n"

            "Kalxa"
        )
    )


    if SMTP_PORT == 465:

        with smtplib.SMTP_SSL(
            SMTP_HOST,
            SMTP_PORT,
            timeout=20,
        ) as server:

            if (
                SMTP_USERNAME
                and SMTP_PASSWORD
            ):

                server.login(
                    SMTP_USERNAME,
                    SMTP_PASSWORD,
                )


            server.send_message(
                message
            )


    else:

        with smtplib.SMTP(
            SMTP_HOST,
            SMTP_PORT,
            timeout=20,
        ) as server:

            server.ehlo()

            server.starttls()

            server.ehlo()


            if (
                SMTP_USERNAME
                and SMTP_PASSWORD
            ):

                server.login(
                    SMTP_USERNAME,
                    SMTP_PASSWORD,
                )


            server.send_message(
                message
            )

# ============================================================
# SUPER ADMIN - CONFIRM SUBSCRIPTION PAYMENT
# ============================================================

@app.route(
    "/superadmin/subscription-payments/<int:payment_id>/confirm",
    methods=[
        "POST",
    ],
)
def superadmin_confirm_subscription_payment(
    payment_id,
):

    auth = (
        require_superadmin()
    )


    if auth:

        return auth


    payment = (
        db.session.get(
            SubscriptionPayment,
            payment_id,
        )
    )


    if not payment:

        abort(404)


    organizer = (
        payment.organizer
    )


    if not organizer:

        abort(404)


    if (
        payment.payment_method
        == "paystack"
    ):

        flash(
            (
                "Paystack subscription payments are verified "
                "automatically and cannot be manually confirmed."
            ),
            "error",
        )

        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=
                    organizer.id,
            )
        )


    if (
        payment.payment_status
        == "paid"
    ):

        flash(
            "This subscription payment is already confirmed.",
            "error",
        )


        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=
                    organizer.id,
            )
        )


    if (
        payment.payment_status
        != "pending"
    ):

        flash(
            (
                "Only pending subscription payments "
                "can be confirmed."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=
                    organizer.id,
            )
        )


    if organizer.is_suspended:

        flash(
            (
                "Reactivate this organizer before "
                "confirming subscription payment."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=
                    organizer.id,
            )
        )


    now = (
        datetime.utcnow()
    )


    if (
        organizer.subscription_expires_at
        and organizer.subscription_expires_at
        > now
    ):

        subscription_start = (
            organizer.subscription_expires_at
        )

    else:

        subscription_start = now


    subscription_end = (
        subscription_start
        + timedelta(
            days=payment.period_days
            or KALXA_SUBSCRIPTION_PERIOD_DAYS
        )
    )


    payment.payment_status = (
        "paid"
    )

    payment.paid_at = now

    payment.confirmed_at = now

    payment.confirmed_by = (
        "superadmin"
    )

    payment.subscription_start = (
        subscription_start
    )

    payment.subscription_end = (
        subscription_end
    )


    organizer.active = True

    organizer.subscription_status = (
        "active"
    )


    if not organizer.subscription_started_at:

        organizer.subscription_started_at = (
            now
        )


    organizer.subscription_expires_at = (
        subscription_end
    )


    try:

        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Super Admin] Failed to confirm "
                "subscription payment payment_id=%s "
                "organizer_id=%s error=%s"
            ),
            payment.id,
            organizer.id,
            error,
        )


        flash(
            "Subscription payment confirmation failed.",
            "error",
        )


        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=
                    organizer.id,
            )
        )


    flash(
        (
            "Subscription payment confirmed. "
            f"Access is active until "
            f"{subscription_end.strftime('%d %B %Y')}."
        ),
        "success",
    )


    return redirect(
        url_for(
            "superadmin_organizer_detail",
            organizer_id=
                organizer.id,
        )
    )


