# ============================================================
# SUPER ADMIN - ACTIVATE / EXTEND SUBSCRIPTION
# ============================================================

@app.route(
    "/superadmin/organizers/<int:organizer_id>/activate",
    methods=[
        "POST",
    ],
)
def superadmin_activate_subscription(
    organizer_id,
):

    auth = (
        require_superadmin()
    )


    if auth:

        return auth


    organizer = (
        db.session.get(
            Organizer,
            organizer_id,
        )
    )


    if not organizer:

        abort(404)


    if (
        organizer.subscription_status
        == "suspended"
        or not organizer.active
    ):

        flash(
            (
                "Reactivate this organizer account "
                "before activating the subscription."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=
                    organizer.id,
            )
        )


    days = request.form.get(
        "days",
        30,
        type=int,
    )


    if (
        not days
        or days < 1
        or days > 3650
    ):

        flash(
            (
                "Subscription extension must be "
                "between 1 and 3650 days."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=
                    organizer.id,
            )
        )


    now = (
        datetime.utcnow()
    )


    if (
        organizer.subscription_expires_at
        and organizer.subscription_expires_at
        > now
    ):

        base_date = (
            organizer.subscription_expires_at
        )

    else:

        base_date = now


    if not organizer.subscription_started_at:

        organizer.subscription_started_at = (
            now
        )


    organizer.subscription_expires_at = (
        base_date
        + timedelta(
            days=days
        )
    )


    organizer.subscription_status = (
        "active"
    )


    organizer.active = True


    try:

        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Super Admin] Failed to activate "
                "subscription organizer_id=%s error=%s"
            ),
            organizer.id,
            error,
        )


        flash(
            "Subscription update failed.",
            "error",
        )


        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=
                    organizer.id,
            )
        )


    flash(
        (
            f"Subscription activated/extended "
            f"by {days} day(s)."
        ),
        "success",
    )


    return redirect(
        url_for(
            "superadmin_organizer_detail",
            organizer_id=
                organizer.id,
        )
    )


# ============================================================
# SUPER ADMIN - SET EXACT EXPIRY DATE
# ============================================================
# ============================================================
# SUPER ADMIN - SET EXACT SUBSCRIPTION / PARTNER EXPIRY
# ============================================================

@app.route(
    "/superadmin/organizers/<int:organizer_id>/set-expiry",
    methods=["POST"],
)
def superadmin_set_subscription_expiry(organizer_id):

    # ========================================================
    # SUPER ADMIN AUTHENTICATION
    # ========================================================

    auth = require_superadmin()

    if auth:
        return auth

    # ========================================================
    # FIND ORGANIZER
    # ========================================================

    organizer = db.session.get(
        Organizer,
        organizer_id,
    )

    if not organizer:
        abort(404)

    # ========================================================
    # READ EXPIRY DATE
    # ========================================================

    expiry_raw = (
        request.form.get(
            "subscription_expires_on",
            "",
        )
        .strip()
    )

    # ========================================================
    # VALIDATE DATE
    # ========================================================

    try:
        expiry_date = datetime.strptime(
            expiry_raw,
            "%Y-%m-%d",
        )

        expiry_at = expiry_date.replace(
            hour=23,
            minute=59,
            second=59,
            microsecond=0,
        )

    except (TypeError, ValueError):

        flash(
            "Please enter a valid expiry date.",
            "error",
        )

        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=organizer.id,
            )
        )

    # ========================================================
    # FIND LATEST PARTNER GRANT
    # ========================================================

    latest_partner_grant = (
        SubscriptionPayment.query
        .filter(
            SubscriptionPayment.organizer_id
            == organizer.id,

            SubscriptionPayment.payment_method
            == "partner_grant",

            SubscriptionPayment.amount
            == Decimal("0.00"),

            SubscriptionPayment.confirmed_by
            == "superadmin_partner_grant",
        )
        .order_by(
            SubscriptionPayment.created_at.desc(),
            SubscriptionPayment.id.desc(),
        )
        .first()
    )

    # ========================================================
    # FIND RESTAURANT PROFILE, IF APPLICABLE
    # ========================================================

    restaurant_advert = None

    account_type = (
        getattr(
            organizer,
            "normalized_account_type",
            None,
        )
        or "event"
    )

    if account_type == "restaurant":

        restaurant_advert = (
            RestaurantAdvert.query
            .filter_by(
                organizer_id=organizer.id,
            )
            .order_by(
                RestaurantAdvert.id.asc()
            )
            .first()
        )

    # ========================================================
    # PREPARE STATUS UPDATE
    # ========================================================

    now = datetime.utcnow()

    # ========================================================
    # UPDATE ORGANIZER EXPIRY
    # ========================================================

    organizer.subscription_expires_at = expiry_at

    # ========================================================
    # UPDATE ORGANIZER SUBSCRIPTION STATUS
    # ========================================================
    #
    # Do not reactivate suspended or inactive accounts.
    # ========================================================

    if (
        organizer.subscription_status != "suspended"
        and organizer.active
    ):

        if expiry_at > now:

            organizer.subscription_status = "active"

            if not organizer.subscription_started_at:
                organizer.subscription_started_at = now

        else:

            organizer.subscription_status = "expired"

    # ========================================================
    # UPDATE PARTNER-GRANT EXPIRY
    # ========================================================

    if latest_partner_grant:

        latest_partner_grant.subscription_end = (
            expiry_at
        )

    # ========================================================
    # SYNCHRONIZE RESTAURANT SUBSCRIPTION EXPIRY
    # ========================================================
    #
    # Only synchronize when the restaurant subscription
    # started at the same time as the complimentary grant.
    #
    # This avoids overwriting a separate paid subscription
    # that started later.
    # ========================================================

    restaurant_expiry_synchronized = False

    if (
        restaurant_advert
        and latest_partner_grant
        and latest_partner_grant.subscription_start
    ):

        restaurant_subscription_started_at = getattr(
            restaurant_advert,
            "subscription_started_at",
            None,
        )

        if (
            restaurant_subscription_started_at
            and restaurant_subscription_started_at
            == latest_partner_grant.subscription_start
        ):

            restaurant_advert.subscription_expires_at = (
                expiry_at
            )

            restaurant_expiry_synchronized = True

    # ========================================================
    # SAVE CHANGES
    # ========================================================

    try:

        db.session.commit()

    except Exception as error:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Super Admin] Failed to synchronize "
                "organizer, partner and restaurant expiry. "
                "organizer_id=%s error=%s"
            ),
            organizer_id,
            error,
        )

        flash(
            (
                "Subscription expiry update failed. "
                "No changes were saved."
            ),
            "error",
        )

        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=organizer_id,
            )
        )

    # ========================================================
    # SYNCHRONIZE RESTAURANT SUBSCRIPTION LIFECYCLE
    # ========================================================
    #
    # Run after saving the new expiry so the existing
    # subscription lifecycle method sees the updated date.
    # ========================================================

    if restaurant_expiry_synchronized:

        try:

            sync_restaurant_subscription(
                restaurant_advert
            )

        except Exception:

            current_app.logger.exception(
                (
                    "[Super Admin] Restaurant subscription "
                    "lifecycle synchronization failed. "
                    "organizer_id=%s advert_id=%s"
                ),
                organizer_id,
                restaurant_advert.id,
            )

    # ========================================================
    # SUCCESS MESSAGE
    # ========================================================

    if latest_partner_grant:

        if restaurant_expiry_synchronized:

            flash(
                (
                    "Expiry date updated successfully. "
                    "The organizer, partner grant and "
                    "restaurant subscription expiry dates "
                    "have been synchronized."
                ),
                "success",
            )

        else:

            flash(
                (
                    "Expiry date updated successfully. "
                    "The organizer expiry and latest recorded "
                    "partner expiry now match. The restaurant "
                    "subscription was not changed because a "
                    "matching complimentary subscription period "
                    "could not be confirmed."
                ),
                "success",
            )

    else:

        flash(
            "Subscription expiry date updated successfully.",
            "success",
        )

    # ========================================================
    # RETURN TO ORGANIZER DETAILS
    # ========================================================

    return redirect(
        url_for(
            "superadmin_organizer_detail",
            organizer_id=organizer_id,
        )
    )
