# ============================================================
# SUPER ADMIN - SEND RESTAURANT PUSH
# ============================================================
@app.route(
    "/superadmin/notifications/restaurants/send",
    methods=[
        "POST",
    ],
)
def superadmin_send_restaurant_notification():

    # ========================================================
    # SUPERADMIN AUTHENTICATION
    # ========================================================

    auth = (
        require_superadmin()
    )


    if auth:
        return auth


    # ========================================================
    # FIREBASE REQUIRED
    # ========================================================

    if not firebase_admin_configured():

        flash(
            (
                "Server-side Firebase sending "
                "is not configured."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications"
            )
        )


    # ========================================================
    # FORM VALUES
    # ========================================================

    restaurant_id = (
        request.form.get(
            "restaurant_id",
            type=int,
        )
    )


    title = (
        request.form.get(
            "title",
            "",
        )
        .strip()
    )


    body = (
        request.form.get(
            "body",
            "",
        )
        .strip()
    )


    # ========================================================
    # RESTAURANT ID REQUIRED
    # ========================================================

    if not restaurant_id:

        flash(
            "Choose a restaurant advert.",
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications"
            )
        )


    # ========================================================
    # RESTAURANT
    # ========================================================

    advert = (
        RestaurantAdvert.query

        .filter_by(
            id=restaurant_id,
        )

        .first()
    )


    if not advert:

        flash(
            "Restaurant advert was not found.",
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications"
            )
        )


    # ========================================================
    # OWNER
    # ========================================================

    organizer = (
        advert.organizer
    )


    # ========================================================
    # RESTAURANT OWNER REQUIRED
    # ========================================================
    #
    # IMPORTANT:
    #
    # We no longer check:
    #
    #     organizer.is_subscription_active
    #
    # Restaurant promotion is now controlled by the
    # RestaurantAdvert Free / Standard / Premium plan.
    #
    # The Organizer account must still exist and be active.
    # ========================================================

    if not organizer:

        flash(
            (
                "This restaurant does not have "
                "a valid owner account."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # OWNER ACCOUNT MUST BE ACTIVE
    # ========================================================

    if not organizer.active:

        flash(
            (
                "This restaurant owner account "
                "is currently inactive."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # RESTAURANT ACCOUNT TYPE
    # ========================================================

    account_type = (
        getattr(
            organizer,
            "account_type",
            None,
        )
        or "event"
    )


    if (
        account_type
        != "restaurant"
    ):

        flash(
            (
                "This advert is not owned by "
                "a restaurant account."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # RESTAURANT ADVERT MUST BE ACTIVE
    # ========================================================

    if not advert.active:

        flash(
            (
                "This restaurant advert "
                "is currently paused."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # RESTAURANT PLAN MUST BE ACTIVE
    # ========================================================
    #
    # FREE
    # --------------------------------------------------------
    # Active without an expiry date.
    #
    # STANDARD / PREMIUM
    # --------------------------------------------------------
    # Must have active status and a future restaurant-plan
    # expiry date.
    #
    # This check belongs to RestaurantAdvert rather than the
    # old Organizer SaaS subscription.
    # ========================================================

    if not advert.is_restaurant_subscription_active:

        flash(
            (
                "This restaurant plan is "
                "currently inactive."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # RESTAURANT PROMOTION / REEL FEATURE
    # ========================================================
    #
    # Restaurant discovery/reel promotion is currently
    # available on:
    #
    #     FREE
    #     STANDARD
    #     PREMIUM
    #
    # We still use the feature property rather than hardcoding
    # plan names so this route automatically follows future
    # changes to the restaurant feature matrix.
    # ========================================================

    if not advert.can_use_reel:

        flash(
            (
                "This restaurant plan does not "
                "currently allow restaurant promotion."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # CAMPAIGN WINDOW
    # ========================================================

    now = (
        datetime.utcnow()
    )


    # ========================================================
    # CAMPAIGN HAS NOT STARTED
    # ========================================================

    if (
        advert.starts_at
        and
        advert.starts_at > now
    ):

        flash(
            (
                "This restaurant campaign "
                "has not started yet."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # CAMPAIGN EXPIRED
    # ========================================================

    if (
        advert.ends_at
        and
        advert.ends_at <= now
    ):

        flash(
            (
                "This restaurant campaign "
                "has already expired."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # TITLE REQUIRED
    # ========================================================

    if not title:

        flash(
            "Notification title is required.",
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # BODY REQUIRED
    # ========================================================

    if not body:

        flash(
            "Notification message is required.",
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # TITLE LENGTH
    # ========================================================

    if len(title) > 120:

        flash(
            (
                "Notification title must be "
                "120 characters or fewer."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # BODY LENGTH
    # ========================================================

    if len(body) > 500:

        flash(
            (
                "Notification message must be "
                "500 characters or fewer."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # AREA REQUIRED
    # ========================================================

    if not advert.area:

        flash(
            (
                "This restaurant does not have "
                "an area configured."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # AUDIENCE
    # ========================================================

    subscriptions = (
        get_restaurant_push_subscriptions(
            advert
        )
    )


    if not subscriptions:

        flash(
            (
                "No active notification "
                f"subscribers were found in {advert.area}."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # CREATE PUSH CAMPAIGN
    # ========================================================

    campaign = PushCampaign(

        campaign_type="restaurant",

        event_id=None,

        restaurant_advert_id=advert.id,

        title=title,

        body=body,

        target_url=(
            url_for(
                "restaurant_page",

                advert_id=advert.id,

                _external=True,
            )
        ),

        target_mode="area",

        target_area=advert.area,

        target_latitude=None,

        target_longitude=None,

        radius_km=None,

        status="draft",

        recipient_count=(
            len(
                subscriptions
            )
        ),

        created_by="superadmin",
    )


    # ========================================================
    # SAVE CAMPAIGN
    # ========================================================

    try:

        db.session.add(
            campaign
        )

        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Restaurant Push] "
                "Campaign creation failed "
                "advert_id=%s "
                "error=%s"
            ),
            advert.id,
            error,
        )


        flash(
            (
                "Restaurant notification "
                "campaign could not be created."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # SEND PUSH CAMPAIGN
    # ========================================================

    try:

        send_push_campaign(
            campaign,
            subscriptions,
        )


    except Exception as error:

        db.session.rollback()


        # ====================================================
        # RELOAD CAMPAIGN
        # ====================================================

        campaign = (
            db.session.get(
                PushCampaign,
                campaign.id,
            )
        )


        # ====================================================
        # MARK CAMPAIGN AS FAILED
        # ====================================================

        if campaign:

            campaign.status = (
                "failed"
            )


            try:

                db.session.commit()


            except Exception:

                db.session.rollback()


                current_app.logger.exception(
                    (
                        "[Restaurant Push] "
                        "Unable to mark campaign "
                        "as failed "
                        "campaign_id=%s "
                        "advert_id=%s"
                    ),
                    campaign.id,
                    advert.id,
                )


        # ====================================================
        # LOG SEND FAILURE
        # ====================================================

        current_app.logger.exception(
            (
                "[Restaurant Push] "
                "Send failed "
                "campaign_id=%s "
                "advert_id=%s "
                "error=%s"
            ),
            (
                campaign.id
                if campaign
                else None
            ),
            advert.id,
            error,
        )


        flash(
            (
                "Firebase could not send the "
                "restaurant notification."
            ),
            "error",
        )


        return redirect(
            url_for(
                "superadmin_notifications",

                restaurant_id=advert.id,
            )
        )


    # ========================================================
    # SEND RESULT
    # ========================================================

    if campaign.failure_count:

        flash(
            (
                "Restaurant notification finished. "
                f"{campaign.success_count} sent, "
                f"{campaign.failure_count} failed."
            ),
            "success",
        )


    else:

        flash(
            (
                "Restaurant notification sent "
                f"successfully to "
                f"{campaign.success_count} "
                "subscriber(s)."
            ),
            "success",
        )


    # ========================================================
    # SUCCESS REDIRECT
    # ========================================================

    return redirect(
        url_for(
            "superadmin_notifications",

            restaurant_id=advert.id,
        )
    )
# ============================================================
# SUPER ADMIN - REACTIVATE ORGANIZER
# ============================================================

@app.route(
    "/superadmin/organizers/<int:organizer_id>/reactivate",
    methods=[
        "POST",
    ],
)
def superadmin_reactivate_organizer(
    organizer_id,
):

    auth = (
        require_superadmin()
    )


    if auth:

        return auth


    organizer = (
        db.session.get(
            Organizer,
            organizer_id,
        )
    )


    if not organizer:

        abort(404)


    organizer.active = True

    organizer.suspended_at = None

    organizer.suspension_reason = None


    now = (
        datetime.utcnow()
    )


    if (
        organizer.subscription_expires_at
        and organizer.subscription_expires_at
        > now
    ):

        organizer.subscription_status = (
            "active"
        )

    elif organizer.subscription_expires_at:

        organizer.subscription_status = (
            "expired"
        )

    else:

        organizer.subscription_status = (
            "inactive"
        )


    try:

        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Super Admin] Failed to reactivate "
                "organizer_id=%s error=%s"
            ),
            organizer.id,
            error,
        )


        flash(
            "Organizer reactivation failed.",
            "error",
        )


        return redirect(
            url_for(
                "superadmin_organizer_detail",
                organizer_id=
                    organizer.id,
            )
        )


    flash(
        "Organizer account reactivated.",
        "success",
    )


    return redirect(
        url_for(
            "superadmin_organizer_detail",
            organizer_id=
                organizer.id,
        )
    )



# ============================================================
# HOME
# ============================================================

@app.route("/")
def home():

    # ========================================================
    # CURRENT DATE / TIME
    # ========================================================

    today = (
        date.today()
    )


    now = (
        datetime.utcnow()
    )


    # ========================================================
    # EVENTS
    # ========================================================

    events = (
        TicketEvent.query

        .filter_by(
            active=True,
            status="published",
            organizer_deleted=False,
        )

        .filter(
            TicketEvent.event_date
            >= today
        )

        .order_by(
            TicketEvent.event_date.asc(),
            TicketEvent.created_at.desc(),
        )

        .all()
    )


    # ========================================================
    # FEATURED EVENTS
    # ========================================================

    active_featured_listings = (
        FeaturedListing.query

        .join(
            TicketEvent,

            FeaturedListing.event_id
            ==
            TicketEvent.id,
        )

        .filter(
            FeaturedListing.status
            == "active",

            FeaturedListing.starts_at
            <= now,

            FeaturedListing.ends_at
            > now,

            TicketEvent.active.is_(True),

            TicketEvent.status
            == "published",

            TicketEvent.organizer_deleted.is_(False),

            TicketEvent.event_date
            >= today,
        )

        .order_by(
            FeaturedListing.starts_at.desc()
        )

        .all()
    )


    featured_by_event = {}


    for listing in active_featured_listings:

        if (
            listing.event_id
            not in featured_by_event
        ):

            featured_by_event[
                listing.event_id
            ] = listing


    featured_events = [

        {
            "event":
                listing.event,

            "listing":
                listing,

            "images":
                list(
                    listing.event.featured_images
                )[
                    :FEATURED_IMAGE_MAX_COUNT
                ],
        }

        for listing
        in featured_by_event.values()
    ]


    featured_event_ids = {

        item["event"].id

        for item
        in featured_events
    }


    normal_events = [

        event

        for event
        in events

        if (
            event.id
            not in featured_event_ids
        )
    ]


    # ========================================================
    # EVENT REELS
    # ========================================================
    #
    # SEE THE VIBE
    # ========================================================

    reels = (
        EventReel.query

        .join(
            TicketEvent,

            EventReel.event_id
            ==
            TicketEvent.id,
        )

        .filter(
            EventReel.active.is_(True),

            TicketEvent.active.is_(True),

            TicketEvent.status
            == "published",

            TicketEvent.organizer_deleted.is_(False),

            TicketEvent.event_date
            >= today,
        )

        .order_by(
            EventReel.created_at.desc()
        )

        .limit(12)

        .all()
    )


    # ========================================================
    # EVENT REEL PUBLIC VIEW COUNTS
    # ========================================================
    #
    # A public reel "view" is currently defined as a unique
    # PLAY analytics event.
    #
    # EventReelAnalytics already has this database constraint:
    #
    #     reel_id
    #     anonymous_session_id
    #     event_type
    #
    # Therefore one anonymous session can only generate one
    # "play" event for a particular reel.
    #
    # We calculate all visible reel counts in ONE query rather
    # than running one query for every reel.
    # ========================================================

    reel_view_counts = {}


    if reels:

        reel_ids = [

            reel.id

            for reel
            in reels
        ]


        reel_view_rows = (
            db.session.query(
                EventReelAnalytics.reel_id,
                db.func.count(
                    EventReelAnalytics.id
                ),
            )

            .filter(
                EventReelAnalytics.reel_id.in_(
                    reel_ids
                ),

                EventReelAnalytics.event_type
                == "play",
            )

            .group_by(
                EventReelAnalytics.reel_id
            )

            .all()
        )


        reel_view_counts = {

            reel_id: int(
                view_count
                or 0
            )

            for (
                reel_id,
                view_count,
            )
            in reel_view_rows
        }


    # ========================================================
    # RESTAURANT REELS
    # ========================================================

    restaurant_reels = (
        RestaurantReel.query

        .join(
            RestaurantAdvert,

            RestaurantReel.advert_id
            ==
            RestaurantAdvert.id,
        )

        .join(
            Organizer,

            RestaurantAdvert.organizer_id
            ==
            Organizer.id,
        )

        .filter(
            # =================================================
            # REEL ACTIVE
            # =================================================

            RestaurantReel.active.is_(
                True
            ),

            # =================================================
            # RESTAURANT ACTIVE
            # =================================================

            RestaurantAdvert.active.is_(
                True
            ),

            # =================================================
            # RESTAURANT SUBSCRIPTION STATUS
            # =================================================
            #
            # Free restaurants are active indefinitely.
            #
            # Paid restaurants remain active during their
            # grace period.
            # =================================================

            RestaurantAdvert.subscription_status
            == "active",

            # =================================================
            # ORGANIZER ACTIVE
            # =================================================

            Organizer.active.is_(
                True
            ),

            # =================================================
            # RESTAURANT ACCOUNT
            # =================================================

            Organizer.account_type
            == "restaurant",

            # =================================================
            # CAMPAIGN START
            # =================================================

            or_(
                RestaurantAdvert.starts_at.is_(
                    None
                ),

                RestaurantAdvert.starts_at
                <= now,
            ),

            # =================================================
            # CAMPAIGN END
            # =================================================

            or_(
                RestaurantAdvert.ends_at.is_(
                    None
                ),

                RestaurantAdvert.ends_at
                > now,
            ),
        )

        .order_by(
            RestaurantReel.created_at.desc()
        )

        .limit(12)

        .all()
    )


    # ========================================================
    # FINAL RESTAURANT REEL CAPABILITY CHECK
    # ========================================================
    #
    # Keep the public feed aligned with the centralized
    # RestaurantAdvert capability system.
    #
    # Free, Standard and Premium currently all have:
    #
    #     can_use_reel == True
    #
    # If plan rules change later, this filter will follow
    # those rules.
    # ========================================================

    visible_restaurant_reels = []


    for restaurant_reel in restaurant_reels:

        advert = (
            restaurant_reel.advert
        )


        if not advert:

            continue


        # ====================================================
        # SYNCHRONIZE PAID PLAN LIFECYCLE
        # ====================================================
        #
        # If Standard/Premium grace has expired, this can
        # downgrade the restaurant to Free.
        #
        # That does NOT remove the Reel because Free is
        # allowed to use Reel/Discovery.
        # ====================================================

        sync_restaurant_subscription(
            advert
        )


        if not advert.can_use_reel:

            continue


        visible_restaurant_reels.append(
            restaurant_reel
        )


    restaurant_reels = (
        visible_restaurant_reels
    )


    # ========================================================
    # CUSTOMER RESTAURANT EXPERIENCES
    # ========================================================
    #
    # Customer experiences are a paid restaurant capability.
    #
    # FREE
    #     -> hidden
    #
    # STANDARD
    #     -> visible
    #
    # PREMIUM
    #     -> visible
    #
    # PAID GRACE
    #     -> visible
    #
    # AFTER GRACE
    #     -> restaurant becomes Free
    #     -> existing posts remain stored
    #     -> existing posts are NOT publicly exposed
    #
    # IMPORTANT:
    #
    # We do not delete experience posts when a restaurant
    # downgrades.
    #
    # Re-upgrading can expose the approved posts again.
    # ========================================================

    restaurant_experience_candidates = (
        RestaurantExperiencePost.query

        .join(
            RestaurantAdvert,

            RestaurantExperiencePost.restaurant_advert_id
            ==
            RestaurantAdvert.id,
        )

        .join(
            Organizer,

            RestaurantAdvert.organizer_id
            ==
            Organizer.id,
        )

        .filter(
            # =================================================
            # EXPERIENCE ACTIVE
            # =================================================

            RestaurantExperiencePost.active.is_(
                True
            ),

            # =================================================
            # APPROVED ONLY
            # =================================================

            RestaurantExperiencePost.moderation_status
            == "approved",

            # =================================================
            # RESTAURANT ACTIVE
            # =================================================

            RestaurantAdvert.active.is_(
                True
            ),

            # =================================================
            # RESTAURANT SUBSCRIPTION STATUS
            # =================================================

            RestaurantAdvert.subscription_status
            == "active",

            # =================================================
            # STANDARD / PREMIUM ONLY
            # =================================================

            RestaurantAdvert.subscription_tier.in_(
                [
                    RESTAURANT_PLAN_STANDARD,
                    RESTAURANT_PLAN_PREMIUM,
                ]
            ),

            # =================================================
            # PAID EXPIRY REQUIRED
            # =================================================

            RestaurantAdvert.subscription_expires_at
            .isnot(
                None
            ),

            # =================================================
            # ORGANIZER ACTIVE
            # =================================================

            Organizer.active.is_(
                True
            ),

            # =================================================
            # RESTAURANT ORGANIZER
            # =================================================

            Organizer.account_type
            == "restaurant",

            # =================================================
            # CAMPAIGN START
            # =================================================

            or_(
                RestaurantAdvert.starts_at.is_(
                    None
                ),

                RestaurantAdvert.starts_at
                <= now,
            ),

            # =================================================
            # CAMPAIGN END
            # =================================================

            or_(
                RestaurantAdvert.ends_at.is_(
                    None
                ),

                RestaurantAdvert.ends_at
                > now,
            ),
        )

        .order_by(
            RestaurantExperiencePost.created_at.desc()
        )

        # ====================================================
        # FETCH EXTRA CANDIDATES
        # ====================================================
        #
        # Some candidates may be removed below because their
        # paid grace period has expired.
        #
        # Fetching more than 20 gives us room to still return
        # up to 20 eligible posts.
        # ====================================================

        .limit(60)

        .all()
    )


    # ========================================================
    # FINAL EXPERIENCE CAPABILITY CHECK
    # ========================================================

    restaurant_experiences = []


    for post in restaurant_experience_candidates:

        advert = (
            post.restaurant_advert
        )


        if not advert:

            continue


        # ====================================================
        # SYNCHRONIZE SUBSCRIPTION
        # ====================================================

        sync_restaurant_subscription(
            advert
        )


        # ====================================================
        # CUSTOMER EXPERIENCE CAPABILITY
        # ====================================================

        if not advert.can_receive_customer_experiences:

            continue


        # ====================================================
        # ADD TO PUBLIC FEED
        # ====================================================

        restaurant_experiences.append(
            post
        )


        # ====================================================
        # HOME FEED LIMIT
        # ====================================================

        if (
            len(
                restaurant_experiences
            )
            >= 20
        ):

            break


    # ========================================================
    # CURRENT ANONYMOUS LOVE STATE
    # ========================================================

    anonymous_session_id = (
        get_restaurant_experience_session_id()
    )


    loved_experience_post_ids = set()


    if restaurant_experiences:

        post_ids = [

            post.id

            for post
            in restaurant_experiences
        ]


        loved_experience_post_ids = {

            love.post_id

            for love
            in (
                RestaurantExperienceLove.query

                .filter(
                    RestaurantExperienceLove.post_id.in_(
                        post_ids
                    )
                )

                .filter(
                    RestaurantExperienceLove.anonymous_session_id
                    ==
                    anonymous_session_id
                )

                .all()
            )
        }


    # ========================================================
    # RENDER HOME
    # ========================================================

    return render_template(
        "event.html",

        featured_events=(
            featured_events
        ),

        events=(
            normal_events
        ),

        event=None,

        reels=(
            reels
        ),

        # ====================================================
        # EVENT REEL VIEW COUNTS
        # ====================================================

        reel_view_counts=(
            reel_view_counts
        ),

        restaurant_reels=(
            restaurant_reels
        ),

        restaurant_experiences=(
            restaurant_experiences
        ),

        loved_experience_post_ids=(
            loved_experience_post_ids
        ),

        firebase_config=(
            FIREBASE_WEB_CONFIG
        ),

        firebase_vapid_key=(
            FIREBASE_VAPID_KEY
        ),

        firebase_push_configured=(
            firebase_web_push_configured()
        ),
    )


@app.route(
    "/event/<int:event_id>"
)
def event_page(
    event_id,
):

    # ========================================================
    # FIND PUBLIC EVENT
    # ========================================================

    event = (
        TicketEvent.query
        .filter_by(
            id=event_id,
            active=True,
            status="published",
            organizer_deleted=False,
        )
        .first_or_404()
    )


    # ========================================================
    # EVENT REEL VIEW COUNT
    # ========================================================
    #
    # event.html is also used for the individual event page.
    #
    # Pass the same reel_view_counts structure used by the
    # homepage so the template can safely use:
    #
    #     reel_view_counts.get(reel.id, 0)
    #
    # regardless of whether it is rendering the homepage or
    # an individual event.
    # ========================================================

    reel_view_counts = {}


    if (
        event.reel
        and event.reel.active
    ):

        view_count = (
            db.session.query(
                db.func.count(
                    EventReelAnalytics.id
                )
            )

            .filter(
                EventReelAnalytics.reel_id
                == event.reel.id,

                EventReelAnalytics.event_type
                == "play",
            )

            .scalar()
            or 0
        )


        reel_view_counts[
            event.reel.id
        ] = int(
            view_count
        )


    # ========================================================
    # RENDER EVENT
    # ========================================================

    return render_template(
        "event.html",

        event=event,

        events=None,

        reel_view_counts=(
            reel_view_counts
        ),
    )
# ============================================================
# RESTAURANT GALLERY
# ============================================================


RESTAURANT_GALLERY_MAX_IMAGES = 5

RESTAURANT_GALLERY_MAX_FILE_BYTES = 8 * 1024 * 1024


def get_restaurant_gallery_files():
    files = request.files.getlist("gallery_images")

    return [
        file
        for file in files
        if file and file.filename
    ]


def validate_restaurant_gallery_files(
    files,
    existing_count=0,
):
    total_after_upload = existing_count + len(files)

    if total_after_upload > RESTAURANT_GALLERY_MAX_IMAGES:
        remaining = max(
            RESTAURANT_GALLERY_MAX_IMAGES - existing_count,
            0,
        )

        return (
            False,
            (
                "A restaurant can have a maximum "
                "of 5 gallery photos. "
                f"You can upload {remaining} more."
            ),
        )

    for image in files:
        if not allowed_restaurant_poster_filename(
            image.filename
        ):
            return (
                False,
                (
                    "Gallery photos must be JPG, "
                    "JPEG, PNG or WebP."
                ),
            )

        image.stream.seek(0, os.SEEK_END)
        file_size = image.stream.tell()
        image.stream.seek(0)

        if file_size > RESTAURANT_GALLERY_MAX_FILE_BYTES:
            return (
                False,
                (
                    f"{image.filename} is too large. "
                    "Maximum size is 8 MB per photo."
                ),
            )

    return True, None


def upload_restaurant_gallery_image(
    image,
    organizer_id,
    advert_id,
):
    image.stream.seek(0, os.SEEK_END)
    file_bytes = image.stream.tell()
    image.stream.seek(0)

    result = cloudinary.uploader.upload(
        image,
        resource_type="image",
        folder=(
            "kalxa/"
            f"organizers/{organizer_id}/"
            f"restaurants/{advert_id}/"
            "gallery"
        ),
        use_filename=True,
        unique_filename=True,
        overwrite=False,
    )

    public_id = result.get("public_id")
    secure_url = result.get("secure_url")

    if not public_id or not secure_url:
        raise RuntimeError(
            "Cloudinary did not return "
            "the restaurant gallery image."
        )

    return {
        "public_id": public_id,
        "secure_url": secure_url,
        "width": result.get("width"),
        "height": result.get("height"),
        "file_bytes": file_bytes,
    }



# ============================================================
# STAGE 6B — ORGANISER PAYOUT LEDGER
# READ-ONLY / NO PAYOUT EXECUTION
# ============================================================

from collections import defaultdict
from decimal import Decimal, InvalidOperation

from flask import render_template


# ============================================================
# STAGE 6B — KALXA ORGANISER PAYOUT LEDGER
# ============================================================
#
# PURPOSE:
#
# Provide Super Admin with a read-only financial overview
# of organiser ticket sales, KALXA commissions, verified
# refunds, settlement reconciliation and organiser
# entitlements.
#
# IMPORTANT:
#
# - No Paystack transfers.
# - No organiser payouts.
# - No payout approvals.
# - No financial database writes.
# - No automatic payout jobs.
# - No withdrawable balance calculations.
#
# Settlement matching is not proof of bank receipt.
#
# ============================================================


from decimal import Decimal, InvalidOperation


# ============================================================
# MONEY HELPERS
# ============================================================

_LEDGER_ZERO = Decimal("0.00")
_LEDGER_CENT = Decimal("0.01")


def _ledger_money(value):
    """
    Convert an existing database monetary value to Decimal.

    Missing, invalid or non-finite values return None.

    Financial validation must never silently convert
    missing amounts to zero.
    """

    if value is None:
        return None

    try:

        amount = Decimal(str(value))

        if not amount.is_finite():
            return None

        # Reject values containing fractions of a cent.
        if amount != amount.quantize(_LEDGER_CENT):
            return None

        return amount.quantize(_LEDGER_CENT)

    except (
        InvalidOperation,
        ValueError,
        TypeError,
    ):
        return None


# ============================================================
# EMPTY ORGANISER ACCOUNT
# ============================================================

def _ledger_empty_account(organizer):

    return {

        "organizer": organizer,

        "paid_orders": 0,

        # Original ticket accounting.
        "face_value": _LEDGER_ZERO,
        "commission": _LEDGER_ZERO,
        "gross_entitlement": _LEDGER_ZERO,

        # Verified refund accounting.
        "refunded_face_value": _LEDGER_ZERO,
        "commission_reversed": _LEDGER_ZERO,

        # Refund-adjusted accounting.
        "net_ticket_sales": _LEDGER_ZERO,
        "net_commission": _LEDGER_ZERO,
        "net_entitlement": _LEDGER_ZERO,

        # Local settlement classifications.
        "settled_entitlement": _LEDGER_ZERO,
        "unsettled_entitlement": _LEDGER_ZERO,

        # Order counts.
        "refunded_orders": 0,
        "partially_refunded_orders": 0,
        "pending_refund_orders": 0,

        # Review flags.
        "has_accounting_exceptions": False,
        "exceptions": 0,
    }


# ============================================================
# VALIDATE REFUND ACCOUNTING
# ============================================================

# ============================================================
# STAGE 6B.1 — REFUND ACCOUNTING VALIDATION
# ============================================================

def _ledger_validate_refunds(order):
    """
    Validate TicketOrder refund snapshots against
    individual TicketRefund records.

    READ ONLY.

    Only succeeded refunds with accounting_applied_at
    contribute to cumulative order refund accounting.
    """

    result = {
        "valid": False,
        "refunded_face_value": _LEDGER_ZERO,
        "commission_reversed": _LEDGER_ZERO,
        "pending_refunds": 0,
    }

    # ========================================================
    # ORDER REFUND SNAPSHOTS
    # ========================================================

    order_refunded = _ledger_money(
        order.refunded_face_value
    )

    order_commission_reversed = _ledger_money(
        order.commission_reversed_amount
    )

    if (
        order_refunded is None
        or order_commission_reversed is None
        or order_refunded < 0
        or order_commission_reversed < 0
    ):
        return result

    # ========================================================
    # REFUND RECORDS
    # ========================================================

    applied_face_value = _LEDGER_ZERO

    applied_commission_reversal = _LEDGER_ZERO

    pending_refunds = 0

    for refund in order.refunds:

        refund_status = (
            refund.status or ""
        ).strip().lower()

        face_value = _ledger_money(
            refund.face_value_amount
        )

        provider_amount = _ledger_money(
            refund.provider_refund_amount
        )

        commission_reversal = _ledger_money(
            refund.commission_reversal_amount
        )

        if (
            face_value is None
            or provider_amount is None
            or commission_reversal is None
            or face_value < 0
            or provider_amount < 0
            or commission_reversal < 0
            or commission_reversal > face_value
        ):
            return result

        # ====================================================
        # SUCCESSFUL REFUNDS
        # ====================================================

        if refund_status == "succeeded":

            if refund.accounting_applied_at is None:
                return result

            applied_face_value += face_value

            applied_commission_reversal += (
                commission_reversal
            )

        # ====================================================
        # PENDING REFUNDS
        # ====================================================

        elif refund_status in {
            "requested",
            "submitted",
            "pending",
            "processing",
        }:

            pending_refunds += 1

            if refund.accounting_applied_at is not None:
                return result

        # ====================================================
        # FAILED OR CANCELLED REFUNDS
        # ====================================================

        elif refund_status in {
            "failed",
            "cancelled",
        }:

            if refund.accounting_applied_at is not None:
                return result

        else:
            return result

    # ========================================================
    # RECONCILE REFUND SNAPSHOTS
    # ========================================================

    if (
        applied_face_value != order_refunded
        or applied_commission_reversal
        != order_commission_reversed
    ):
        return result

    result["valid"] = True

    result["refunded_face_value"] = (
        order_refunded
    )

    result["commission_reversed"] = (
        order_commission_reversed
    )

    result["pending_refunds"] = pending_refunds

    return result

# ============================================================
# VALIDATE ORIGINAL ORDER ACCOUNTING
# ============================================================

# ============================================================
# STAGE 6B.1 — ORDER FINANCIAL VALIDATION
# ============================================================

def _ledger_validate_order(order):
    """
    Validate original commission accounting and
    refund-adjusted organiser entitlement.

    Returns validated financial values or None.

    READ ONLY.
    """

    # ========================================================
    # ORIGINAL ACCOUNTING
    # ========================================================

    face_value = _ledger_money(
        order.total_amount
    )

    commission = _ledger_money(
        order.commission_amount
    )

    gross_share = _ledger_money(
        order.organizer_gross_share
    )

    if (
        face_value is None
        or commission is None
        or gross_share is None
        or order.commission_recorded_at is None
    ):
        return None

    if (
        face_value <= 0
        or commission < 0
        or gross_share < 0
        or commission > face_value
        or face_value - commission != gross_share
    ):
        return None

    # ========================================================
    # REFUND ACCOUNTING
    # ========================================================

    refunds = _ledger_validate_refunds(
        order
    )

    if not refunds["valid"]:
        return None

    refunded_face_value = (
        refunds["refunded_face_value"]
    )

    commission_reversed = (
        refunds["commission_reversed"]
    )

    if (
        refunded_face_value > face_value
        or commission_reversed > commission
    ):
        return None

    # ========================================================
    # NET ACCOUNTING
    # ========================================================

    net_ticket_sales = (
        face_value - refunded_face_value
    ).quantize(_LEDGER_CENT)

    net_commission = (
        commission - commission_reversed
    ).quantize(_LEDGER_CENT)

    net_entitlement = (
        gross_share
        - refunded_face_value
        + commission_reversed
    ).quantize(_LEDGER_CENT)

    if (
        net_ticket_sales < 0
        or net_commission < 0
        or net_entitlement < 0
        or net_ticket_sales - net_commission
        != net_entitlement
    ):
        return None

    # ========================================================
    # VERIFIED ACCOUNTING
    # ========================================================

    return {
        "face_value": face_value,
        "commission": commission,
        "gross_entitlement": gross_share,
        "refunded_face_value": refunded_face_value,
        "commission_reversed": commission_reversed,
        "net_ticket_sales": net_ticket_sales,
        "net_commission": net_commission,
        "net_entitlement": net_entitlement,
        "pending_refunds": refunds["pending_refunds"],
        "is_fully_refunded": (
            refunded_face_value == face_value
            and refunded_face_value > 0
        ),
        "is_partially_refunded": (
            refunded_face_value > 0
            and refunded_face_value < face_value
        ),
    }

# ============================================================
# STAGE 6B.1 — ACCOUNTING EXCEPTIONS INSPECTOR
# ============================================================
#
# PURPOSE:
#
# Identify why a paid Paystack ticket order fails
# organiser ledger validation.
#
# READ-ONLY:
#
# - No database writes
# - No commission backfills
# - No refund changes
# - No settlement modifications
# - No payout execution
#
# ============================================================


# ============================================================
# STAGE 6B.1 — ACCOUNTING EXCEPTIONS DIAGNOSTIC
# ============================================================

def _ledger_diagnose_order(order):
    """
    Diagnose financial accounting problems for a
    paid Paystack ticket order.

    Returns a list of human-readable issues.

    READ ONLY.
    """

    issues = []

    # ========================================================
    # ORGANISER OWNERSHIP
    # ========================================================

    event = order.event

    if event is None:

        issues.append(
            "Ticket event is missing."
        )

    elif event.organizer_id is None:

        issues.append(
            "Ticket event has no organiser assigned."
        )

    elif db.session.get(
        Organizer,
        event.organizer_id,
    ) is None:

        issues.append(
            "Assigned organiser does not exist."
        )

    # ========================================================
    # ORIGINAL FINANCIAL VALUES
    # ========================================================

    face_value = _ledger_money(
        order.total_amount
    )

    commission = _ledger_money(
        order.commission_amount
    )

    gross_share = _ledger_money(
        order.organizer_gross_share
    )

    # ========================================================
    # FACE VALUE
    # ========================================================

    if face_value is None:

        issues.append(
            "Ticket face value is missing or invalid."
        )

    elif face_value <= 0:

        issues.append(
            "Paid ticket order has a non-positive face value."
        )

    # ========================================================
    # COMMISSION
    # ========================================================

    if commission is None:

        issues.append(
            "KALXA commission is missing or invalid."
        )

    elif commission < 0:

        issues.append(
            "KALXA commission is negative."
        )

    # ========================================================
    # ORGANISER SHARE
    # ========================================================

    if gross_share is None:

        issues.append(
            "Organiser gross share is missing or invalid."
        )

    elif gross_share < 0:

        issues.append(
            "Organiser gross share is negative."
        )

    # ========================================================
    # COMMISSION RECORDING
    # ========================================================

    if order.commission_recorded_at is None:

        issues.append(
            "Commission recording timestamp is missing."
        )

    # ========================================================
    # ORIGINAL ACCOUNTING EQUATION
    # ========================================================

    if all(
        value is not None
        for value in (
            face_value,
            commission,
            gross_share,
        )
    ):

        if commission > face_value:

            issues.append(
                "KALXA commission exceeds ticket face value."
            )

        if (
            face_value - commission
            != gross_share
        ):

            issues.append(
                "Ticket face value minus KALXA commission "
                "does not equal organiser gross share."
            )

        # ----------------------------------------------------
        # HISTORICAL COMMISSION INDICATOR
        # ----------------------------------------------------
        #
        # This is a diagnostic hint only.
        #
        # It does not automatically classify the order
        # as a verified legacy test transaction.
        #
        # ----------------------------------------------------

        if (
            face_value > 0
            and commission == 0
            and gross_share == 0
        ):

            issues.append(
                "Possible historical pre-commission order: "
                "positive ticket face value with zero "
                "commission and zero organiser share. "
                "Historical test status requires verification."
            )

    # ========================================================
    # REFUND SNAPSHOTS
    # ========================================================

    refunded_face_value = _ledger_money(
        order.refunded_face_value
    )

    commission_reversed = _ledger_money(
        order.commission_reversed_amount
    )

    if refunded_face_value is None:

        issues.append(
            "Refunded ticket value is missing or invalid."
        )

    elif refunded_face_value < 0:

        issues.append(
            "Refunded ticket value is negative."
        )

    if commission_reversed is None:

        issues.append(
            "Commission reversal amount is missing or invalid."
        )

    elif commission_reversed < 0:

        issues.append(
            "Commission reversal amount is negative."
        )

    # ========================================================
    # REFUND LIMITS
    # ========================================================

    if (
        face_value is not None
        and refunded_face_value is not None
        and refunded_face_value > face_value
    ):

        issues.append(
            "Refunded ticket value exceeds original face value."
        )

    if (
        commission is not None
        and commission_reversed is not None
        and commission_reversed > commission
    ):

        issues.append(
            "Commission reversal exceeds original commission."
        )

    # ========================================================
    # INDIVIDUAL REFUND RECORDS
    # ========================================================

    applied_refunds = _LEDGER_ZERO

    applied_reversals = _LEDGER_ZERO

    for refund in order.refunds:

        status = (
            refund.status or ""
        ).strip().lower()

        reference = (
            refund.refund_reference
            or f"Refund #{refund.id}"
        )

        refund_face_value = _ledger_money(
            refund.face_value_amount
        )

        provider_amount = _ledger_money(
            refund.provider_refund_amount
        )

        reversal = _ledger_money(
            refund.commission_reversal_amount
        )

        if (
            refund_face_value is None
            or provider_amount is None
            or reversal is None
        ):

            issues.append(
                f"{reference}: invalid refund financial values."
            )

            continue

        if (
            refund_face_value < 0
            or provider_amount < 0
            or reversal < 0
            or reversal > refund_face_value
        ):

            issues.append(
                f"{reference}: refund amounts are inconsistent."
            )

        if status == "succeeded":

            if refund.accounting_applied_at is None:

                issues.append(
                    f"{reference}: successful refund has "
                    "not been applied to order accounting."
                )

            else:

                applied_refunds += refund_face_value

                applied_reversals += reversal

        elif status in {
            "requested",
            "submitted",
            "pending",
            "processing",
            "failed",
            "cancelled",
        }:

            if refund.accounting_applied_at is not None:

                issues.append(
                    f"{reference}: non-successful refund "
                    "was marked as accounting-applied."
                )

        else:

            issues.append(
                f"{reference}: unknown refund status '{status}'."
            )

    # ========================================================
    # REFUND SNAPSHOT RECONCILIATION
    # ========================================================

    if (
        refunded_face_value is not None
        and applied_refunds != refunded_face_value
    ):

        issues.append(
            "Order refunded ticket value does not match "
            "successfully applied refund records."
        )

    if (
        commission_reversed is not None
        and applied_reversals != commission_reversed
    ):

        issues.append(
            "Order commission reversal total does not match "
            "successfully applied refund records."
        )

    # ========================================================
    # NET ENTITLEMENT
    # ========================================================

    if all(
        value is not None
        for value in (
            face_value,
            commission,
            gross_share,
            refunded_face_value,
            commission_reversed,
        )
    ):

        net_ticket_sales = (
            face_value - refunded_face_value
        )

        net_commission = (
            commission - commission_reversed
        )

        net_entitlement = (
            gross_share
            - refunded_face_value
            + commission_reversed
        )

        if net_ticket_sales < 0:

            issues.append(
                "Net ticket sales are negative."
            )

        if net_commission < 0:

            issues.append(
                "Net KALXA commission is negative."
            )

        if net_entitlement < 0:

            issues.append(
                "Net organiser entitlement is negative."
            )

        if (
            net_ticket_sales - net_commission
            != net_entitlement
        ):

            issues.append(
                "Net ticket sales minus net commission "
                "does not equal net organiser entitlement."
            )

    return issues
# ============================================================
# SUPER ADMIN — ORGANISER PAYOUT LEDGER
# ============================================================

# ============================================================
# STAGE 6B + 6B.1
# KALXA ORGANISER PAYOUT LEDGER
# ACCOUNTING EXCEPTIONS INSPECTOR
# ============================================================
#
# PURPOSE:
#
# Provide Super Admin with a read-only financial overview
# of organiser ticket sales, commissions, verified refunds,
# settlement matching and accounting exceptions.
#
# SECURITY:
#
# - Super Admin access only.
# - No database modifications.
# - No commission backfills.
# - No refund modifications.
# - No settlement modifications.
# - No Paystack transfer requests.
# - No organiser payouts.
#
# IMPORTANT:
#
# Settlement matching does not prove bank receipt.
#
# Net organiser entitlement is not a withdrawable balance.
#
# ============================================================


# ============================================================
# STAGE 6B.1 — ORGANISER PAYOUT LEDGER
# ============================================================

@app.route(
    "/superadmin/organiser-payout-ledger",
    methods=["GET"],
)
def superadmin_organiser_payout_ledger():

    # ========================================================
    # SUPER ADMIN AUTHENTICATION
    # ========================================================

    auth = require_superadmin()

    if auth:
        return auth

    # ========================================================
    # LOAD ORGANISERS
    # ========================================================

    organizers = (
        Organizer.query
        .order_by(
            Organizer.id.asc()
        )
        .all()
    )

    accounts = {
        organizer.id: _ledger_empty_account(organizer)
        for organizer in organizers
    }

    # ========================================================
    # LOAD PAID PAYSTACK ORDERS
    # ========================================================

    orders = (
        TicketOrder.query
        .filter(
            TicketOrder.payment_status == "paid",
            TicketOrder.payment_provider == "paystack",
        )
        .order_by(
            TicketOrder.id.asc()
        )
        .all()
    )

    # ========================================================
    # LOAD RECONCILED SETTLEMENT ALLOCATIONS
    # ========================================================

    reconciled_allocations = (
        db.session.query(
            TicketSettlementAllocation
        )
        .join(
            PaystackSettlement,
            TicketSettlementAllocation.settlement_id
            == PaystackSettlement.id,
        )
        .filter(
            PaystackSettlement.status == "reconciled"
        )
        .all()
    )

    settled_order_ids = {
        allocation.order_id
        for allocation in reconciled_allocations
    }

    # ========================================================
    # ACCOUNTING EXCEPTIONS
    # ========================================================

    unassigned_orders = 0

    exception_records = []

    # ========================================================
    # PROCESS PAID ORDERS
    # ========================================================

    for order in orders:

        event = order.event

        organizer_id = (
            event.organizer_id
            if event is not None
            else None
        )

        # ====================================================
        # RESOLVE ORGANISER ACCOUNT
        # ====================================================

        account = accounts.get(
            organizer_id
        )

        # ====================================================
        # UNASSIGNED OR INVALID ORGANISER
        # ====================================================

        if account is None:

            unassigned_orders += 1

            issues = _ledger_diagnose_order(
                order
            )

            if not any(
                "organiser" in issue.lower()
                or "event" in issue.lower()
                for issue in issues
            ):

                issues.insert(
                    0,
                    "Order does not belong to a valid organiser."
                )

            exception_records.append({
                "order_id": order.id,
                "payment_reference": order.payment_reference,
                "organizer_name": "Unassigned",
                "event_id": order.event_id,
                "face_value": _ledger_money(
                    order.total_amount
                ),
                "issues": issues,
            })

            continue

        # ====================================================
        # VALIDATE ORDER ACCOUNTING
        # ====================================================

        financials = _ledger_validate_order(
            order
        )

        if financials is None:

            account["has_accounting_exceptions"] = True

            account["exceptions"] += 1

            issues = _ledger_diagnose_order(
                order
            )

            if not issues:

                issues = [
                    "Order failed financial validation. "
                    "Further investigation is required."
                ]

            exception_records.append({
                "order_id": order.id,
                "payment_reference": order.payment_reference,
                "organizer_name": (
                    getattr(
                        account["organizer"],
                        "display_name",
                        f"Organiser #{organizer_id}",
                    )
                ),
                "event_id": order.event_id,
                "face_value": _ledger_money(
                    order.total_amount
                ),
                "issues": issues,
            })

            continue

        # ====================================================
        # ORIGINAL ACCOUNTING
        # ====================================================

        account["paid_orders"] += 1

        account["face_value"] += (
            financials["face_value"]
        )

        account["commission"] += (
            financials["commission"]
        )

        account["gross_entitlement"] += (
            financials["gross_entitlement"]
        )

        # ====================================================
        # REFUNDS
        # ====================================================

        account["refunded_face_value"] += (
            financials["refunded_face_value"]
        )

        account["commission_reversed"] += (
            financials["commission_reversed"]
        )

        # ====================================================
        # NET ACCOUNTING
        # ====================================================

        account["net_ticket_sales"] += (
            financials["net_ticket_sales"]
        )

        account["net_commission"] += (
            financials["net_commission"]
        )

        account["net_entitlement"] += (
            financials["net_entitlement"]
        )

        # ====================================================
        # REFUND COUNTS
        # ====================================================

        if financials["is_fully_refunded"]:

            account["refunded_orders"] += 1

        elif financials["is_partially_refunded"]:

            account["partially_refunded_orders"] += 1

        if financials["pending_refunds"] > 0:

            account["pending_refund_orders"] += 1

        # ====================================================
        # SETTLEMENT MATCHING
        # ====================================================

        if order.id in settled_order_ids:

            account["settled_entitlement"] += (
                financials["net_entitlement"]
            )

        else:

            account["unsettled_entitlement"] += (
                financials["net_entitlement"]
            )

    # ========================================================
    # FILTER ORGANISER ACCOUNTS
    # ========================================================

    ledger_accounts = [
        account
        for account in accounts.values()
        if (
            account["paid_orders"] > 0
            or account["exceptions"] > 0
        )
    ]

    # ========================================================
    # FINANCIAL TOTALS
    # ========================================================

    money_fields = (
        "face_value",
        "commission",
        "gross_entitlement",
        "refunded_face_value",
        "commission_reversed",
        "net_ticket_sales",
        "net_commission",
        "net_entitlement",
        "settled_entitlement",
        "unsettled_entitlement",
    )

    count_fields = (
        "paid_orders",
        "refunded_orders",
        "partially_refunded_orders",
        "pending_refund_orders",
    )

    totals = {
        "organizers": len(ledger_accounts),
        "total_paid_orders": len(orders),
        "unassigned_orders": unassigned_orders,
    }

    # ========================================================
    # FINANCIAL AGGREGATION
    # ========================================================

    for field in money_fields:

        totals[field] = sum(
            (
                account[field]
                for account in ledger_accounts
            ),
            _LEDGER_ZERO,
        )

    for field in count_fields:

        totals[field] = sum(
            account[field]
            for account in ledger_accounts
        )

    # ========================================================
    # EXCEPTION TOTALS
    # ========================================================

    totals["accounting_exceptions"] = len(
        exception_records
    )

    totals["validated_orders"] = (
        totals["paid_orders"]
    )

    totals["organizers_with_valid_orders"] = sum(
        1
        for account in ledger_accounts
        if account["paid_orders"] > 0
    )

    totals["organizers_under_review"] = sum(
        1
        for account in ledger_accounts
        if account["exceptions"] > 0
    )

    # ========================================================
    # FINANCIAL CONSISTENCY CHECK
    # ========================================================

    if (
        totals["validated_orders"]
        + totals["accounting_exceptions"]
        != totals["total_paid_orders"]
    ):

        app.logger.error(
            "KALXA LEDGER INCONSISTENCY: "
            "paid=%s validated=%s exceptions=%s",
            totals["total_paid_orders"],
            totals["validated_orders"],
            totals["accounting_exceptions"],
        )

        # Do not show an apparently complete financial
        # report if the order counts are inconsistent.

        raise RuntimeError(
            "Organiser ledger accounting counts "
            "are inconsistent."
        )

    # ========================================================
    # SORT ACCOUNTS
    # ========================================================

    ledger_accounts.sort(
        key=lambda account: (
            -account["net_entitlement"],
            account["organizer"].id,
        )
    )

    # ========================================================
    # SORT EXCEPTIONS
    # ========================================================

    exception_records.sort(
        key=lambda record: record["order_id"]
    )

    # ========================================================
    # RENDER TEMPLATE
    # ========================================================

    return render_template(
        "superadmin/organiser_payout_ledger.html",
        accounts=ledger_accounts,
        totals=totals,
        exception_records=exception_records,
        payouts_enabled=False,
    )
