# ============================================================


          
# ============================================================
# ADMIN - PAUSE RESTAURANT ADVERT
# ============================================================

@app.route(
    "/admin/restaurants/<int:advert_id>/pause",
    methods=[
        "POST",
    ],
)
def admin_pause_restaurant(
    advert_id,
):

    auth = (
        require_ticketing_organizer()
    )


    if auth:
        return auth


    organizer = (
        get_current_organizer()
    )


    advert = (
        RestaurantAdvert.query
        .filter_by(
            id=
                advert_id,

            organizer_id=
                organizer.id,
        )
        .first_or_404()
    )


    advert.active = False


    try:

        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Restaurant Pause] "
                "Failed advert_id=%s error=%s"
            ),
            advert.id,
            error,
        )


        flash(
            "Restaurant advert could not be paused.",
            "error",
        )


        return redirect(
            url_for(
                "admin_manage_restaurant",

                advert_id=
                    advert.id,
            )
        )


    flash(
        "Restaurant advert paused.",
        "success",
    )


    return redirect(
        url_for(
            "admin_manage_restaurant",

            advert_id=
                advert.id,
        )
    )


# ============================================================
# ADMIN - RESUME RESTAURANT ADVERT
# ============================================================

@app.route(
    "/admin/restaurants/<int:advert_id>/resume",
    methods=[
        "POST",
    ],
)
def admin_resume_restaurant(
    advert_id,
):

    auth = (
        require_ticketing_organizer()
    )


    if auth:
        return auth


    subscription_auth = (
        require_restaurant_subscription()
    )


    if subscription_auth:
        return subscription_auth


    organizer = (
        get_current_organizer()
    )


    advert = (
        RestaurantAdvert.query
        .filter_by(
            id=
                advert_id,

            organizer_id=
                organizer.id,
        )
        .first_or_404()
    )


    now = (
        datetime.utcnow()
    )


    if (
        advert.ends_at
        and advert.ends_at <= now
    ):

        flash(
            (
                "This campaign has expired. "
                "Edit the campaign schedule "
                "before resuming it."
            ),
            "error",
        )


        return redirect(
            url_for(
                "admin_manage_restaurant",

                advert_id=
                    advert.id,
            )
        )


    if (
        organizer.subscription_expires_at
        and advert.ends_at
        and advert.ends_at
        > organizer.subscription_expires_at
    ):

        flash(
            (
                "The campaign extends beyond "
                "your current subscription. "
                "Edit its schedule first."
            ),
            "error",
        )


        return redirect(
            url_for(
                "admin_manage_restaurant",

                advert_id=
                    advert.id,
            )
        )


    advert.active = True


    try:

        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Restaurant Resume] "
                "Failed advert_id=%s error=%s"
            ),
            advert.id,
            error,
        )


        flash(
            "Restaurant advert could not be resumed.",
            "error",
        )


        return redirect(
            url_for(
                "admin_manage_restaurant",

                advert_id=
                    advert.id,
            )
        )


    flash(
        "Restaurant advert resumed.",
        "success",
    )


    return redirect(
        url_for(
            "admin_manage_restaurant",

            advert_id=
                advert.id,
        )
    )
# ============================================================
# ORGANIZER - RESTAURANT REEL
# ============================================================


# ============================================================
# STAGE 1D - YOCO SUBSCRIPTION WEBHOOK
# ============================================================

# ============================================================
# YOCO WEBHOOK
# ORGANIZER SUBSCRIPTIONS, RESTAURANT SUBSCRIPTIONS,
# AND RESTAURANT SPECIALS
# ============================================================

@app.route(
    "/webhooks/yoco",
    methods=["POST"],
)
def yoco_webhook():
    """
    Receive and verify Yoco webhook notifications.

    Security:
        - Verify the webhook signature before processing.
        - Never trust the webhook alone as payment proof.
        - Verify the checkout independently with Yoco.

    Supports:
        - Organizer subscription payments.
        - Restaurant subscription payments.
        - Restaurant special payments.

    Idempotency:
        Each payment type uses its own verification and
        activation function.
    """

    # ========================================================
    # READ ORIGINAL REQUEST BODY
    # ========================================================

    raw_body = request.get_data(
        cache=False
    )

    current_app.logger.info(
        "[Yoco] Webhook request received."
    )

    # ========================================================
    # VERIFY WEBHOOK SIGNATURE
    # ========================================================

    try:

        event = verify_yoco_webhook(
            raw_body,
            request.headers,
        )

    except YocoWebhookError:

        current_app.logger.warning(
            "[Yoco] Webhook signature verification failed."
        )

        return jsonify({
            "error": "Invalid webhook",
        }), 400

    # ========================================================
    # VALIDATE VERIFIED EVENT
    # ========================================================

    if not isinstance(event, dict):

        current_app.logger.warning(
            "[Yoco] Verified webhook payload is invalid."
        )

        return jsonify({
            "error": "Invalid event",
        }), 400

    event_type = event.get(
        "type",
        "unknown",
    )

    current_app.logger.info(
        "[Yoco] Verified webhook event type=%s",
        event_type,
    )

    # ========================================================
    # PROCESS PAYMENT
    # ========================================================

    try:

        result = process_yoco_subscription_payment(
            event
        )

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            "[Yoco] Webhook payment processing failed."
        )

        return jsonify({
            "error": "Processing failed",
        }), 500

    # ========================================================
    # LOG RESULT
    # ========================================================

    current_app.logger.info(
        "[Yoco] Webhook processing result=%s",
        result,
    )

    # ========================================================
    # SUCCESS / IGNORED
    # ========================================================

    if result in (
        "ignored",
        "already_paid",
        "activated",
        "paid",
        "success",
        "processed",
    ):

        return jsonify({
            "received": True,
            "result": result,
        }), 200

    # ========================================================
    # UNKNOWN PAYMENT
    # ========================================================

    if result == "unmatched":

        current_app.logger.warning(
            "[Yoco] Verified payment could not be matched.",
        )

        return jsonify({
            "error": "Payment not matched",
        }), 503

    # ========================================================
    # PAYMENT VERIFICATION STILL PENDING
    # ========================================================

    if result == "pending":

        current_app.logger.warning(
            "[Yoco] Payment verification is still pending.",
        )

        return jsonify({
            "received": True,
            "result": "pending",
        }), 503

    # ========================================================
    # INVALID PAYMENT
    # ========================================================

    if result == "invalid":

        current_app.logger.warning(
            "[Yoco] Payment event could not be processed.",
        )

        return jsonify({
            "error": "Payment event invalid",
        }), 422

    # ========================================================
    # UNEXPECTED RESULT
    # ========================================================

    current_app.logger.error(
        "[Yoco] Unexpected processor result=%s",
        result,
    )

    return jsonify({
        "error": "Unexpected processing result",
    }), 500
# ============================================================
# RESTAURANT REEL
# ============================================================
@app.route(
    "/admin/restaurants/<int:advert_id>/reel",
    methods=["GET", "POST"],
)
def admin_restaurant_reel(advert_id):

    # ========================================================
    # ORGANIZER AUTHENTICATION
    # ========================================================

    auth = require_ticketing_organizer()

    if auth:
        return auth

    # ========================================================
    # RESTAURANT ACCOUNT ACCESS
    # ========================================================

    subscription_auth = require_restaurant_subscription()

    if subscription_auth:
        return subscription_auth

    organizer = get_current_organizer()

    if not organizer:
        flash(
            "Organizer account could not be found.",
            "error",
        )

        return redirect(
            url_for("organizer_login")
        )

    # ========================================================
    # ORGANIZER ACTIVE
    # ========================================================

    if not organizer.active:
        flash(
            "Your organizer account is inactive.",
            "error",
        )

        return redirect(
            url_for("organizer_login")
        )

    # ========================================================
    # RESTAURANT ACCOUNT TYPE
    # ========================================================

    if getattr(organizer, "account_type", None) != "restaurant":
        abort(403)

    # ========================================================
    # RESTAURANT OWNERSHIP
    # ========================================================

    advert = (
        RestaurantAdvert.query
        .filter_by(
            id=advert_id,
            organizer_id=organizer.id,
        )
        .first_or_404()
    )

    # ========================================================
    # SYNCHRONIZE RESTAURANT SUBSCRIPTION
    # ========================================================

    sync_restaurant_subscription(advert)

    # ========================================================
    # REEL CAPABILITY
    # ========================================================

    if not advert.can_use_reel:
        abort(403)

    # ========================================================
    # RESTAURANT REEL LIMITS
    # ========================================================

    RESTAURANT_REEL_MAX_DURATION_SECONDS = 90

    RESTAURANT_REEL_MAX_FILE_BYTES = (
        80 * 1024 * 1024
    )

    # ========================================================
    # EXISTING REEL
    # ========================================================

    reel = (
        RestaurantReel.query
        .filter_by(
            advert_id=advert.id,
            organizer_id=organizer.id,
        )
        .first()
    )

    # ========================================================
    # POST - UPLOAD / REPLACE
    # ========================================================

    if request.method == "POST":

        uploaded_public_id = None

        old_public_id = None

        database_committed = False

        try:

            # =================================================
            # REQUEST DIAGNOSTICS
            # =================================================

            current_app.logger.info(
                (
                    "[Restaurant Reel] Incoming request "
                    "advert_id=%s organizer_id=%s "
                    "content_type=%s content_length=%s "
                    "max_content_length=%s"
                ),
                advert.id,
                organizer.id,
                request.content_type,
                request.content_length,
                current_app.config.get(
                    "MAX_CONTENT_LENGTH"
                ),
            )

            # =================================================
            # VERIFY MULTIPART FORM
            # =================================================

            if not request.mimetype == "multipart/form-data":

                current_app.logger.warning(
                    (
                        "[Restaurant Reel] Unexpected request "
                        "content type advert_id=%s "
                        "content_type=%s"
                    ),
                    advert.id,
                    request.content_type,
                )

                flash(
                    (
                        "The upload form was submitted "
                        "incorrectly. Refresh the page, "
                        "select your video again, and retry."
                    ),
                    "error",
                )

                return redirect(
                    url_for(
                        "admin_restaurant_reel",
                        advert_id=advert.id,
                    )
                )

            # =================================================
            # RE-SYNCHRONIZE SUBSCRIPTION
            # =================================================

            sync_restaurant_subscription(advert)

            if not advert.can_use_reel:
                abort(403)

            # =================================================
            # CLOUDINARY CONFIGURATION
            # =================================================

            if not cloudinary_reels_configured():

                current_app.logger.error(
                    (
                        "[Restaurant Reel] Cloudinary is "
                        "not configured advert_id=%s"
                    ),
                    advert.id,
                )

                flash(
                    (
                        "Restaurant Reel storage is not "
                        "configured yet."
                    ),
                    "error",
                )

                return redirect(
                    url_for(
                        "admin_restaurant_reel",
                        advert_id=advert.id,
                    )
                )

            # =================================================
            # INSPECT RECEIVED FILE FIELDS
            # =================================================

            received_file_fields = list(
                request.files.keys()
            )

            current_app.logger.info(
                (
                    "[Restaurant Reel] Received file "
                    "field names advert_id=%s fields=%s"
                ),
                advert.id,
                received_file_fields,
            )

            # =================================================
            # GET VIDEO FILE
            # =================================================

            video = request.files.get("reel_video")

            if video is None:

                current_app.logger.warning(
                    (
                        "[Restaurant Reel] Missing reel_video "
                        "field advert_id=%s "
                        "received_fields=%s "
                        "content_length=%s"
                    ),
                    advert.id,
                    received_file_fields,
                    request.content_length,
                )

                flash(
                    (
                        "No video file reached the server. "
                        "Please select the video again. "
                        "If you are using a phone, try a video "
                        "saved directly to your device."
                    ),
                    "error",
                )

                return redirect(
                    url_for(
                        "admin_restaurant_reel",
                        advert_id=advert.id,
                    )
                )

            # =================================================
            # VERIFY FILENAME
            # =================================================

            if not video.filename:

                current_app.logger.warning(
                    (
                        "[Restaurant Reel] Empty filename "
                        "advert_id=%s fields=%s"
                    ),
                    advert.id,
                    received_file_fields,
                )

                flash(
                    (
                        "The selected video has no filename. "
                        "Please choose the video again."
                    ),
                    "error",
                )

                return redirect(
                    url_for(
                        "admin_restaurant_reel",
                        advert_id=advert.id,
                    )
                )

            # =================================================
            # LOG RECEIVED FILE
            # =================================================

            current_app.logger.info(
                (
                    "[Restaurant Reel] File received "
                    "advert_id=%s organizer_id=%s "
                    "filename=%s mimetype=%s"
                ),
                advert.id,
                organizer.id,
                video.filename,
                video.mimetype,
            )

            # =================================================
            # FILE TYPE
            # =================================================

            if not allowed_event_reel_filename(
                video.filename
            ):

                flash(
                    (
                        "Use an MP4, MOV, M4V or WebM "
                        "video."
                    ),
                    "error",
                )

                return redirect(
                    url_for(
                        "admin_restaurant_reel",
                        advert_id=advert.id,
                    )
                )

            # =================================================
            # FILE SIZE
            # =================================================

            video.stream.seek(
                0,
                os.SEEK_END,
            )

            file_size = video.stream.tell()

            video.stream.seek(
                0,
                os.SEEK_SET,
            )

            if file_size <= 0:

                current_app.logger.warning(
                    (
                        "[Restaurant Reel] Empty uploaded "
                        "file advert_id=%s filename=%s"
                    ),
                    advert.id,
                    video.filename,
                )

                flash(
                    "The selected video file is empty.",
                    "error",
                )

                return redirect(
                    url_for(
                        "admin_restaurant_reel",
                        advert_id=advert.id,
                    )
                )

            if file_size > RESTAURANT_REEL_MAX_FILE_BYTES:

                current_app.logger.warning(
                    (
                        "[Restaurant Reel] File exceeds "
                        "size limit advert_id=%s "
                        "file_size=%s"
                    ),
                    advert.id,
                    file_size,
                )

                flash(
                    (
                        "The reel is too large. "
                        "Maximum size is 80 MB."
                    ),
                    "error",
                )

                return redirect(
                    url_for(
                        "admin_restaurant_reel",
                        advert_id=advert.id,
                    )
                )

            # =================================================
            # LOG UPLOAD START
            # =================================================

            current_app.logger.info(
                (
                    "[Restaurant Reel] Cloudinary upload "
                    "starting advert_id=%s organizer_id=%s "
                    "file_size=%s"
                ),
                advert.id,
                organizer.id,
                file_size,
            )

            # =================================================
            # UPLOAD TO CLOUDINARY
            # =================================================

            upload_result = cloudinary.uploader.upload(
                video,
                resource_type="video",
                folder=(
                    "kalxa/"
                    f"organizers/{organizer.id}/"
                    f"restaurants/{advert.id}/"
                    "reels"
                ),
                use_filename=True,
                unique_filename=True,
                overwrite=False,
            )

            # =================================================
            # VALIDATE CLOUDINARY RESPONSE
            # =================================================

            if not isinstance(upload_result, dict):

                raise RuntimeError(
                    "Cloudinary returned an invalid response."
                )

            uploaded_public_id = upload_result.get(
                "public_id"
            )

            secure_url = upload_result.get(
                "secure_url"
            )

            if not uploaded_public_id or not secure_url:

                raise RuntimeError(
                    (
                        "Cloudinary did not return "
                        "the required video identifiers."
                    )
                )

            # =================================================
            # VIDEO DURATION
            # =================================================

            try:

                duration_seconds = float(
                    upload_result.get("duration") or 0
                )

            except (TypeError, ValueError):

                duration_seconds = 0

            if duration_seconds <= 0:

                raise RuntimeError(
                    (
                        "Cloudinary did not provide "
                        "a valid video duration."
                    )
                )

            # =================================================
            # ENFORCE 90-SECOND LIMIT
            # =================================================

            if (
                duration_seconds
                > RESTAURANT_REEL_MAX_DURATION_SECONDS
            ):

                try:

                    delete_cloudinary_reel(
                        uploaded_public_id
                    )

                except Exception:

                    current_app.logger.exception(
                        (
                            "[Restaurant Reel] Failed to "
                            "delete over-duration video. "
                            "public_id=%s"
                        ),
                        uploaded_public_id,
                    )

                finally:

                    uploaded_public_id = None

                flash(
                    (
                        "Restaurant Reels must be "
                        "1 minute 30 seconds (90 seconds) "
                        "or shorter."
                    ),
                    "error",
                )

                return redirect(
                    url_for(
                        "admin_restaurant_reel",
                        advert_id=advert.id,
                    )
                )

            # =================================================
            # THUMBNAIL
            # =================================================

            thumbnail_url = (
                cloudinary.CloudinaryVideo(
                    uploaded_public_id
                )
                .build_url(
                    resource_type="video",
                    format="jpg",
                    start_offset="1",
                    width=720,
                    crop="limit",
                    secure=True,
                )
            )

            # =================================================
            # REMEMBER EXISTING VIDEO
            # =================================================

            old_public_id = (
                reel.cloudinary_public_id
                if reel
                else None
            )

            # =================================================
            # CREATE REEL
            # =================================================

            if reel is None:

                reel = RestaurantReel(
                    advert_id=advert.id,
                    organizer_id=organizer.id,
                    cloudinary_public_id=uploaded_public_id,
                    video_url=secure_url,
                    thumbnail_url=thumbnail_url,
                    duration_seconds=duration_seconds,
                    width=upload_result.get("width"),
                    height=upload_result.get("height"),
                    file_bytes=upload_result.get("bytes"),
                    active=True,
                )

                db.session.add(reel)

            # =================================================
            # REPLACE REEL
            # =================================================

            else:

                reel.cloudinary_public_id = (
                    uploaded_public_id
                )

                reel.video_url = secure_url

                reel.thumbnail_url = thumbnail_url

                reel.duration_seconds = duration_seconds

                reel.width = upload_result.get("width")

                reel.height = upload_result.get("height")

                reel.file_bytes = upload_result.get("bytes")

                reel.active = True

            # =================================================
            # COMMIT DATABASE
            # =================================================

            db.session.commit()

            database_committed = True

            # =================================================
            # REMOVE PREVIOUS VIDEO
            # =================================================

            if (
                old_public_id
                and old_public_id != uploaded_public_id
            ):

                try:

                    delete_cloudinary_reel(
                        old_public_id
                    )

                except Exception:

                    current_app.logger.exception(
                        (
                            "[Restaurant Reel] Previous "
                            "video cleanup failed. "
                            "public_id=%s"
                        ),
                        old_public_id,
                    )

            # =================================================
            # SUCCESS LOG
            # =================================================

            current_app.logger.info(
                (
                    "[Restaurant Reel] Upload completed "
                    "advert_id=%s organizer_id=%s "
                    "public_id=%s duration=%s"
                ),
                advert.id,
                organizer.id,
                uploaded_public_id,
                duration_seconds,
            )

            # =================================================
            # SUCCESS MESSAGE
            # =================================================

            flash(
                "Restaurant Reel published successfully.",
                "success",
            )

            return redirect(
                url_for(
                    "admin_restaurant_reel",
                    advert_id=advert.id,
                )
            )

        except Exception:

            # =================================================
            # DATABASE ROLLBACK
            # =================================================

            if not database_committed:

                db.session.rollback()

            # =================================================
            # CLEAN UP NEW VIDEO
            # =================================================

            if (
                uploaded_public_id
                and not database_committed
            ):

                try:

                    delete_cloudinary_reel(
                        uploaded_public_id
                    )

                except Exception:

                    current_app.logger.exception(
                        (
                            "[Restaurant Reel] Failed to "
                            "clean up uploaded video. "
                            "public_id=%s"
                        ),
                        uploaded_public_id,
                    )

            # =================================================
            # LOG ERROR WITH TRACEBACK
            # =================================================

            current_app.logger.exception(
                (
                    "[Restaurant Reel] Upload failed "
                    "advert_id=%s organizer_id=%s"
                ),
                advert.id,
                organizer.id,
            )

            # =================================================
            # USER MESSAGE
            # =================================================

            flash(
                (
                    "Kalxa could not upload this restaurant "
                    "reel. Check your connection and try "
                    "again. If the problem continues, "
                    "check the application logs."
                ),
                "error",
            )

            return redirect(
                url_for(
                    "admin_restaurant_reel",
                    advert_id=advert.id,
                )
            )

    # ========================================================
    # GET - RENDER PAGE
    # ========================================================

    return render_template(
        "admin/restaurant_reel.html",
        organizer=organizer,
        advert=advert,
        reel=reel,
        restaurant_plan=advert.normalized_subscription_tier,
        restaurant_plan_name=advert.subscription_plan_name,
        can_use_reel=advert.can_use_reel,
    )
# ============================================================
# RESTAURANT EXPERIENCE POSTS
# ============================================================
#
# Public customer-generated content.
#
# Users do NOT need a Kalxa account.
#
# Supported media:
#
# - image
# - short video / reel
#
# Images use the same 8 MB limit as restaurant posters.
# Videos use the same 80 MB / 30 second limits as event reels.
# ============================================================


# ============================================================
# EXPERIENCE MEDIA TYPE
# ============================================================

def get_restaurant_experience_media_type(
    filename,
):

    filename = (
        str(
            filename
            or ""
        )
        .strip()
        .lower()
    )


    if (
        "." not in filename
    ):

        return None


    extension = (
        filename
        .rsplit(
            ".",
            1,
        )[1]
    )


    if (
        extension
        in RESTAURANT_EXPERIENCE_IMAGE_EXTENSIONS
    ):

        return "image"


    if (
        extension
        in RESTAURANT_EXPERIENCE_VIDEO_EXTENSIONS
    ):

        return "video"


    return None


# ============================================================
# ANONYMOUS EXPERIENCE SESSION
# ============================================================
#
# Used for ❤️ loves.
#
# No Kalxa account is required.
#
# The random identifier is stored inside the user's Flask
# session cookie and does not contain their name, email
# or phone number.
# ============================================================

def get_restaurant_experience_session_id():

    session_key = (
        "kalxa_restaurant_experience_session"
    )


    anonymous_session_id = (
        session.get(
            session_key
        )
    )


    if not anonymous_session_id:

        anonymous_session_id = (
            secrets.token_urlsafe(
                32
            )
        )


        session[
            session_key
        ] = (
            anonymous_session_id
        )


    return anonymous_session_id




