# ============================================================
# ORGANIZER - DELETE RESTAURANT REEL
# ============================================================

@app.route(
    "/admin/restaurants/<int:advert_id>/reel/delete",
    methods=[
        "POST",
    ],
)
def admin_delete_restaurant_reel(
    advert_id,
):

    # ========================================================
    # ORGANIZER AUTH
    # ========================================================

    auth = (
        require_ticketing_organizer()
    )


    if auth:
        return auth


    # ========================================================
    # ACTIVE RESTAURANT SUBSCRIPTION REQUIRED
    # ========================================================

    subscription_auth = (
        require_restaurant_subscription()
    )


    if subscription_auth:
        return subscription_auth


    organizer = (
        get_current_organizer()
    )


    # ========================================================
    # OWNERSHIP
    # ========================================================

    advert = (
        RestaurantAdvert.query
        .filter_by(
            id=
                advert_id,

            organizer_id=
                organizer.id,
        )
        .first_or_404()
    )


    reel = (
        RestaurantReel.query
        .filter_by(
            advert_id=
                advert.id,

            organizer_id=
                organizer.id,
        )
        .first_or_404()
    )


    public_id = (
        reel.cloudinary_public_id
    )


    # ========================================================
    # DELETE DATABASE RECORD
    # ========================================================

    try:

        db.session.delete(
            reel
        )


        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Restaurant Reel Delete] "
                "Failed "
                "organizer_id=%s "
                "advert_id=%s "
                "error=%s"
            ),
            organizer.id,
            advert.id,
            error,
        )


        flash(
            (
                "Unable to remove the "
                "restaurant reel."
            ),
            "error",
        )


        return redirect(
            url_for(
                "admin_restaurant_reel",

                advert_id=
                    advert.id,
            )
        )


    # ========================================================
    # DELETE CLOUDINARY VIDEO
    # ========================================================

    if public_id:

        try:

            delete_cloudinary_reel(
                public_id
            )


        except Exception as error:

            current_app.logger.warning(
                (
                    "[Restaurant Reel Delete] "
                    "Database reel was removed, "
                    "but Cloudinary cleanup failed "
                    "public_id=%s "
                    "error=%s"
                ),
                public_id,
                error,
            )


    # ========================================================
    # SUCCESS
    # ========================================================

    flash(
        "Restaurant Reel removed.",
        "success",
    )


    return redirect(
        url_for(
            "admin_restaurants"
        )
    )
