@app.route(
    "/organizer/signup",
    methods=[
        "GET",
        "POST",
    ],
)
def organizer_signup():

    # ========================================================
    # ALREADY LOGGED IN
    # ========================================================

    existing_organizer = (
        get_current_organizer()
    )


    if existing_organizer:

        return redirect(
            url_for(
                organizer_home_endpoint(
                    existing_organizer
                )
            )
        )


    # ========================================================
    # CREATE ACCOUNT
    # ========================================================

    if request.method == "POST":

        # ====================================================
        # ACCOUNT TYPE
        # ====================================================

        account_type = (
            request.form.get(
                "account_type",
                "",
            )
            .strip()
            .lower()
        )


        if account_type not in {
            "event",
            "restaurant",
        }:

            flash(
                (
                    "Choose whether you are "
                    "creating an Event or "
                    "Restaurant account."
                ),
                "error",
            )

            return render_template(
                "organizer/signup.html"
            )


        # ====================================================
        # NAME
        # ====================================================

        name = (
            request.form.get(
                "name",
                "",
            )
            .strip()
        )


        # ====================================================
        # BUSINESS / BRAND NAME
        # ====================================================

        business_name = (
            request.form.get(
                "business_name",
                "",
            )
            .strip()
            or None
        )


        # ====================================================
        # EMAIL
        # ====================================================

        email = (
            normalize_email(
                request.form.get(
                    "email",
                    "",
                )
            )
        )


        # ====================================================
        # PHONE
        # ====================================================

        phone = (
            request.form.get(
                "phone",
                "",
            )
            .strip()
            or None
        )


        # ====================================================
        # PASSWORD
        # ====================================================

        password = (
            request.form.get(
                "password",
                "",
            )
        )


        password_confirm = (
            request.form.get(
                "password_confirm",
                "",
            )
        )


        # ====================================================
        # REQUIRED FIELDS
        # ====================================================

        if (
            not name
            or not email
            or not password
        ):

            flash(
                (
                    "Name, email and password "
                    "are required."
                ),
                "error",
            )

            return render_template(
                "organizer/signup.html"
            )


        # ====================================================
        # PASSWORD LENGTH
        # ====================================================

        if (
            len(
                password
            )
            < 8
        ):

            flash(
                (
                    "Password must be at least "
                    "8 characters."
                ),
                "error",
            )

            return render_template(
                "organizer/signup.html"
            )


        # ====================================================
        # PASSWORD CONFIRMATION
        # ====================================================

        if (
            password
            != password_confirm
        ):

            flash(
                "Passwords do not match.",
                "error",
            )

            return render_template(
                "organizer/signup.html"
            )


        # ====================================================
        # EXISTING EMAIL
        # ====================================================

        existing = (
            Organizer.query
            .filter_by(
                email=email
            )
            .first()
        )


        if existing:

            flash(
                (
                    "An account already exists "
                    "with that email."
                ),
                "error",
            )

            return redirect(
                url_for(
                    "organizer_login"
                )
            )


        # ====================================================
        # CREATE ORGANIZER
        # ====================================================
        #
        # IMPORTANT:
        #
        # account_type is stored explicitly.
        #
        # event
        # restaurant
        #
        # This prevents restaurant accounts from falling back
        # to the Organizer model's default "event" value.
        # ====================================================

        organizer = (
            Organizer(
                name=
                    name,

                business_name=
                    business_name,

                email=
                    email,

                phone=
                    phone,

                account_type=
                    account_type,

                active=
                    True,
            )
        )


        organizer.set_password(
            password
        )


        # ====================================================
        # SAVE
        # ====================================================

        try:

            db.session.add(
                organizer
            )

            db.session.commit()


        except Exception as error:

            db.session.rollback()


            current_app.logger.exception(
                (
                    "[Organizer Signup] "
                    "Unable to create organizer "
                    "email=%s "
                    "account_type=%s "
                    "error=%s"
                ),
                email,
                account_type,
                error,
            )


            flash(
                (
                    "Unable to create your account. "
                    "Please try again."
                ),
                "error",
            )

            return render_template(
                "organizer/signup.html"
            )


        # ====================================================
        # SUCCESS
        # ====================================================

        session.clear()


        if (
            account_type
            == "restaurant"
        ):

            flash(
                (
                    "Restaurant advertiser account "
                    "created successfully. "
                    "Please sign in."
                ),
                "success",
            )

        else:

            flash(
                (
                    "Event organizer account "
                    "created successfully. "
                    "Please sign in."
                ),
                "success",
            )


        return redirect(
            url_for(
                "organizer_login"
            )
        )


    # ========================================================
    # GET
    # ========================================================

    return render_template(
        "organizer/signup.html"
    )



# ============================================================
# KALXA TICKETING - ORGANIZER ACCESS HELPERS
# ============================================================

def get_current_organizer():

    # ========================================================
    # ORGANIZER SESSION ID
    # ========================================================

    organizer_id = session.get(
        ORGANIZER_SESSION_KEY
    )

    if not organizer_id:
        return None

    # ========================================================
    # VALIDATE ORGANIZER ID
    # ========================================================

    try:
        organizer_id = int(organizer_id)

    except (TypeError, ValueError):

        session.pop(
            ORGANIZER_SESSION_KEY,
            None,
        )

        return None

    # ========================================================
    # LOAD ORGANIZER
    # ========================================================

    organizer = db.session.get(
        Organizer,
        organizer_id,
    )

    if not organizer:

        session.pop(
            ORGANIZER_SESSION_KEY,
            None,
        )

        return None

    # ========================================================
    # NORMALIZE ACCOUNT TYPE
    # ========================================================

    account_type = (
        str(
            getattr(
                organizer,
                "account_type",
                None,
            )
            or "event"
        )
        .strip()
        .lower()
    )

    if account_type not in {
        "event",
        "restaurant",
    }:
        account_type = "event"

    # ========================================================
    # RESTAURANT ACCOUNTS
    # ========================================================
    #
    # Preserve the existing active-account requirement.
    #
    # Restaurant subscriptions remain separate from event
    # organiser approval.
    # ========================================================

    if account_type == "restaurant":

        if not organizer.active:

            session.pop(
                ORGANIZER_SESSION_KEY,
                None,
            )

            return None

    # ========================================================
    # EVENT ORGANISER ACCOUNTS
    # ========================================================
    #
    # Pending and rejected event organisers can remain
    # authenticated so they can view their application status.
    #
    # Approval and suspension are enforced by permission
    # checks, not by logging out pending applicants.
    # ========================================================

    return organizer


# ============================================================
# REQUIRE AUTHENTICATED ORGANIZER
# ============================================================




# ============================================================
# LEGACY SUBSCRIPTION GUARD - COMPATIBILITY
# ============================================================
#
# Existing event routes may still call:
#
# require_active_subscription(organizer)
#
# Keep this function temporarily to prevent those routes
# from breaking during the transition.
#
# It now checks event approval instead of subscription expiry.
#
# IMPORTANT:
# Replace calls with require_approved_event_organizer()
# as we review each event route.
# ============================================================

def require_active_subscription(organizer):

    auth = require_ticketing_organizer()

    if auth:
        return auth

    current_organizer = get_current_organizer()

    if (
        not organizer
        or not current_organizer
        or organizer.id != current_organizer.id
    ):

        flash(
            "Unable to verify your organiser account.",
            "error",
        )

        return redirect(
            url_for("admin_dashboard")
        )

    return require_approved_event_organizer()


