@app.route(
    "/organizer/forgot-password",
    methods=[
        "GET",
        "POST",
    ],
)
def organizer_forgot_password():

    if request.method == "POST":

        email = (
            normalize_email(
                request.form.get(
                    "email",
                    "",
                )
            )
        )


        if not email:

            flash(
                "Enter your email address.",
                "error",
            )


            return render_template(
                "organizer/forgot_password.html"
            )


        organizer = (
            Organizer.query
            .filter_by(
                email=email
            )
            .first()
        )


        # ====================================================
        # IMPORTANT:
        #
        # We intentionally give the same public response
        # whether the email exists or not.
        #
        # This prevents account/email enumeration.
        # ====================================================

        if organizer:

            try:

                token = (
                    create_organizer_password_reset_token(
                        organizer
                    )
                )


                reset_url = (
                    url_for(
                        "organizer_reset_password",

                        token=
                            token,

                        _external=
                            True,
                    )
                )


                send_organizer_password_reset_email(
                    organizer,
                    reset_url,
                )


                current_app.logger.info(
                    (
                        "[Password Reset] "
                        "Reset email sent "
                        "organizer_id=%s"
                    ),
                    organizer.id,
                )


            except Exception as error:

                current_app.logger.exception(
                    (
                        "[Password Reset] "
                        "Unable to send reset email "
                        "organizer_id=%s "
                        "error=%s"
                    ),
                    organizer.id,
                    error,
                )


        flash(
            (
                "If an account exists for that "
                "email address, a password-reset "
                "link has been sent."
            ),
            "success",
        )


        return redirect(
            url_for(
                "organizer_forgot_password"
            )
        )


    return render_template(
        "organizer/forgot_password.html"
    )


# ============================================================
# ORGANIZER - RESET PASSWORD
# ============================================================

@app.route(
    "/organizer/reset-password/<token>",
    methods=[
        "GET",
        "POST",
    ],
)
def organizer_reset_password(
    token,
):

    organizer, token_error = (
        verify_organizer_password_reset_token(
            token
        )
    )


    # ========================================================
    # INVALID / EXPIRED TOKEN
    # ========================================================

    if not organizer:

        if (
            token_error
            == "expired"
        ):

            flash(
                (
                    "That password-reset link "
                    "has expired. "
                    "Request a new one."
                ),
                "error",
            )

        else:

            flash(
                (
                    "That password-reset link "
                    "is invalid. "
                    "Request a new one."
                ),
                "error",
            )


        return redirect(
            url_for(
                "organizer_forgot_password"
            )
        )


    # ========================================================
    # SET NEW PASSWORD
    # ========================================================

    if request.method == "POST":

        password = (
            request.form.get(
                "password",
                "",
            )
        )


        password_confirm = (
            request.form.get(
                "password_confirm",
                "",
            )
        )


        if (
            not password
            or not password_confirm
        ):

            flash(
                (
                    "Enter and confirm "
                    "your new password."
                ),
                "error",
            )


            return render_template(
                "organizer/reset_password.html",

                token=
                    token,

                organizer=
                    organizer,
            )


        if (
            len(
                password
            )
            < 8
        ):

            flash(
                (
                    "Password must be at least "
                    "8 characters."
                ),
                "error",
            )


            return render_template(
                "organizer/reset_password.html",

                token=
                    token,

                organizer=
                    organizer,
            )


        if (
            password
            != password_confirm
        ):

            flash(
                "Passwords do not match.",
                "error",
            )


            return render_template(
                "organizer/reset_password.html",

                token=
                    token,

                organizer=
                    organizer,
            )


        try:

            organizer.set_password(
                password
            )


            db.session.commit()


        except Exception as error:

            db.session.rollback()


            current_app.logger.exception(
                (
                    "[Password Reset] "
                    "Unable to reset password "
                    "organizer_id=%s "
                    "error=%s"
                ),
                organizer.id,
                error,
            )


            flash(
                (
                    "Your password could not "
                    "be updated. Please try again."
                ),
                "error",
            )


            return render_template(
                "organizer/reset_password.html",

                token=
                    token,

                organizer=
                    organizer,
            )


        # ====================================================
        # REMOVE EXISTING LOGIN SESSION
        # ====================================================

        session.clear()


        flash(
            (
                "Your password has been updated. "
                "You can now sign in."
            ),
            "success",
        )


        return redirect(
            url_for(
                "organizer_login"
            )
        )


    return render_template(
        "organizer/reset_password.html",

        token=
            token,

        organizer=
            organizer,
    )
