# ============================================================
# RESTAURANT RATING QR HELPERS
# ============================================================


def generate_restaurant_rating_public_code():
    """
    Generate a short public Kalxa restaurant QR code.

    Example:

        KX-A7F92C4D

    The database ID is intentionally not exposed in the
    customer-facing QR URL.
    """

    while True:

        public_code = (
            "KX-"
            + secrets.token_hex(4).upper()
        )

        existing_qr = (
            RestaurantRatingQRCode.query
            .filter_by(
                public_code=public_code
            )
            .first()
        )

        if not existing_qr:
            return public_code


def get_or_create_restaurant_main_qr(
    advert,
):
    """
    Return the restaurant's permanent main QR record.

    If one does not exist yet, create it.

    The same restaurant should continue using the same QR
    instead of generating a different code every time the
    owner opens the page.
    """

    restaurant_qr = (
        RestaurantRatingQRCode.query

        .filter_by(
            restaurant_advert_id=
                advert.id,

            placement_type=
                "main",
        )

        .order_by(
            RestaurantRatingQRCode.created_at.asc()
        )

        .first()
    )


    if restaurant_qr:

        # If it was previously disabled, keep the existing
        # permanent code but activate it again.
        if not restaurant_qr.active:

            restaurant_qr.active = True

            db.session.commit()

        return restaurant_qr


    restaurant_qr = (
        RestaurantRatingQRCode(
            restaurant_advert_id=
                advert.id,

            public_code=
                generate_restaurant_rating_public_code(),

            placement_type=
                "main",

            placement_label=
                "Main restaurant QR",

            active=
                True,
        )
    )


    db.session.add(
        restaurant_qr
    )

    db.session.commit()


    return restaurant_qr


# ============================================================
# RESTAURANT EXPERIENCE VIEW ANALYTICS
# ============================================================

@app.route(
    (
        "/restaurant/<int:advert_id>"
        "/analytics/experience/"
        "<int:post_id>/view"
    ),
    methods=["POST"],
)
def restaurant_experience_view_analytics(
    advert_id,
    post_id,
):

    # ========================================================
    # RESTAURANT
    # ========================================================

    advert = (
        RestaurantAdvert.query
        .filter_by(
            id=advert_id,
            active=True,
        )
        .first_or_404()
    )


    # ========================================================
    # EXPERIENCE POST
    #
    # Only approved, active experiences belonging to this
    # restaurant can generate an experience_view event.
    # ========================================================

    post = (
        RestaurantExperiencePost.query
        .filter_by(
            id=post_id,
            restaurant_advert_id=advert.id,
            active=True,
            moderation_status="approved",
        )
        .first_or_404()
    )


    # ========================================================
    # RECORD ANALYTICS
    #
    # Attribution already lives in the Ticketing session.
    #
    # If this visitor arrived from Kalxa Stories, the existing
    # record_restaurant_analytics_event() helper automatically
    # attaches:
    #
    # source = kalxa_stories
    # source_article_id
    # source_restaurant_id
    # source_session_id
    #
    # We keep the experience post ID inside event_metadata
    # because RestaurantAnalyticsEvent currently has no
    # dedicated experience_post_id column.
    # ========================================================

    recorded = (
        record_restaurant_analytics_event(
            restaurant_id=advert.id,
            event_type="experience_view",
            metadata={
                "experience_post_id":
                    post.id,
            },
            deduplicate=True,
        )
    )


    # ========================================================
    # RESPONSE
    # ========================================================

    return jsonify({
        "ok": True,

        "recorded":
            bool(
                recorded
            ),

        "event_type":
            "experience_view",

        "restaurant_id":
            advert.id,

        "experience_post_id":
            post.id,
    })
# ============================================================
# RESTAURANT RATING QR - PNG IMAGE
# ============================================================

@app.route(
    "/restaurant/<int:advert_id>/rating-qr.png"
)
def restaurant_rating_qr_image(
    advert_id,
):

    # ========================================================
    # ORGANIZER AUTHENTICATION
    # ========================================================

    current_organizer = (
        get_current_organizer()
    )


    if not current_organizer:

        abort(401)


    # ========================================================
    # RESTAURANT
    # ========================================================

    advert = (
        RestaurantAdvert.query

        .filter_by(
            id=
                advert_id
        )

        .first_or_404()
    )


    # ========================================================
    # OWNERSHIP
    # ========================================================

    if (
        advert.organizer_id
        !=
        current_organizer.id
    ):

        abort(403)


    # ========================================================
    # SUBSCRIPTION
    # ========================================================

    if (
        not advert.organizer
        or
        not advert.organizer.is_subscription_active
    ):

        abort(403)


    # ========================================================
    # GET OR CREATE PERMANENT QR
    # ========================================================

    restaurant_qr = (
        get_or_create_restaurant_main_qr(
            advert
        )
    )


    # ========================================================
    # PUBLIC QR DESTINATION
    # ========================================================

    rating_url = (
        url_for(
            "restaurant_rating_qr_page",

            public_code=
                restaurant_qr.public_code,

            _external=True,

            _scheme="https",
        )
    )


    # ========================================================
    # GENERATE QR
    # ========================================================

    qr = qrcode.QRCode(
        version=None,

        error_correction=
            qrcode.constants.ERROR_CORRECT_M,

        box_size=12,

        border=4,
    )


    qr.add_data(
        rating_url
    )


    qr.make(
        fit=True
    )


    qr_image = (
        qr.make_image(
            fill_color="black",
            back_color="white",
        )
    )


    # ========================================================
    # WRITE PNG INTO MEMORY
    # ========================================================

    image_buffer = (
        io.BytesIO()
    )


    qr_image.save(
        image_buffer,
        format="PNG",
    )


    image_buffer.seek(
        0
    )


    # ========================================================
    # DOWNLOAD FILE NAME
    # ========================================================

    safe_business_name = (
        "".join(
            character
            if (
                character.isalnum()
                or character in {
                    "-",
                    "_",
                }
            )
            else "-"
            for character
            in advert.business_name
        )
        .strip("-")
        .lower()
    )


    if not safe_business_name:

        safe_business_name = (
            f"restaurant-{advert.id}"
        )


    filename = (
        f"kalxa-{safe_business_name}-rating-qr.png"
    )


    # ========================================================
    # RETURN PNG
    # ========================================================

    return send_file(
        image_buffer,

        mimetype=
            "image/png",

        as_attachment=
            False,

        download_name=
            filename,

        max_age=
            0,
    )



# ============================================================
# KALXA INTERNAL ANALYTICS API
# ============================================================
#
# This API allows trusted Kalxa services such as
# Kalxa Stories to retrieve aggregated Ticketing conversion
# data.
#
# IMPORTANT:
#
# - This is NOT a public analytics endpoint.
# - It returns aggregate counts only.
# - It does NOT return session IDs.
# - It does NOT return source session IDs.
# - It does NOT return individual analytics events.
# ============================================================


KALXA_INTERNAL_API_KEY = (
    os.getenv(
        "KALXA_INTERNAL_API_KEY",
        "",
    )
    .strip()
)


# ============================================================
# VERIFY INTERNAL API KEY
# ============================================================

def kalxa_internal_api_authorized():
    """
    Verify that the request came from another trusted
    Kalxa service.

    The caller must send:

        X-Kalxa-Internal-Key: <secret>

    hmac.compare_digest() is used instead of normal string
    comparison.
    """

    configured_key = (
        KALXA_INTERNAL_API_KEY
    )


    if not configured_key:

        current_app.logger.error(
            "KALXA_INTERNAL_API_KEY "
            "is not configured."
        )

        return False


    supplied_key = (
        request.headers
        .get(
            "X-Kalxa-Internal-Key",
            "",
        )
        .strip()
    )


    if not supplied_key:

        return False


    return hmac.compare_digest(
        configured_key,
        supplied_key,
    )


# ============================================================
# PARSE STORY IDS
# ============================================================

def parse_internal_story_ids(
    raw_value,
):
    """
    Convert:

        1,2,3

    into:

        [1, 2, 3]

    Invalid values are ignored.

    A maximum of 100 story IDs is accepted per request.
    """

    if not raw_value:

        return []


    story_ids = []


    for raw_id in raw_value.split(","):

        raw_id = (
            raw_id.strip()
        )


        if not raw_id:

            continue


        try:

            story_id = int(
                raw_id
            )

        except (
            TypeError,
            ValueError,
        ):

            continue


        if story_id <= 0:

            continue


        if story_id in story_ids:

            continue


        story_ids.append(
            story_id
        )


        if len(
            story_ids
        ) >= 100:

            break


    return story_ids


# ============================================================
# PRIVATE RESTAURANT ANALYTICS
# ============================================================

@app.route(
    "/api/internal/restaurant-analytics",
    methods=["GET"],
)
def internal_restaurant_analytics():
    """
    Return aggregated Kalxa Ticketing restaurant analytics
    attributed to Kalxa Stories.

    Example request:

        /api/internal/restaurant-analytics
            ?story_ids=1,2,3
            &start_at=2026-09-26T00:00:00+00:00
            &end_at=2026-10-03T00:00:00+00:00

    Required header:

        X-Kalxa-Internal-Key: <secret>

    Optional query parameters:

        start_at
        end_at

    When start_at and end_at are omitted, the endpoint
    returns all-time analytics.

    The endpoint intentionally returns aggregate data only.
    """


    # ========================================================
    # AUTHENTICATION
    # ========================================================

    if not kalxa_internal_api_authorized():

        return jsonify(
            {
                "ok": False,
                "error":
                    "unauthorized",
            }
        ), 401


    # ========================================================
    # STORY IDS
    # ========================================================

    story_ids = (
        parse_internal_story_ids(
            request.args.get(
                "story_ids",
                "",
            )
        )
    )


    if not story_ids:

        return jsonify(
            {
                "ok": False,
                "error":
                    "story_ids_required",
            }
        ), 400


    # ========================================================
    # ANALYTICS DATE RANGE
    # ========================================================
    #
    # Kalxa Stories sends UTC ISO-8601 values:
    #
    #     start_at=2026-09-26T00:00:00+00:00
    #     end_at=2026-10-03T00:00:00+00:00
    #
    # Both are optional.
    #
    # If neither is supplied, analytics remain all-time.
    # ========================================================

    start_at_raw = (
        request.args
        .get(
            "start_at",
            "",
        )
        .strip()
    )

    end_at_raw = (
        request.args
        .get(
            "end_at",
            "",
        )
        .strip()
    )


    start_at = None
    end_at = None


    # --------------------------------------------------------
    # PARSE START DATE
    # --------------------------------------------------------

    if start_at_raw:

        try:

            normalized_start_at = (
                start_at_raw
                .replace(
                    "Z",
                    "+00:00",
                )
            )

            start_at = (
                datetime.fromisoformat(
                    normalized_start_at
                )
            )

            if start_at.tzinfo is None:

                start_at = (
                    start_at.replace(
                        tzinfo=timezone.utc
                    )
                )

            else:

                start_at = (
                    start_at.astimezone(
                        timezone.utc
                    )
                )

        except (
            TypeError,
            ValueError,
        ):

            return jsonify(
                {
                    "ok": False,
                    "error":
                        "invalid_start_at",
                }
            ), 400


    # --------------------------------------------------------
    # PARSE END DATE
    # --------------------------------------------------------

    if end_at_raw:

        try:

            normalized_end_at = (
                end_at_raw
                .replace(
                    "Z",
                    "+00:00",
                )
            )

            end_at = (
                datetime.fromisoformat(
                    normalized_end_at
                )
            )

            if end_at.tzinfo is None:

                end_at = (
                    end_at.replace(
                        tzinfo=timezone.utc
                    )
                )

            else:

                end_at = (
                    end_at.astimezone(
                        timezone.utc
                    )
                )

        except (
            TypeError,
            ValueError,
        ):

            return jsonify(
                {
                    "ok": False,
                    "error":
                        "invalid_end_at",
                }
            ), 400


    # --------------------------------------------------------
    # VALIDATE RANGE
    # --------------------------------------------------------

    if (
        start_at is not None
        and
        end_at is not None
        and
        start_at >= end_at
    ):

        return jsonify(
            {
                "ok": False,
                "error":
                    "invalid_date_range",
            }
        ), 400


    # ========================================================
    # SUPPORTED CONVERSION EVENTS
    # ========================================================

    supported_events = (
        "restaurant_view",
        "experience_view",
        "whatsapp_click",
        "phone_click",
        "directions_click",
    )


    # ========================================================
    # BASE ANALYTICS FILTERS
    # ========================================================
    #
    # These filters are shared by:
    #
    # 1. event-count analytics
    # 2. unique-session analytics
    #
    # This is important because both queries must represent
    # exactly the same selected dashboard period.
    # ========================================================

    analytics_filters = [
        (
            RestaurantAnalyticsEvent.source
            == "kalxa_stories"
        ),

        (
            RestaurantAnalyticsEvent
            .source_article_id
            .in_(
                story_ids
            )
        ),
    ]


    # --------------------------------------------------------
    # START DATE
    # --------------------------------------------------------

    if start_at is not None:

        analytics_filters.append(
            (
                RestaurantAnalyticsEvent
                .created_at
                >= start_at
            )
        )


    # --------------------------------------------------------
    # END DATE
    # --------------------------------------------------------
    #
    # We use < rather than <= so date windows can be treated
    # as half-open intervals:
    #
    #     start_at <= event < end_at
    #
    # This prevents boundary events from being counted twice
    # if adjacent reporting periods are used later.
    # --------------------------------------------------------

    if end_at is not None:

        analytics_filters.append(
            (
                RestaurantAnalyticsEvent
                .created_at
                < end_at
            )
        )


    # ========================================================
    # EVENT COUNT QUERY
    # ========================================================
    #
    # Only events carrying verified Kalxa Stories attribution
    # are included.
    #
    # Group by:
    #
    #     story
    #     restaurant
    #     event type
    #
    # This keeps the response small even when the underlying
    # event table eventually contains millions of events.
    # ========================================================

    rows = (
        db.session.query(

            RestaurantAnalyticsEvent
            .source_article_id
            .label(
                "story_id"
            ),

            RestaurantAnalyticsEvent
            .restaurant_id
            .label(
                "restaurant_id"
            ),

            RestaurantAnalyticsEvent
            .event_type
            .label(
                "event_type"
            ),

            db.func.count(
                RestaurantAnalyticsEvent.id
            )
            .label(
                "event_count"
            ),
        )

        .filter(
            *analytics_filters,

            RestaurantAnalyticsEvent
            .event_type
            .in_(
                supported_events
            ),
        )

        .group_by(
            RestaurantAnalyticsEvent
            .source_article_id,

            RestaurantAnalyticsEvent
            .restaurant_id,

            RestaurantAnalyticsEvent
            .event_type,
        )

        .all()
    )


    # ========================================================
    # UNIQUE ATTRIBUTED STORIES VISITORS
    # ========================================================
    #
    # source_session_id originates from the anonymous Stories
    # session.
    #
    # We count it here but never expose the IDs themselves.
    #
    # IMPORTANT:
    #
    # The same date filters used by the event-count query are
    # also applied here.
    # ========================================================

    unique_rows = (
        db.session.query(

            RestaurantAnalyticsEvent
            .source_article_id
            .label(
                "story_id"
            ),

            RestaurantAnalyticsEvent
            .restaurant_id
            .label(
                "restaurant_id"
            ),

            db.func.count(
                db.func.distinct(
                    RestaurantAnalyticsEvent
                    .source_session_id
                )
            )
            .label(
                "unique_sessions"
            ),
        )

        .filter(
            *analytics_filters,

            RestaurantAnalyticsEvent
            .source_session_id
            .isnot(
                None
            ),
        )

        .group_by(
            RestaurantAnalyticsEvent
            .source_article_id,

            RestaurantAnalyticsEvent
            .restaurant_id,
        )

        .all()
    )


    # ========================================================
    # RESPONSE STRUCTURE
    # ========================================================

    results = {}


    def get_result(
        story_id,
        restaurant_id,
    ):

        story_key = str(
            story_id
        )

        restaurant_key = str(
            restaurant_id
        )


        if story_key not in results:

            results[
                story_key
            ] = {
                "story_id":
                    story_id,

                "restaurants":
                    {},
            }


        restaurants = (
            results[
                story_key
            ][
                "restaurants"
            ]
        )


        if (
            restaurant_key
            not in restaurants
        ):

            restaurants[
                restaurant_key
            ] = {
                "restaurant_id":
                    restaurant_id,

                "restaurant_views":
                    0,

                "experience_views":
                    0,

                "whatsapp_clicks":
                    0,

                "phone_clicks":
                    0,

                "directions_clicks":
                    0,

                "meaningful_actions":
                    0,

                "unique_sessions":
                    0,
            }


        return restaurants[
            restaurant_key
        ]


    # ========================================================
    # MAP EVENT COUNTS
    # ========================================================

    event_field_map = {
        "restaurant_view":
            "restaurant_views",

        "experience_view":
            "experience_views",

        "whatsapp_click":
            "whatsapp_clicks",

        "phone_click":
            "phone_clicks",

        "directions_click":
            "directions_clicks",
    }


    for row in rows:

        result = get_result(
            story_id=(
                row.story_id
            ),

            restaurant_id=(
                row.restaurant_id
            ),
        )


        field_name = (
            event_field_map.get(
                row.event_type
            )
        )


        if field_name:

            result[
                field_name
            ] = int(
                row.event_count
                or
                0
            )


    # ========================================================
    # UNIQUE SESSIONS
    # ========================================================

    for row in unique_rows:

        result = get_result(
            story_id=(
                row.story_id
            ),

            restaurant_id=(
                row.restaurant_id
            ),
        )


        result[
            "unique_sessions"
        ] = int(
            row.unique_sessions
            or
            0
        )


    # ========================================================
    # MEANINGFUL ACTIONS
    # ========================================================
    #
    # Restaurant views and experience views represent
    # engagement.
    #
    # The following represent stronger customer intent:
    #
    #     WhatsApp
    #     phone
    #     directions
    # ========================================================

    for story in results.values():

        for restaurant in (
            story[
                "restaurants"
            ]
            .values()
        ):

            restaurant[
                "meaningful_actions"
            ] = (
                restaurant[
                    "whatsapp_clicks"
                ]
                +
                restaurant[
                    "phone_clicks"
                ]
                +
                restaurant[
                    "directions_clicks"
                ]
            )


    # ========================================================
    # CONVERT RESTAURANT DICTS TO LISTS
    # ========================================================

    response_stories = []


    for story_id in story_ids:

        story_key = str(
            story_id
        )


        story = (
            results.get(
                story_key,
                {
                    "story_id":
                        story_id,

                    "restaurants":
                        {},
                },
            )
        )


        restaurants = list(
            story[
                "restaurants"
            ]
            .values()
        )


        # ====================================================
        # STORY TOTALS
        # ====================================================

        totals = {
            "restaurant_views":
                sum(
                    restaurant[
                        "restaurant_views"
                    ]
                    for restaurant
                    in restaurants
                ),

            "experience_views":
                sum(
                    restaurant[
                        "experience_views"
                    ]
                    for restaurant
                    in restaurants
                ),

            "whatsapp_clicks":
                sum(
                    restaurant[
                        "whatsapp_clicks"
                    ]
                    for restaurant
                    in restaurants
                ),

            "phone_clicks":
                sum(
                    restaurant[
                        "phone_clicks"
                    ]
                    for restaurant
                    in restaurants
                ),

            "directions_clicks":
                sum(
                    restaurant[
                        "directions_clicks"
                    ]
                    for restaurant
                    in restaurants
                ),

            "meaningful_actions":
                sum(
                    restaurant[
                        "meaningful_actions"
                    ]
                    for restaurant
                    in restaurants
                ),

            "unique_sessions":
                sum(
                    restaurant[
                        "unique_sessions"
                    ]
                    for restaurant
                    in restaurants
                ),
        }


        response_stories.append(
            {
                "story_id":
                    story_id,

                "totals":
                    totals,

                "restaurants":
                    restaurants,
            }
        )


    # ========================================================
    # SUCCESS
    # ========================================================

    return jsonify(
        {
            "ok":
                True,

            "source":
                "kalxa_stories",

            "period": {
                "start_at":
                    (
                        start_at.isoformat()
                        if start_at
                        else None
                    ),

                "end_at":
                    (
                        end_at.isoformat()
                        if end_at
                        else None
                    ),
            },

            "stories":
                response_stories,
        }
    ), 200


# ============================================================
# PUBLIC - LOVE / UNLOVE RESTAURANT EXPERIENCE
# ============================================================

@app.route(
    "/experiences/<int:post_id>/love",
    methods=[
        "POST",
    ],
)
def love_restaurant_experience(
    post_id,
):

    experience_post = (
        RestaurantExperiencePost.query

        .filter_by(
            id=
                post_id,

            active=
                True,

            moderation_status=
                "approved",
        )

        .first_or_404()
    )


    anonymous_session_id = (
        get_restaurant_experience_session_id()
    )


    existing_love = (
        RestaurantExperienceLove.query

        .filter_by(
            post_id=
                experience_post.id,

            anonymous_session_id=
                anonymous_session_id,
        )

        .first()
    )


    loved = False


    try:

        # ====================================================
        # UNLOVE
        # ====================================================

        if existing_love:

            db.session.delete(
                existing_love
            )


            loved = False


        # ====================================================
        # LOVE
        # ====================================================

        else:

            love = (
                RestaurantExperienceLove(

                    post_id=
                        experience_post.id,

                    anonymous_session_id=
                        anonymous_session_id,
                )
            )


            db.session.add(
                love
            )


            loved = True


        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Restaurant Experience Love] "
                "Failed post_id=%s error=%s"
            ),
            experience_post.id,
            error,
        )


        return jsonify(
            {
                "ok": False,
                "message": (
                    "Unable to update love."
                ),
            }
        ), 500


    love_count = (
        RestaurantExperienceLove.query

        .filter_by(
            post_id=
                experience_post.id
        )

        .count()
    )


    return jsonify(
        {
            "ok": True,

            "post_id":
                experience_post.id,

            "loved":
                loved,

            "love_count":
                love_count,
        }
    )

# ============================================================
# RESERVE TICKET
# ============================================================
@app.route(
    "/event/<int:event_id>/reserve",
    methods=["GET", "POST"],
)
def reserve_ticket(event_id):
    """
    Reserve KALXA event tickets and initialize Paystack checkout.

    Supports:
        - General tickets.
        - Multiple ticket types.
        - Ticket sale phases.
        - Attendee names.
        - Maximum 10 tickets per order.
        - PostgreSQL inventory row locking.
        - Temporary inventory reservations.
        - Server-side ticket pricing.
        - Verified organiser Paystack splits.
        - Paystack checkout initialization.

    Security:
        - Only approved event organisers may sell tickets.
        - Events must be published and accepting sales.
        - Prices are never accepted from the customer.
        - Inventory is checked inside a database transaction.
        - The event row is locked before reserving inventory.
        - The Paystack split is obtained from the organiser.
        - Checkout must be explicitly enabled.
        - Paystack initialization occurs after the
          reservation transaction commits.

    IMPORTANT:
        This route does not issue EntryPass records.

        It does not mark orders as paid.

        Payment finalization must independently verify
        Paystack and use the same event inventory lock.

        Reservation expiry alone must not be treated as
        proof that a payment can no longer succeed.
    """

    # ========================================================
    # 1. LOAD EVENT
    # ========================================================

    event = (
        TicketEvent.query
        .filter_by(
            id=event_id,
            active=True,
            status="published",
            organizer_deleted=False,
        )
        .first_or_404()
    )

    organizer = event.organizer

    # ========================================================
    # 2. VERIFY ORGANISER APPROVAL
    # ========================================================

    if not event_organizer_is_approved(organizer):

        flash(
            "Ticket purchases are unavailable for this event.",
            "error",
        )

        return redirect(
            url_for(
                "event_page",
                event_id=event.id,
            )
        )

    # ========================================================
    # 3. VERIFY EVENT SALES STATUS
    # ========================================================

    if (
        not event.sales_open
        or event.is_closed
    ):

        flash(
            "Ticket sales are currently paused for this event.",
            "error",
        )

        return redirect(
            url_for(
                "event_page",
                event_id=event.id,
            )
        )

    ticket_types = event.active_ticket_types

    # ========================================================
    # 4. HANDLE GET REQUEST
    # ========================================================

    if request.method == "GET":

        if event.is_sold_out:

            flash(
                "This event is sold out.",
                "warning",
            )

            return redirect(
                url_for(
                    "event_page",
                    event_id=event.id,
                )
            )

        return _reserve_page(
            event,
            ticket_types,
        )

    # ========================================================
    # 5. CHECK CHECKOUT ACTIVATION
    # ========================================================

    if not KALXA_PAYSTACK_TICKET_CHECKOUT_ENABLED:

        flash(
            (
                "Online ticket payments are temporarily "
                "unavailable. Please try again later."
            ),
            "warning",
        )

        return _reserve_page(
            event,
            ticket_types,
        )

    if not KALXA_PAYSTACK_TICKET_SPLITS_ENABLED:

        current_app.logger.warning(
            "[Paystack Ticket Checkout] "
            "Splits disabled event_id=%s",
            event.id,
        )

        flash(
            "Ticket payments are not yet available for this event.",
            "warning",
        )

        return _reserve_page(
            event,
            ticket_types,
        )

    # ========================================================
    # 6. VERIFY INITIAL ORGANISER SPLIT
    # ========================================================

    try:

        organizer_split_code = (
            get_verified_organizer_paystack_split(
                organizer
            )
        )

    except RuntimeError:

        current_app.logger.warning(
            "[Paystack Ticket Checkout] "
            "Unverified organiser payout "
            "organizer_id=%s event_id=%s",
            organizer.id if organizer else None,
            event.id,
        )

        flash(
            (
                "Ticket payments are not yet available "
                "for this event."
            ),
            "warning",
        )

        return _reserve_page(
            event,
            ticket_types,
        )

    # ========================================================
    # 7. CUSTOMER DETAILS
    # ========================================================

    customer_name = (
        request.form.get(
            "customer_name",
            "",
        ).strip()
    )

    customer_phone = (
        request.form.get(
            "customer_phone",
            "",
        ).strip()
    )

    customer_email = (
        request.form.get(
            "customer_email",
            "",
        ).strip().lower()
    )

    if not all(
        (
            customer_name,
            customer_phone,
            customer_email,
        )
    ):

        flash(
            (
                "Name, phone number and email "
                "are required for secure checkout."
            ),
            "error",
        )

        return _reserve_page(
            event,
            ticket_types,
        )

    if (
        len(customer_name) > 150
        or len(customer_phone) > 50
        or len(customer_email) > 150
        or "@" not in customer_email
    ):

        flash(
            "Enter valid customer details.",
            "error",
        )

        return _reserve_page(
            event,
            ticket_types,
        )

    # ========================================================
    # 8. READ CUSTOMER TICKET SELECTION
    # ========================================================
    #
    # We initially read IDs, quantities and attendee names.
    #
    # Prices and sale phases will be recalculated using
    # fresh database values inside the inventory lock.
    # ========================================================

    requested_basket = []

    if ticket_types:

        for ticket_type in ticket_types:

            raw_quantity = request.form.get(
                f"qty_{ticket_type.id}",
                "0",
            )

            try:

                quantity = int(raw_quantity)

            except (TypeError, ValueError):

                flash(
                    "Enter a valid ticket quantity.",
                    "error",
                )

                return _reserve_page(
                    event,
                    ticket_types,
                )

            if quantity < 0:

                abort(400)

            if quantity == 0:

                continue

            if quantity > 10:

                flash(
                    "Maximum 10 tickets per order.",
                    "error",
                )

                return _reserve_page(
                    event,
                    ticket_types,
                )

            attendee_names = [
                request.form.get(
                    f"attendee_{ticket_type.id}_{index}",
                    "",
                ).strip()

                for index in range(
                    1,
                    quantity + 1,
                )
            ]

            if not all(attendee_names):

                flash(
                    (
                        "Enter the attendee name "
                        f"for every {ticket_type.name} ticket."
                    ),
                    "error",
                )

                return _reserve_page(
                    event,
                    ticket_types,
                )

            if any(
                len(name) > 150
                for name in attendee_names
            ):

                flash(
                    "Attendee names must not exceed 150 characters.",
                    "error",
                )

                return _reserve_page(
                    event,
                    ticket_types,
                )

            requested_basket.append(
                {
                    "ticket_type_id": ticket_type.id,
                    "quantity": quantity,
                    "attendee_names": attendee_names,
                }
            )

    # ========================================================
    # 9. GENERAL TICKET SELECTION
    # ========================================================

    else:

        raw_quantity = request.form.get(
            "quantity",
            "0",
        )

        try:

            quantity = int(raw_quantity)

        except (TypeError, ValueError):

            flash(
                "Enter a valid ticket quantity.",
                "error",
            )

            return _reserve_page(
                event,
                [],
            )

        if quantity < 0:

            abort(400)

        if quantity > 10:

            flash(
                "Maximum 10 tickets per order.",
                "error",
            )

            return _reserve_page(
                event,
                [],
            )

        if quantity:

            attendee_names = [
                request.form.get(
                    f"attendee_general_{index}",
                    "",
                ).strip()

                for index in range(
                    1,
                    quantity + 1,
                )
            ]

            if not all(attendee_names):

                flash(
                    (
                        "Enter the attendee name "
                        "for every General ticket."
                    ),
                    "error",
                )

                return _reserve_page(
                    event,
                    [],
                )

            if any(
                len(name) > 150
                for name in attendee_names
            ):

                flash(
                    "Attendee names must not exceed 150 characters.",
                    "error",
                )

                return _reserve_page(
                    event,
                    [],
                )

            requested_basket.append(
                {
                    "ticket_type_id": None,
                    "quantity": quantity,
                    "attendee_names": attendee_names,
                }
            )

    # ========================================================
    # 10. VALIDATE TOTAL QUANTITY
    # ========================================================

    total_quantity = sum(
        item["quantity"]
        for item in requested_basket
    )

    if not 1 <= total_quantity <= 10:

        flash(
            "Choose between 1 and 10 tickets in total.",
            "error",
        )

        return _reserve_page(
            event,
            ticket_types,
        )

    # ========================================================
    # 11. GENERATE PAYMENT REFERENCE
    # ========================================================

    reference = generate_payment_reference()

    # ========================================================
    # 12. PREPARE TRANSACTION STATE
    # ========================================================

    order_id = None

    checkout_amount = None
    checkout_cents = None
    processing_fee = None
    total_amount = None

    basket = []

    organizer_split_code = None
    organizer_subaccount_code = None
    organizer_id = None

    # ========================================================
    # 13. CREATE INVENTORY RESERVATION
    # ========================================================
    #
    # This is the critical database transaction.
    #
    # The event row lock serializes concurrent ticket
    # reservations for the same event.
    #
    # The reservation and all order items are committed
    # together.
    #
    # No Paystack API call occurs while the lock is held.
    # ========================================================

    try:

        # ====================================================
        # 14. LOCK EVENT INVENTORY
        # ====================================================

        locked_event = _inventory_locked_event(
            event_id
        )

        # ====================================================
        # 15. RECHECK EVENT AVAILABILITY UNDER LOCK
        # ====================================================

        if (
            not locked_event.active
            or locked_event.status != "published"
            or not locked_event.sales_open
            or locked_event.organizer_deleted
        ):

            raise InventoryUnavailable(
                "This event is no longer available for checkout."
            )

        # ====================================================
        # 16. RELOAD ORGANISER UNDER LOCK
        # ====================================================

        locked_organizer = (
            db.session.query(Organizer)
            .filter(
                Organizer.id == locked_event.organizer_id
            )
            .with_for_update()
            .one_or_none()
        )

        if not event_organizer_is_approved(
            locked_organizer
        ):

            raise InventoryUnavailable(
                "Ticket purchases are unavailable for this event."
            )

        organizer_split_code = (
            get_verified_organizer_paystack_split(
                locked_organizer
            )
        )

        organizer_subaccount_code = (
            locked_organizer.paystack_subaccount_code
        )

        organizer_id = locked_organizer.id

        # ====================================================
        # 17. RELOAD ACTIVE TICKET TYPES
        # ====================================================

        locked_ticket_types = (
            db.session.query(TicketType)
            .filter(
                TicketType.event_id == locked_event.id,
                TicketType.active.is_(True),
            )
            .order_by(
                TicketType.sort_order.asc(),
                TicketType.id.asc(),
            )
            .all()
        )

        types_by_id = {
            ticket_type.id: ticket_type
            for ticket_type in locked_ticket_types
        }

        # ====================================================
        # 18. BUILD SERVER-VERIFIED BASKET
        # ====================================================

        for requested_item in requested_basket:

            ticket_type_id = requested_item[
                "ticket_type_id"
            ]

            quantity = requested_item[
                "quantity"
            ]

            attendee_names = requested_item[
                "attendee_names"
            ]

            # ================================================
            # GENERAL TICKETS
            # ================================================

            if ticket_type_id is None:

                if locked_ticket_types:

                    raise InventoryUnavailable(
                        "General tickets are no longer available."
                    )

                phase = None

                ticket_type = None

                ticket_name = "General"

                unit_price = Decimal(
                    str(
                        locked_event.ticket_price or 0
                    )
                )

            # ================================================
            # TICKET TYPE PURCHASES
            # ================================================

            else:

                ticket_type = types_by_id.get(
                    ticket_type_id
                )

                if ticket_type is None:

                    raise InventoryUnavailable(
                        "A selected ticket type is no longer available."
                    )

                phase = ticket_type.current_sale_phase

                if (
                    ticket_type.active_sale_phases
                    and phase is None
                ):

                    raise InventoryUnavailable(
                        (
                            f"{ticket_type.name} is not "
                            "currently on sale."
                        )
                    )

                ticket_name = ticket_type.name

                unit_price = Decimal(
                    str(
                        phase.price
                        if phase
                        else ticket_type.price
                    )
                )

            # ================================================
            # VALIDATE PRICE
            # ================================================

            if (
                not unit_price.is_finite()
                or unit_price <= 0
                or unit_price.as_tuple().exponent < -2
            ):

                raise InventoryConfigurationError(
                    "Invalid ticket price configuration."
                )

            unit_price = unit_price.quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            )

            # ================================================
            # BUILD VERIFIED LINE
            # ================================================

            basket.append(
                {
                    "ticket_type": ticket_type,
                    "sale_phase": phase,
                    "name": ticket_name,
                    "price": unit_price,
                    "quantity": quantity,
                    "attendee_names": attendee_names,
                }
            )

        # ====================================================
        # 19. CALCULATE SERVER-SIDE ORDER TOTAL
        # ====================================================

        total_amount = sum(
            (
                item["price"] * item["quantity"]
                for item in basket
            ),
            Decimal("0.00"),
        ).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP,
        )

        if total_amount <= 0:

            raise InventoryConfigurationError(
                "Invalid ticket order total."
            )

        # ====================================================
        # 20. CALCULATE PAYSTACK CHECKOUT AMOUNT
        # ====================================================

        checkout_amount, processing_fee = (
            calculate_paystack_checkout_amount(
                total_amount
            )
        )

        checkout_amount = Decimal(
            str(checkout_amount)
        )

        processing_fee = Decimal(
            str(processing_fee)
        )

        if (
            not checkout_amount.is_finite()
            or checkout_amount <= 0
            or not processing_fee.is_finite()
            or processing_fee < 0
        ):

            raise InventoryConfigurationError(
                "Invalid checkout amount."
            )

        if (
            checkout_amount
            != total_amount + processing_fee
        ):

            raise InventoryConfigurationError(
                "Checkout amount does not match ticket total and fee."
            )

        checkout_cents_decimal = (
            checkout_amount * Decimal("100")
        )

        if (
            checkout_cents_decimal
            != checkout_cents_decimal.to_integral_value()
        ):

            raise InventoryConfigurationError(
                "Checkout amount contains fractional cents."
            )

        checkout_cents = int(
            checkout_cents_decimal
        )

        # ====================================================
        # 21. BUILD RESERVATION BASKET
        # ====================================================

        reservation_basket = [
            {
                "ticket_type_id": (
                    item["ticket_type"].id
                    if item["ticket_type"]
                    else None
                ),
                "sale_phase_id": (
                    item["sale_phase"].id
                    if item["sale_phase"]
                    else None
                ),
                "quantity": item["quantity"],
            }

            for item in basket
        ]

        # ====================================================
        # 22. CREATE PENDING ORDER
        # ====================================================

        order = TicketOrder(
            event_id=locked_event.id,
            customer_name=customer_name,
            customer_phone=customer_phone,
            customer_email=customer_email,
            quantity=total_quantity,
            ticket_price=(
                total_amount / total_quantity
            ).quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            ),
            total_amount=total_amount,
            processing_fee=processing_fee,
            checkout_amount=checkout_amount,
            payment_provider="paystack",
            payment_reference=reference,
            payment_status="pending",

            # ================================================
            # VERIFIED PAYSTACK SPLIT SNAPSHOT
            # ================================================

            paystack_split_code=organizer_split_code,

            paystack_subaccount_code=(
                organizer_subaccount_code
            ),

            paystack_split_verified_at=(
                locked_organizer.paystack_split_verified_at
            ),
        )

        # ====================================================
        # 23. VALIDATE AND RESERVE INVENTORY
        # ====================================================
        #
        # The service checks:
        #
        # - Paid tickets.
        # - Active pending reservations.
        # - General ticket capacity.
        # - Ticket type capacity.
        # - Sale phase quantity limits.
        #
        # The event row is already locked.
        # ====================================================

        reserve_inventory_for_order_locked(
            locked_event,
            order,
            reservation_basket,
        )

        # ====================================================
        # 24. SAVE ORDER
        # ====================================================

        db.session.add(order)

        db.session.flush()

        order_id = order.id

        # ====================================================
        # 25. CREATE ORDER ITEMS
        # ====================================================

        for item in basket:

            phase = item["sale_phase"]

            ticket_type = item["ticket_type"]

            line_total = (
                item["price"] * item["quantity"]
            ).quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            )

            db.session.add(
                TicketOrderItem(
                    order_id=order_id,
                    ticket_type_id=(
                        ticket_type.id
                        if ticket_type
                        else None
                    ),
                    sale_phase_id=(
                        phase.id
                        if phase
                        else None
                    ),
                    sale_phase_name=(
                        phase.name
                        if phase
                        else None
                    ),
                    ticket_name=item["name"],
                    unit_price=item["price"],
                    quantity=item["quantity"],
                    line_total=line_total,
                    attendee_names=item["attendee_names"],
                )
            )

        # ====================================================
        # 26. COMMIT ORDER AND INVENTORY RESERVATION
        # ====================================================

        db.session.commit()

    except (
        InventoryUnavailable,
        InventoryConfigurationError,
        RuntimeError,
    ) as error:

        db.session.rollback()

        current_app.logger.warning(
            "[Ticket Inventory] "
            "Reservation rejected event_id=%s reason=%s",
            event_id,
            str(error),
        )

        flash(
            str(error),
            "error",
        )

        return redirect(
            url_for(
                "event_page",
                event_id=event_id,
            )
        )

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            "[Ticket Inventory] "
            "Reservation failed event_id=%s reference=%s",
            event_id,
            reference,
        )

        flash(
            "Ticket reservation could not be completed.",
            "error",
        )

        return redirect(
            url_for(
                "event_page",
                event_id=event_id,
            )
        )

    # ========================================================
    # 27. INVENTORY RESERVATION COMMITTED
    # ========================================================
    #
    # The event lock has been released.
    #
    # The order is pending and has a reservation deadline.
    #
    # Do not create a second order below this point.
    # ========================================================

    # ========================================================
    # 28. BUILD PAYSTACK CALLBACK URL
    # ========================================================

    callback_url = url_for(
        "paystack_ticket_callback",
        _external=True,
        _scheme="https",
    )

    cancel_url = url_for(
        "booking_status",
        reference=reference,
        _external=True,
        _scheme="https",
    )

    # ========================================================
    # 29. BUILD PAYMENT METADATA
    # ========================================================

    metadata = {
        "payment_type": "kalxa_event_ticket",
        "kalxa_order_id": order_id,
        "event_id": event_id,
        "organizer_id": organizer_id,
        "ticket_face_value": str(
            total_amount
        ),
        "processing_fee": str(
            processing_fee
        ),
        "kalxa_commission_rate": "0.04",
        "paystack_split_code": organizer_split_code,
        "ticket_types": [
            {
                "name": item["name"],
                "quantity": item["quantity"],
                "unit_price": str(
                    item["price"]
                ),
                "sale_phase": (
                    item["sale_phase"].name
                    if item["sale_phase"]
                    else None
                ),
            }

            for item in basket
        ],
        "cancel_action": cancel_url,
    }

    # ========================================================
    # 30. BUILD PAYSTACK CHECKOUT PAYLOAD
    # ========================================================

    payload = {
        "email": customer_email,
        "amount": str(
            checkout_cents
        ),
        "currency": "ZAR",
        "reference": reference,
        "callback_url": callback_url,
        "channels": [
            "eft",
            "capitec_pay",
        ],
        "metadata": json.dumps(
            metadata
        ),

        # ====================================================
        # VERIFIED ORGANISER TRANSACTION SPLIT
        # ====================================================
        #
        # This is the locally verified split snapshot.
        #
        # The customer cannot supply or modify this value.
        # ====================================================

        "split_code": organizer_split_code,
    }

    # ========================================================
    # 31. INITIALIZE PAYSTACK CHECKOUT
    # ========================================================

    try:

        result = paystack_api_request(
            "POST",
            "/transaction/initialize",
            payload,
        )

        data = result.get("data") or {}

        authorization_url = data.get(
            "authorization_url"
        )

        access_code = data.get(
            "access_code"
        )

        # ====================================================
        # 32. VALIDATE PAYSTACK CHECKOUT URL
        # ====================================================

        if (
            not isinstance(authorization_url, str)
            or not authorization_url.strip()
        ):

            raise RuntimeError(
                "Paystack did not return a checkout URL."
            )

        parsed_url = urlparse(
            authorization_url.strip()
        )

        if (
            parsed_url.scheme != "https"
            or not parsed_url.hostname
            or parsed_url.username is not None
            or parsed_url.password is not None
            or parsed_url.port not in (None, 443)
            or (
                parsed_url.hostname != "paystack.com"
                and not parsed_url.hostname.endswith(
                    ".paystack.com"
                )
            )
        ):

            raise RuntimeError(
                "Paystack returned an invalid checkout URL."
            )

        authorization_url = authorization_url.strip()

        # ====================================================
        # 33. SAVE CHECKOUT DETAILS
        # ====================================================

        order = db.session.get(
            TicketOrder,
            order_id,
        )

        if order is None:

            raise RuntimeError(
                "Ticket order no longer exists."
            )

        if (
            order.payment_reference != reference
            or order.payment_status != "pending"
        ):

            raise RuntimeError(
                "Ticket order changed during checkout initialization."
            )

        order.paystack_access_code = (
            access_code
            if isinstance(access_code, str)
            else None
        )

        order.paystack_authorization_url = (
            authorization_url
        )

        db.session.commit()

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            "[Paystack Ticket Checkout] "
            "Initialization failed "
            "event_id=%s order_id=%s reference=%s",
            event_id,
            order_id,
            reference,
        )

        # ====================================================
        # IMPORTANT PAYMENT SAFETY RULE
        # ====================================================
        #
        # Do not automatically delete the order.
        #
        # Do not automatically release inventory.
        #
        # Paystack may have initialized the transaction
        # even if the response was lost or saving failed.
        #
        # The payment must be reconciled before inventory
        # is released or checkout is retried.
        # ====================================================

        flash(
            (
                "Secure checkout could not be started. "
                "Please contact support if you attempted payment."
            ),
            "error",
        )

        return redirect(
            url_for(
                "booking_status",
                reference=reference,
            )
        )

    # ========================================================
    # 34. REDIRECT CUSTOMER TO PAYSTACK
    # ========================================================

    return redirect(
        authorization_url
    )
# ============================================================
# PAYSTACK TICKET CALLBACK
# ============================================================



# ============================================================
# KALXA TICKETING
# PAYSTACK PAYMENT + REFUND WEBHOOK
# ============================================================

@app.route(
    "/payments/paystack/webhook",
    methods=["POST"],
)
def paystack_ticket_webhook():
    """
    Handle authenticated Paystack webhook events.

    Supported products:
        1. Event ticket purchases.
        2. Restaurant subscriptions.
        3. Legacy organiser subscriptions.
        4. Event Boost payments.
        5. Featured Listing payments.
        6. Event ticket refunds.

    Security:
        - Requires configured Paystack credentials.
        - Enforces webhook request-size limits.
        - Verifies HMAC-SHA512 signatures.
        - Parses authenticated JSON.
        - Independently verifies successful transactions.
        - Dispatches payments by local reference.
        - Delegates refunds to the refund service.
        - Does not update settlement accounting directly.

    IMPORTANT:
        All finalization functions must be idempotent.

        Payment amount and ownership verification
        must happen inside the relevant finalizer.
    """

    # ========================================================
    # 1. VERIFY CONFIGURATION
    # ========================================================

    if not paystack_is_configured():

        current_app.logger.error(
            "[Paystack Webhook] Secret key not configured."
        )

        abort(503)

    # ========================================================
    # 2. ENFORCE REQUEST SIZE LIMIT
    # ========================================================

    MAX_PAYSTACK_WEBHOOK_BYTES = (
        256 * 1024
    )

    if (
        request.content_length is not None
        and request.content_length
        > MAX_PAYSTACK_WEBHOOK_BYTES
    ):

        current_app.logger.warning(
            "[Paystack Webhook] Oversized request."
        )

        abort(413)

    raw_body = request.get_data(
        cache=False,
    )

    if (
        len(raw_body)
        > MAX_PAYSTACK_WEBHOOK_BYTES
    ):

        current_app.logger.warning(
            "[Paystack Webhook] Payload exceeds limit."
        )

        abort(413)

    # ========================================================
    # 3. READ SIGNATURE
    # ========================================================

    received_signature = (
        request.headers.get(
            "x-paystack-signature"
        ) or ""
    ).strip()

    # ========================================================
    # 4. CALCULATE EXPECTED SIGNATURE
    # ========================================================

    expected_signature = hmac.new(
        PAYSTACK_SECRET_KEY.encode("utf-8"),
        raw_body,
        hashlib.sha512,
    ).hexdigest()

    # ========================================================
    # 5. VALIDATE SIGNATURE
    # ========================================================

    if (
        len(received_signature) != 128
        or not hmac.compare_digest(
            received_signature.lower(),
            expected_signature,
        )
    ):

        current_app.logger.warning(
            "[Paystack Webhook] Invalid signature."
        )

        abort(400)

    # ========================================================
    # 6. PARSE VERIFIED PAYLOAD
    # ========================================================

    try:

        payload = json.loads(
            raw_body.decode("utf-8")
        )

    except (
        ValueError,
        UnicodeDecodeError,
    ):

        current_app.logger.warning(
            "[Paystack Webhook] Invalid JSON."
        )

        abort(400)

    if not isinstance(
        payload,
        dict,
    ):

        current_app.logger.warning(
            "[Paystack Webhook] Invalid payload format."
        )

        abort(400)

    # ========================================================
    # 7. IDENTIFY EVENT
    # ========================================================

    event_type = payload.get(
        "event"
    )

    if (
        not isinstance(event_type, str)
        or not event_type.strip()
    ):

        current_app.logger.warning(
            "[Paystack Webhook] Invalid event type."
        )

        abort(400)

    event_type = event_type.strip()

    # ========================================================
    # 8. HANDLE REFUND EVENTS
    # ========================================================

    if event_type.startswith(
        "refund."
    ):

        from ticket_refund_routes import (
            handle_ticket_refund_webhook,
        )

        try:

            handled = (
                handle_ticket_refund_webhook(
                    payload,
                    db=db,
                    TicketOrder=TicketOrder,
                    TicketOrderItem=TicketOrderItem,
                    TicketRefund=TicketRefund,
                    TicketRefundItem=TicketRefundItem,
                    EntryPass=EntryPass,
                    paystack_api_request=paystack_api_request,
                )
            )

            if not handled:

                current_app.logger.warning(
                    (
                        "[Paystack Refund Webhook] "
                        "Unrecognized event=%s"
                    ),
                    event_type,
                )

            return "", 200

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                (
                    "[Paystack Refund Webhook] "
                    "Reconciliation failed event=%s"
                ),
                event_type,
            )

            return "", 500

    # ========================================================
    # 9. HANDLE SETTLEMENT EVENTS
    # ========================================================

    if event_type.startswith(
        "settlement."
    ):

        current_app.logger.warning(
            (
                "[Paystack Webhook] "
                "Settlement event received "
                "event=%s"
            ),
            event_type,
        )

        # Settlement accounting must be handled
        # by a separate verified reconciliation
        # process.

        return "", 200

    # ========================================================
    # 10. IGNORE UNSUPPORTED EVENTS
    # ========================================================

    if event_type != "charge.success":

        current_app.logger.info(
            (
                "[Paystack Webhook] "
                "Ignoring event=%s"
            ),
            event_type,
        )

        return "", 200

    # ========================================================
    # 11. EXTRACT PAYMENT REFERENCE
    # ========================================================

    webhook_data = payload.get(
        "data"
    )

    if not isinstance(
        webhook_data,
        dict,
    ):

        current_app.logger.warning(
            "[Paystack Webhook] Missing payment data."
        )

        abort(400)

    reference = webhook_data.get(
        "reference"
    )

    if (
        not isinstance(reference, str)
        or not reference.strip()
    ):

        current_app.logger.warning(
            "[Paystack Webhook] Missing reference."
        )

        abort(400)

    reference = reference.strip()

    if len(reference) > 200:

        abort(400)

    # ========================================================
    # 12. VERIFY TRANSACTION WITH PAYSTACK
    # ========================================================

    try:

        transaction_data = (
            _kalxa_verified_paystack_transaction(
                reference
            )
        )

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Paystack Webhook] "
                "Transaction verification failed "
                "reference=%s"
            ),
            reference,
        )

        return "", 500

    # ========================================================
    # 13. EVENT TICKET PURCHASES
    # ========================================================

    order = (
        TicketOrder.query
        .filter_by(
            payment_reference=reference
        )
        .first()
    )

    if order is not None:

        try:

            finalize_paystack_ticket_order(
                order,
                transaction_data,
            )

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                (
                    "[Paystack Ticket Webhook] "
                    "Finalization failed "
                    "reference=%s order_id=%s"
                ),
                reference,
                order.id,
            )

            return "", 500

        return "", 200

    # ========================================================
    # 14. RESTAURANT SUBSCRIPTIONS
    # ========================================================

    restaurant_payment = (
        RestaurantSubscriptionPayment.query
        .filter_by(
            payment_reference=reference
        )
        .first()
    )

    if restaurant_payment is not None:

        if (
            restaurant_payment.payment_status
            == "cancelled"
        ):

            current_app.logger.warning(
                (
                    "[Restaurant Subscription Webhook] "
                    "Cancelled payment requires "
                    "reconciliation reference=%s"
                ),
                reference,
            )

            return "", 200

        try:

            finalize_restaurant_subscription_payment(
                restaurant_payment,
                transaction_data,
            )

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                (
                    "[Restaurant Subscription Webhook] "
                    "Finalization failed "
                    "reference=%s payment_id=%s"
                ),
                reference,
                restaurant_payment.id,
            )

            return "", 500

        return "", 200

    # ========================================================
    # 15. LEGACY ORGANISER SUBSCRIPTIONS
    # ========================================================

    subscription_payment = (
        SubscriptionPayment.query
        .filter_by(
            payment_reference=reference
        )
        .first()
    )

    if subscription_payment is not None:

        if (
            subscription_payment.payment_status
            == "cancelled"
        ):

            current_app.logger.warning(
                (
                    "[Legacy Subscription Webhook] "
                    "Cancelled payment requires "
                    "reconciliation reference=%s"
                ),
                reference,
            )

            return "", 200

        try:

            finalize_paystack_subscription_payment(
                subscription_payment,
                transaction_data,
            )

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                (
                    "[Legacy Subscription Webhook] "
                    "Finalization failed "
                    "reference=%s payment_id=%s"
                ),
                reference,
                subscription_payment.id,
            )

            return "", 500

        return "", 200

    # ========================================================
    # 16. EVENT BOOST PAYMENTS
    # ========================================================

    boost = (
        EventBoost.query
        .filter_by(
            payment_reference=reference
        )
        .first()
    )

    if boost is not None:

        try:

            finalize_event_boost_payment(
                boost,
                transaction_data,
            )

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                (
                    "[Event Boost Webhook] "
                    "Finalization failed "
                    "reference=%s boost_id=%s"
                ),
                reference,
                boost.id,
            )

            return "", 500

        return "", 200

    # ========================================================
    # 17. FEATURED LISTING PAYMENTS
    # ========================================================

    listing = (
        FeaturedListing.query
        .filter_by(
            payment_reference=reference
        )
        .first()
    )

    if listing is not None:

        try:

            finalize_featured_listing_payment(
                listing,
                transaction_data,
            )

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                (
                    "[Featured Listing Webhook] "
                    "Finalization failed "
                    "reference=%s listing_id=%s"
                ),
                reference,
                listing.id,
            )

            return "", 500

        return "", 200

    # ========================================================
    # 18. UNMATCHED VERIFIED PAYMENT
    # ========================================================

    current_app.logger.error(
        (
            "[Paystack Webhook] "
            "Unmatched verified payment "
            "requires reconciliation "
            "reference=%s "
            "transaction_id=%s "
            "amount=%s"
        ),
        reference,
        transaction_data.get("id"),
        transaction_data.get("amount"),
    )

    # Returning 200 prevents endless retries.
    #
    # IMPORTANT:
    # This does not itself guarantee reconciliation.
    # Add a persistent reconciliation record and
    # alerting before relying on this in production.

    return "", 200

# ============================================================
# OPTIONAL KALXA DISCOVERY -> TICKETING BRIDGE
# ============================================================
#
# Ticketing is now standalone.
#
# The Discovery bridge remains available as an optional
# traffic / context integration.
#
# A Discovery organizer is NOT automatically authenticated
# as a Ticketing organizer anymore.
# ============================================================

def get_kalxa_bridge_serializer():

    bridge_secret = (
        os.environ.get(
            "KALXA_TICKETING_BRIDGE_SECRET"
        )
    )


    if not bridge_secret:

        raise RuntimeError(
            (
                "KALXA_TICKETING_BRIDGE_SECRET "
                "is not configured."
            )
        )


    return URLSafeTimedSerializer(
        secret_key=
            bridge_secret,

        salt=
            "kalxa-ticketing-bridge-v1",
    )


@app.route(
    "/auth/kalxa",
    methods=[
        "POST",
    ],
)
def kalxa_auth_bridge():

    token = (
        request.form.get(
            "token",
            "",
        )
        .strip()
    )


    if not token:

        abort(400)


    serializer = (
        get_kalxa_bridge_serializer()
    )


    try:

        payload = serializer.loads(
            token,
            max_age=90,
        )


    except SignatureExpired:

        flash(
            (
                "Your secure Kalxa Ticketing link "
                "expired. Please open it again."
            ),
            "error",
        )

        return redirect(
            url_for(
                "organizer_login"
            )
        )


    except BadSignature:

        abort(403)


    if (
        payload.get("aud")
        != "kalxa-ticketing"
    ):

        abort(403)


    if (
        payload.get("purpose")
        != "organizer-login"
    ):

        abort(403)


    bridge_id = (
        payload.get(
            "bridge_id"
        )
    )


    kalxa_organizer_id = (
        payload.get(
            "organizer_id"
        )
    )


    content_item_id = (
        payload.get(
            "content_item_id"
        )
    )


    if (
        not bridge_id
        or kalxa_organizer_id is None
        or content_item_id is None
    ):

        abort(403)


    try:

        kalxa_organizer_id = int(
            kalxa_organizer_id
        )

        content_item_id = int(
            content_item_id
        )


    except (
        TypeError,
        ValueError,
    ):

        abort(403)


    already_used = (
        KalxaBridgeTokenUse.query
        .filter_by(
            bridge_id=
                bridge_id
        )
        .first()
    )


    if already_used:

        abort(403)


    token_use = KalxaBridgeTokenUse(

        bridge_id=
            bridge_id,

        kalxa_organizer_id=
            kalxa_organizer_id,

        kalxa_content_item_id=
            content_item_id,
    )


    try:

        db.session.add(
            token_use
        )

        db.session.commit()


    except Exception:

        db.session.rollback()

        abort(403)


    # ========================================================
    # STORE TEMPORARY DISCOVERY CONTEXT
    # ========================================================

    session[
        "pending_kalxa_organizer_id"
    ] = kalxa_organizer_id


    session[
        "pending_kalxa_content_item_id"
    ] = content_item_id


    organizer = (
        get_current_organizer()
    )


    if organizer:

        session[
            "kalxa_organizer_id"
        ] = kalxa_organizer_id


        session[
            "kalxa_content_item_id"
        ] = content_item_id


        if (
            organizer.kalxa_discovery_organizer_id
            is None
        ):

            organizer.kalxa_discovery_organizer_id = (
                kalxa_organizer_id
            )


            try:

                db.session.commit()


            except Exception:

                db.session.rollback()


        return redirect(
            url_for(
                "admin_dashboard"
            )
        )


    flash(
        (
            "Sign in to your Kalxa Ticketing "
            "organizer account to continue."
        ),
        "success",
    )


    return redirect(
        url_for(
            "organizer_login"
        )
    )


