# ============================================================
# FIREBASE MESSAGING SERVICE WORKER
# ============================================================
#
# Served at the root of the domain so the service worker can
# control the whole Kalxa Ticketing origin.
# ============================================================

@app.route(
    "/firebase-messaging-sw.js"
)
def firebase_messaging_service_worker():

    if not firebase_web_push_configured():

        return Response(
            (
                "// Firebase Web Push is not configured.\n"
            ),
            mimetype=
                "application/javascript",
        )


    config_json = json.dumps(
        FIREBASE_WEB_CONFIG
    )


    service_worker = f"""
importScripts(
    "https://www.gstatic.com/firebasejs/12.19.0/firebase-app-compat.js"
);

importScripts(
    "https://www.gstatic.com/firebasejs/12.19.0/firebase-messaging-compat.js"
);

firebase.initializeApp(
    {config_json}
);

const messaging =
    firebase.messaging();


// IMPORTANT:
//
// Do not manually call showNotification() here.
//
// The server sends an FCM notification payload, so Firebase
// displays the browser notification automatically in the
// background.
//
// Click navigation is handled by webpush.fcm_options.link.


// ==========================================================
// KALXA PWA APP SHELL
// ==========================================================

const KALXA_CACHE =
    "kalxa-ticketing-pwa-v3";

const KALXA_APP_SHELL = [
    "/offline",
    "/manifest.webmanifest",
    "/static/icons/kalxa-192.png",
    "/static/icons/kalxa-512.png",
    "/static/icons/kalxa-maskable-512.png"
];


self.addEventListener(
    "install",
    (event) => {{

        event.waitUntil(
            caches
                .open(
                    KALXA_CACHE
                )
                .then(
                    async (cache) => {{

                        // Cache each asset independently.
                        //
                        // One missing optional asset should NOT
                        // prevent the whole service worker from
                        // installing.
                        await Promise.allSettled(
                            KALXA_APP_SHELL.map(
                                (url) =>
                                    cache.add(url)
                            )
                        );
                    }}
                )
        );

        self.skipWaiting();
    }}
);


self.addEventListener(
    "activate",
    (event) => {{

        event.waitUntil(
            caches
                .keys()
                .then(
                    (keys) =>
                        Promise.all(
                            keys
                                .filter(
                                    (key) =>
                                        key.startsWith(
                                            "kalxa-ticketing-pwa-"
                                        )
                                        &&
                                        key !== KALXA_CACHE
                                )
                                .map(
                                    (key) =>
                                        caches.delete(
                                            key
                                        )
                                )
                        )
                )
        );

        self.clients.claim();
    }}
);


self.addEventListener(
    "fetch",
    (event) => {{

        if (
            event.request.method
            !== "GET"
        ) {{
            return;
        }}


        const requestUrl =
            new URL(
                event.request.url
            );


        if (
            requestUrl.origin
            !== self.location.origin
        ) {{
            return;
        }}


        if (
            event.request.mode
            === "navigate"
        ) {{

            event.respondWith(
                fetch(
                    event.request
                )
                .catch(
                    () =>
                        caches.match(
                            "/offline"
                        )
                )
            );

            return;
        }}


        if (
            requestUrl.pathname.startsWith(
                "/static/icons/"
            )
            ||
            requestUrl.pathname
            === "/manifest.webmanifest"
        ) {{

            event.respondWith(
                caches.match(
                    event.request
                )
                .then(
                    (cached) =>
                        cached
                        ||
                        fetch(
                            event.request
                        )
                )
            );
        }}
    }}
);
"""


    response = Response(
        service_worker,
        mimetype=
            "application/javascript",
    )


    response.headers[
        "Cache-Control"
    ] = (
        "no-cache, no-store, must-revalidate"
    )


    return response


# ============================================================
# ATTENDEE - ENABLE PUSH NOTIFICATIONS
# ============================================================

@app.route(
    "/notifications/subscribe",
    methods=["POST"],
)
def notification_subscribe():

    if not firebase_web_push_configured():

        return {
            "ok": False,
            "error":
                "Firebase Web Push is not configured.",
        }, 503

    payload = request.get_json(silent=True) or {}

    reference = str(
        payload.get("reference", "")
    ).strip().upper()

    installation_id = str(
        payload.get("installation_id", "")
    ).strip()

    home_area = str(
        payload.get("home_area", "")
    ).strip()

    if not reference or not installation_id:
        return {
            "ok": False,
            "error":
                "Booking reference and installation ID are required.",
        }, 400

    if not home_area:
        return {
            "ok": False,
            "error":
                "Enter the area or town where you live.",
        }, 400

    if len(installation_id) > 255:
        return {
            "ok": False,
            "error":
                "Invalid Firebase installation ID.",
        }, 400

    order = (
        TicketOrder.query
        .filter_by(
            payment_reference=reference
        )
        .first()
    )

    if not order:
        return {
            "ok": False,
            "error":
                "Booking could not be found.",
        }, 404

    try:
        location = geocode_area(home_area)

    except (ValueError, RuntimeError) as error:
        return {
            "ok": False,
            "error": str(error),
        }, 400

    phone_normalized = normalize_attendee_phone(
        order.customer_phone
    )

    if not phone_normalized:
        return {
            "ok": False,
            "error":
                "A valid attendee phone number is required.",
        }, 400

    now = datetime.utcnow()

    contact = (
        AttendeeContact.query
        .filter_by(
            phone_normalized=
                phone_normalized
        )
        .first()
    )

    if not contact:

        contact = AttendeeContact(
            name=order.customer_name,
            phone=order.customer_phone,
            phone_normalized=
                phone_normalized,
            email=order.customer_email,
            notification_consent=True,
            consented_at=now,
            opted_out_at=None,
        )

        db.session.add(contact)
        db.session.flush()

    else:

        contact.name = (
            order.customer_name
            or contact.name
        )
        contact.phone = (
            order.customer_phone
            or contact.phone
        )
        contact.email = (
            order.customer_email
            or contact.email
        )
        contact.notification_consent = True
        contact.consented_at = now
        contact.opted_out_at = None

    subscription = (
        PushSubscription.query
        .filter_by(
            firebase_installation_id=
                installation_id
        )
        .first()
    )

    if not subscription:

        subscription = PushSubscription(
            contact_id=contact.id,
            firebase_installation_id=
                installation_id,
            active=True,
            registered_at=now,
            last_seen_at=now,
            disabled_at=None,
        )

        db.session.add(subscription)

    else:

        subscription.contact_id = contact.id
        subscription.active = True
        subscription.last_seen_at = now
        subscription.disabled_at = None

    subscription.home_area = home_area
    subscription.home_location_display = (
        location.display_name
    )
    subscription.home_latitude = (
        location.latitude
    )
    subscription.home_longitude = (
        location.longitude
    )

    try:

        db.session.commit()

    except Exception as error:

        db.session.rollback()

        current_app.logger.exception(
            "[Push Subscribe] Failed "
            "reference=%s error=%s",
            reference,
            error,
        )

        return {
            "ok": False,
            "error":
                "Notification subscription could not be saved.",
        }, 500

    return {
        "ok": True,
        "message": (
            "Future-event notifications are enabled "
            f"for {home_area} and events within "
            f"{LOCAL_NOTIFICATION_RADIUS_KM:g} km."
        ),
        "home_area": home_area,
        "radius_km":
            LOCAL_NOTIFICATION_RADIUS_KM,
    }


# ============================================================
# ATTENDEE - DISABLE PUSH NOTIFICATIONS
# ============================================================

@app.route(
    "/notifications/unsubscribe",
    methods=[
        "POST",
    ],
)
def notification_unsubscribe():

    payload = (
        request.get_json(
            silent=True
        )
        or {}
    )


    reference = (
        str(
            payload.get(
                "reference",
                ""
            )
        )
        .strip()
        .upper()
    )


    installation_id = (
        str(
            payload.get(
                "installation_id",
                ""
            )
        )
        .strip()
    )


    if (
        not reference
        or not installation_id
    ):

        return {
            "ok": False,
            "error": (
                "Booking reference and installation ID "
                "are required."
            ),
        }, 400


    order = (
        TicketOrder.query
        .filter_by(
            payment_reference=
                reference
        )
        .first()
    )
    if not order:

        return {
            "ok": False,
            "error": (
                "Booking could not be found."
            ),
        }, 404


    phone_normalized = (
        normalize_attendee_phone(
            order.customer_phone
        )
    )


    subscription = (
        PushSubscription.query
        .filter_by(
            firebase_installation_id=
                installation_id
        )
        .first()
    )


    now = (
        datetime.utcnow()
    )


    if subscription:

        subscription.active = (
            False
        )

        subscription.disabled_at = (
            now
        )


    contact = None


    if phone_normalized:

        contact = (
            AttendeeContact.query
            .filter_by(
                phone_normalized=
                    phone_normalized
            )
            .first()
        )


    if contact:

        contact.notification_consent = (
            False
        )

        contact.opted_out_at = (
            now
        )


        for device in (
            contact.push_subscriptions
        ):

            device.active = (
                False
            )

            device.disabled_at = (
                now
            )


    try:

        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Push Unsubscribe] Failed "
                "reference=%s error=%s"
            ),
            reference,
            error,
        )


        return {
            "ok": False,
            "error": (
                "Notification preference could "
                "not be updated."
            ),
        }, 500


    return {
        "ok": True,
        "message": (
            "Future-event notifications are turned off."
        ),
    }


