@app.route(
    "/payments/yoco/subscription/return",
    methods=["GET"],
)
def yoco_subscription_return():

    auth = require_ticketing_organizer()

    if auth:
        return auth

    organizer = get_current_organizer()

    if not organizer:
        return redirect(
            url_for("organizer_login")
        )

    reference = (
        request.args.get(
            "reference",
            "",
        )
        .strip()
    )

    if not reference:
        abort(400)

    payment = (
        SubscriptionPayment.query
        .filter_by(
            payment_reference=reference,
            organizer_id=organizer.id,
            payment_method="yoco",
        )
        .first_or_404()
    )

    if payment.payment_status == "paid":

        flash(
            "Your Kalxa subscription is active.",
            "success",
        )

    else:

        flash(
            (
                "Your payment is being confirmed. "
                "Please refresh your subscription page shortly."
            ),
            "info",
        )

    return redirect(
        url_for("admin_subscription")
    )
    
# ============================================================
# YOCO — RESTAURANT SUBSCRIPTION RETURN
# ============================================================

@app.route(
    "/payments/yoco/restaurant-subscription/return",
    methods=["GET"],
)
def yoco_restaurant_subscription_return():
    """
    Handle the restaurant owner's return from Yoco.

    SECURITY:
    - Requires an authenticated restaurant owner.
    - Finds the payment by reference and organizer.
    - Does not trust browser redirect parameters as proof.
    - Verifies the stored checkout directly with Yoco.
    - Activates only through the central verification function.
    - Never creates a second payment.
    """

    # ========================================================
    # AUTHENTICATION
    # ========================================================

    auth = require_ticketing_organizer()

    if auth:
        return auth

    organizer = get_current_organizer()

    if not organizer:

        return redirect(
            url_for("organizer_login")
        )

    # ========================================================
    # VALIDATE ACCOUNT TYPE
    # ========================================================

    account_type = (
        getattr(
            organizer,
            "account_type",
            None,
        )
        or "event"
    ).strip().lower()

    if account_type != "restaurant":
        abort(403)

    # ========================================================
    # PAYMENT REFERENCE
    # ========================================================

    reference = (
        request.args.get(
            "reference",
            "",
        )
        .strip()
    )

    if not reference:
        abort(400)

    if len(reference) > 100:
        abort(400)

    # ========================================================
    # FIND RESTAURANT PAYMENT
    # ========================================================

    payment = (
        RestaurantSubscriptionPayment.query
        .filter_by(
            payment_reference=reference,
            organizer_id=organizer.id,
            payment_method="yoco",
        )
        .first_or_404()
    )

    # ========================================================
    # CAPTURE IDENTIFIERS BEFORE TRANSACTION RESET
    # ========================================================

    payment_id = payment.id

    advert_id = payment.restaurant_advert_id

    plan_name = payment.plan_name

    payment_status = payment.payment_status

    checkout_id = payment.yoco_checkout_id

    # ========================================================
    # ALREADY CONFIRMED
    # ========================================================

    if payment_status == "paid":

        flash(
            (
                f"{plan_name} payment confirmed. "
                "Your restaurant subscription is active."
            ),
            "success",
        )

        return redirect(
            url_for(
                "admin_manage_restaurant",
                advert_id=advert_id,
            )
        )

    # ========================================================
    # DO NOT RECONCILE CANCELLED / FAILED PAYMENTS
    # ========================================================

    if payment_status != "pending":

        flash(
            (
                "This restaurant payment is no longer "
                "pending. Please check your subscription "
                "status before starting another payment."
            ),
            "info",
        )

        return redirect(
            url_for(
                "admin_manage_restaurant",
                advert_id=advert_id,
            )
        )

    # ========================================================
    # CHECK STORED CHECKOUT
    # ========================================================

    if not checkout_id:

        current_app.logger.warning(
            (
                "[Yoco] Restaurant return has no checkout ID. "
                "payment_id=%s advert_id=%s"
            ),
            payment_id,
            advert_id,
        )

        flash(
            (
                "Your payment could not be verified yet. "
                "Please contact support if you have "
                "already completed payment."
            ),
            "info",
        )

        return redirect(
            url_for(
                "admin_manage_restaurant",
                advert_id=advert_id,
            )
        )

    # ========================================================
    # CLEAR LOOKUP TRANSACTION
    # ========================================================

    db.session.rollback()

    # ========================================================
    # VERIFY DIRECTLY WITH YOCO
    # ========================================================

    try:

        result = verify_and_activate_yoco_subscription(
            kind="restaurant",
            payment_id=payment_id,
            source="reconciliation",
        )

    except YocoError:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Yoco] Restaurant return verification "
                "failed payment_id=%s advert_id=%s"
            ),
            payment_id,
            advert_id,
        )

        result = "verification_unavailable"

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Yoco] Unexpected restaurant return "
                "verification error payment_id=%s "
                "advert_id=%s"
            ),
            payment_id,
            advert_id,
        )

        result = "verification_unavailable"

    # ========================================================
    # ACTIVATED
    # ========================================================

    if result == "activated":

        flash(
            (
                f"{plan_name} payment confirmed! "
                "Your restaurant subscription "
                "has been activated successfully."
            ),
            "success",
        )

    # ========================================================
    # ALREADY PROCESSED
    # ========================================================

    elif result == "already_processed":

        flash(
            (
                f"{plan_name} payment confirmed. "
                "Your restaurant subscription "
                "has already been activated."
            ),
            "success",
        )

    # ========================================================
    # STILL PENDING
    # ========================================================

    elif result == "pending":

        flash(
            (
                "Your restaurant payment is still "
                "being verified with Yoco. "
                "Your plan will activate after "
                "payment confirmation. "
                "Please do not pay again."
            ),
            "info",
        )

    # ========================================================
    # VERIFICATION UNAVAILABLE
    # ========================================================

    elif result == "verification_unavailable":

        flash(
            (
                "We could not contact Yoco to "
                "verify your payment right now. "
                "If you have already paid, "
                "please do not pay again."
            ),
            "info",
        )

    # ========================================================
    # UNMATCHED / INVALID
    # ========================================================

    else:

        current_app.logger.warning(
            (
                "[Yoco] Restaurant return verification "
                "did not activate subscription. "
                "payment_id=%s result=%s"
            ),
            payment_id,
            result,
        )

        flash(
            (
                "Your restaurant payment could not "
                "be confirmed automatically. "
                "Please contact Kalxa support "
                "if you have already paid."
            ),
            "error",
        )

    # ========================================================
    # RETURN TO RESTAURANT CONTROL CENTRE
    # ========================================================

    return redirect(
        url_for(
            "admin_manage_restaurant",
            advert_id=advert_id,
        )
    )
# ============================================================
# RESTAURANT SUBSCRIPTION PAYSTACK CALLBACK
# ============================================================

@app.route(
    "/payments/paystack/restaurant-subscription/callback"
)
def paystack_restaurant_subscription_callback():

    # ========================================================
    # REFERENCE
    # ========================================================

    reference = (
        request.args.get(
            "reference",
            "",
        )
        .strip()
    )


    if not reference:

        abort(400)


    # ========================================================
    # PAYMENT
    # ========================================================

    payment = (
        RestaurantSubscriptionPayment.query
        .filter_by(
            payment_reference=reference
        )
        .first_or_404()
    )


    # ========================================================
    # VERIFY WITH PAYSTACK
    # ========================================================

    try:

        result = (
            paystack_api_request(
                "GET",
                (
                    "/transaction/verify/"
                    +
                    urllib.parse.quote(
                        reference,
                        safe="",
                    )
                ),
            )
        )


        transaction_data = (
            result.get(
                "data"
            )
            or {}
        )


        finalize_restaurant_subscription_payment(
            payment,
            transaction_data,
        )


        flash(
            (
                f"{payment.plan_name} payment confirmed. "
                "Your restaurant plan is now active."
            ),
            "success",
        )


    except Exception as error:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Restaurant Subscription Callback] "
                "Verification failed "
                "reference=%s "
                "error=%s"
            ),
            reference,
            error,
        )


        flash(
            (
                "Your restaurant subscription payment "
                "is still being verified. "
                "Please refresh shortly."
            ),
            "error",
        )


    # ========================================================
    # RETURN TO RESTAURANT
    # ========================================================

    return redirect(
        url_for(
            "admin_manage_restaurant",
            advert_id=
                payment.restaurant_advert_id,
        )
    )
