@app.route(
    "/admin/events/<int:event_id>/boost"
)
def admin_event_boost(
    event_id,
):

    auth = (
        require_ticketing_organizer()
    )


    if auth:

        return auth


    organizer = (
        get_current_organizer()
    )


    event = (
        TicketEvent.query
        .filter_by(
            id=
                event_id,

            organizer_id=
                organizer.id,
        )
        .first_or_404()
    )


    boost = (
        EventBoost.query
        .filter_by(
            event_id=
                event.id
        )
        .first()
    )


    audience_count = 0


    if (
        event.notification_latitude
        is not None
        and event.notification_longitude
        is not None
    ):

        audience_count = len(
            get_local_push_subscriptions(
                event,
                float(
                    EVENT_BOOST_RADIUS_KM
                ),
            )
        )


    if (
        boost
        and boost.status
        == "active"
        and boost.plan_code
        == "pro"
    ):

        build_event_boost_schedule(
            boost
        )

        db.session.commit()


    reminders = (
        boost.reminders
        if boost
        else []
    )


    sent_campaigns = [
        reminder.campaign
        for reminder in reminders
        if reminder.campaign
    ]


    performance = {
        "campaigns_sent":
            len(
                [
                    campaign
                    for campaign in sent_campaigns
                    if campaign.sent_at
                ]
            ),

        "recipients":
            sum(
                campaign.recipient_count
                or 0
                for campaign in sent_campaigns
            ),

        "success":
            sum(
                campaign.success_count
                or 0
                for campaign in sent_campaigns
            ),

        "failed":
            sum(
                campaign.failure_count
                or 0
                for campaign in sent_campaigns
            ),
    }


    performance[
        "delivery_rate"
    ] = (
        round(
            (
                performance[
                    "success"
                ]
                /
                performance[
                    "recipients"
                ]
                * 100
            ),
            1,
        )
        if performance[
            "recipients"
        ]
        else 0
    )


    audience_analytics = (
        build_local_audience_analytics(
            event,
            EVENT_BOOST_RADIUS_KM,
        )
    )


    reminder_rows = []


    for reminder in reminders:

        campaign = (
            reminder.campaign
        )


        recipient_count = (
            campaign.recipient_count
            if campaign
            else 0
        ) or 0

        success_count = (
            campaign.success_count
            if campaign
            else 0
        ) or 0

        failure_count = (
            campaign.failure_count
            if campaign
            else 0
        ) or 0


        reminder_rows.append(
            {
                "reminder":
                    reminder,

                "scheduled_display":
                    format_boost_schedule_sast(
                        reminder.scheduled_for
                    ),

                "campaign":
                    campaign,

                "recipient_count":
                    recipient_count,

                "success_count":
                    success_count,

                "failure_count":
                    failure_count,

                "delivery_rate":
                    (
                        round(
                            (
                                success_count
                                /
                                recipient_count
                                * 100
                            ),
                            1,
                        )
                        if recipient_count
                        else 0
                    ),
            }
        )


    return render_template(
        "admin/event_boost.html",

        organizer=
            organizer,

        event=
            event,

        boost=
            boost,

        reminders=
            reminders,

        reminder_rows=
            reminder_rows,

        audience_count=
            audience_count,

        audience_analytics=
            audience_analytics,

        performance=
            performance,

        basic_price=
            EVENT_BOOST_BASIC_PRICE,

        pro_price=
            EVENT_BOOST_PRO_PRICE,

        radius_km=
            EVENT_BOOST_RADIUS_KM,
    )


