@app.route(
    "/admin/events/<int:event_id>/featured/images",
    methods=["POST"],
)
def admin_save_featured_images(event_id):

    auth = require_ticketing_organizer()
    if auth:
        return auth

    organizer = get_current_organizer()

    subscription_auth = (
        require_active_subscription(
            organizer
        )
    )

    if subscription_auth:
        return subscription_auth

    event = (
        TicketEvent.query
        .filter_by(
            id=event_id,
            organizer_id=organizer.id,
        )
        .first_or_404()
    )

    uploaded = [
        file
        for file in request.files.getlist(
            "featured_images"
        )
        if file and file.filename
    ]

    if not uploaded:
        flash(
            "Choose between 1 and 3 featured poster images.",
            "error",
        )
        return redirect(
            url_for(
                "admin_featured_listing",
                event_id=event.id,
            )
        )

    if len(uploaded) > FEATURED_IMAGE_MAX_COUNT:
        flash(
            "You can upload a maximum of 3 featured poster images.",
            "error",
        )
        return redirect(
            url_for(
                "admin_featured_listing",
                event_id=event.id,
            )
        )

    try:
        prepared = [
            validate_featured_image_upload(
                image
            )
            for image in uploaded
        ]
    except ValueError as error:
        flash(
            str(error),
            "error",
        )
        return redirect(
            url_for(
                "admin_featured_listing",
                event_id=event.id,
            )
        )

    try:

        for existing in list(
            event.featured_images
        ):
            db.session.delete(
                existing
            )

        db.session.flush()

        for index, image in enumerate(
            prepared,
            start=1,
        ):
            db.session.add(
                FeaturedListingImage(
                    event_id=event.id,
                    image_order=index,
                    image_data=image["data"],
                    image_mimetype=image[
                        "mimetype"
                    ],
                    image_filename=image[
                        "filename"
                    ],
                )
            )

        db.session.commit()

    except Exception as error:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Featured Listing] "
                "Failed saving images "
                "event_id=%s error=%s"
            ),
            event.id,
            error,
        )

        flash(
            "Featured posters could not be saved.",
            "error",
        )

        return redirect(
            url_for(
                "admin_featured_listing",
                event_id=event.id,
            )
        )

    flash(
        (
            f"{len(prepared)} featured poster"
            f"{'s' if len(prepared) != 1 else ''} saved."
        ),
        "success",
    )

    return redirect(
        url_for(
            "admin_featured_listing",
            event_id=event.id,
        )
    )


@app.route(
    "/admin/events/<int:event_id>/featured/purchase/<plan_code>",
    methods=["POST"],
)
def admin_purchase_featured_listing(
    event_id,
    plan_code,
):
    """
    Initialize a Paystack Featured Listing purchase.

    Payment model:
        - The organiser purchases advertising.
        - KALXA provides the advertising service.
        - No marketplace Transaction Split is applied.

    Security:
        - Requires authenticated organiser.
        - Requires active organiser subscription.
        - Event must belong to organiser.
        - Event must be published and active.
        - Past events cannot be featured.
        - Prevents duplicate active listings.
        - Validates featured image requirements.
        - Calculates amount server-side.
        - Uses an existing pending payment when appropriate.
        - Independently verifies payment before activation.

    IMPORTANT:
        This function only initializes payment.

        Featured Listing activation must happen
        after independent Paystack verification.
    """

    # ========================================================
    # 1. AUTHENTICATE ORGANISER
    # ========================================================

    auth = (
        require_ticketing_organizer()
    )

    if auth:
        return auth

    organizer = (
        get_current_organizer()
    )

    # ========================================================
    # 2. CHECK ACTIVE SUBSCRIPTION
    # ========================================================

    subscription_auth = (
        require_active_subscription(
            organizer
        )
    )

    if subscription_auth:
        return subscription_auth

    # ========================================================
    # 3. LOAD ORGANISER EVENT
    # ========================================================

    event = (
        TicketEvent.query
        .filter_by(
            id=event_id,
            organizer_id=organizer.id,
        )
        .first_or_404()
    )

    # ========================================================
    # 4. VALIDATE FEATURED LISTING PLAN
    # ========================================================

    try:

        plan = featured_listing_plan(
            plan_code
        )

    except ValueError:

        abort(400)

    # ========================================================
    # 5. VALIDATE EVENT STATUS
    # ========================================================

    if (
        event.status != "published"
        or not event.active
    ):

        flash(
            (
                "Publish the event before "
                "buying a Featured Listing."
            ),
            "error",
        )

        return redirect(
            url_for(
                "admin_featured_listing",
                event_id=event.id,
            )
        )

    # ========================================================
    # 6. CHECK EVENT DATE
    # ========================================================

    if (
        event.event_date
        and event.event_date < date.today()
    ):

        flash(
            "Past events cannot be featured.",
            "error",
        )

        return redirect(
            url_for(
                "admin_featured_listing",
                event_id=event.id,
            )
        )

    # ========================================================
    # 7. PREVENT DUPLICATE ACTIVE LISTINGS
    # ========================================================

    if get_active_featured_listing(
        event.id
    ):

        flash(
            (
                "This event already has an active "
                "Featured Listing. Buy another "
                "package after it expires."
            ),
            "error",
        )

        return redirect(
            url_for(
                "admin_featured_listing",
                event_id=event.id,
            )
        )

    # ========================================================
    # 8. REQUIRE EVENT POSTER
    # ========================================================

    if (
        not event.featured_images
        and not event.poster_image_mimetype
        and not event.image_url
    ):

        flash(
            (
                "Upload at least one featured "
                "poster image or add a normal "
                "event poster first."
            ),
            "error",
        )

        return redirect(
            url_for(
                "admin_featured_listing",
                event_id=event.id,
            )
        )

    # ========================================================
    # 9. FIND EXISTING PENDING LISTING
    # ========================================================

    pending = (
        FeaturedListing.query
        .filter_by(
            event_id=event.id,
            organizer_id=organizer.id,
            status="pending",
        )
        .order_by(
            FeaturedListing.created_at.desc()
        )
        .first()
    )

    # ========================================================
    # 10. HANDLE CHANGED PLAN
    # ========================================================

    if (
        pending
        and pending.plan_code != plan_code
    ):

        # Do not delete an existing checkout that
        # might already have been paid.
        #
        # Instead, prevent silent replacement and
        # require reconciliation.

        if (
            pending.paystack_authorization_url
            or pending.paystack_access_code
        ):

            flash(
                (
                    "An earlier Featured Listing checkout "
                    "exists. Please complete or reconcile "
                    "that payment before changing plans."
                ),
                "warning",
            )

            return redirect(
                url_for(
                    "admin_featured_listing",
                    event_id=event.id,
                )
            )

        db.session.delete(
            pending
        )

        db.session.commit()

        pending = None

    # ========================================================
    # 11. CREATE PENDING LISTING
    # ========================================================

    if not pending:

        pending = FeaturedListing(
            event_id=event.id,
            organizer_id=organizer.id,
            plan_code=plan_code,
            plan_name=plan["name"],
            price=plan["price"],
            duration_days=plan[
                "duration_days"
            ],
            status="pending",
            payment_reference=(
                generate_featured_listing_reference()
            ),
            payment_provider="paystack",
        )

        db.session.add(
            pending
        )

        db.session.commit()

    # ========================================================
    # 12. REUSE EXISTING CHECKOUT
    # ========================================================

    if pending.paystack_authorization_url:

        return redirect(
            pending.paystack_authorization_url
        )

    # ========================================================
    # 13. CALCULATE AMOUNT
    # ========================================================

    try:

        price = Decimal(
            str(
                pending.price
            )
        )

    except (
        InvalidOperation,
        TypeError,
        ValueError,
    ) as error:

        raise RuntimeError(
            "Invalid Featured Listing price."
        ) from error

    if (
        not price.is_finite()
        or price <= 0
    ):

        raise RuntimeError(
            "Invalid Featured Listing price."
        )

    amount_cents = (
        price
        * Decimal("100")
    )

    if (
        amount_cents
        != amount_cents.to_integral_value()
    ):

        raise RuntimeError(
            "Featured Listing price contains fractional cents."
        )

    amount_cents = int(
        amount_cents
    )

    # ========================================================
    # 14. BUILD CALLBACK URL
    # ========================================================

    callback_url = url_for(
        "paystack_featured_listing_callback",
        _external=True,
        _scheme="https",
    )

    # ========================================================
    # 15. BUILD PAYMENT METADATA
    # ========================================================

    metadata = {
        "payment_type": (
            "kalxa_featured_listing"
        ),
        "featured_listing_id": pending.id,
        "event_id": event.id,
        "organizer_id": organizer.id,
        "plan_code": pending.plan_code,
    }

    # ========================================================
    # 16. BUILD PAYSTACK PAYMENT PAYLOAD
    # ========================================================

    payload = {
        "email": organizer.email,
        "amount": str(
            amount_cents
        ),
        "currency": "ZAR",
        "reference": (
            pending.payment_reference
        ),
        "callback_url": callback_url,
        "channels": [
            "eft",
            "capitec_pay",
        ],
        "metadata": json.dumps(
            metadata
        ),

        # No split_code.
        #
        # Featured Listings are KALXA platform
        # advertising purchases.
    }

    # ========================================================
    # 17. INITIALIZE PAYSTACK CHECKOUT
    # ========================================================

    try:

        result = paystack_api_request(
            "POST",
            "/transaction/initialize",
            payload,
        )

        data = (
            result.get("data")
            or {}
        )

        authorization_url = (
            data.get(
                "authorization_url"
            )
        )

        if (
            not isinstance(
                authorization_url,
                str,
            )
            or not authorization_url.strip()
        ):

            raise RuntimeError(
                (
                    "Paystack did not return a "
                    "Featured Listing checkout URL."
                )
            )

        # ====================================================
        # 18. SAVE CHECKOUT DETAILS
        # ====================================================

        pending.paystack_access_code = (
            data.get(
                "access_code"
            )
            or None
        )

        pending.paystack_authorization_url = (
            authorization_url
        )

        db.session.commit()

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Featured Listing Paystack] "
                "Checkout initialization failed "
                "listing_id=%s event_id=%s"
            ),
            pending.id,
            event.id,
        )

        flash(
            (
                "Featured Listing checkout could "
                "not be started. Please try again."
            ),
            "error",
        )

        return redirect(
            url_for(
                "admin_featured_listing",
                event_id=event.id,
            )
        )

    # ========================================================
    # 19. REDIRECT TO PAYSTACK
    # ========================================================

    return redirect(
        authorization_url
    )


@app.route(
    "/payments/paystack/featured/callback",
    methods=["GET"],
)
def paystack_featured_listing_callback():
    """
    Handle the customer's return from Paystack
    after purchasing a Featured Listing.

    SECURITY:
        The callback URL does not prove payment.
        Always verify the transaction directly
        with Paystack before activating the listing.

    IDEMPOTENCY:
        The finalisation service must prevent
        repeated callbacks from activating or
        extending the same purchase more than once.

    This callback does not initiate settlements,
    refunds, or organiser transfers.
    """

    # ========================================================
    # EXTRACT PAYMENT REFERENCE
    # ========================================================

    reference = request.args.get("reference", "")

    if not isinstance(reference, str):
        abort(400)

    reference = reference.strip()

    if not reference:
        abort(400)

    # ========================================================
    # FIND FEATURED LISTING
    # ========================================================

    listing = (
        FeaturedListing.query
        .filter_by(
            payment_reference=reference,
        )
        .first_or_404()
    )

    # ========================================================
    # VERIFY PAYMENT DIRECTLY WITH PAYSTACK
    # ========================================================

    try:

        result = paystack_api_request(
            "GET",
            (
                "/transaction/verify/"
                + urllib.parse.quote(
                    reference,
                    safe="",
                )
            ),
        )

        if (
            not isinstance(result, dict)
            or result.get("status") is not True
        ):
            raise RuntimeError(
                "Paystack verification request failed."
            )

        transaction_data = result.get("data")

        if not isinstance(transaction_data, dict):
            raise RuntimeError(
                "Paystack returned invalid transaction data."
            )

        # ====================================================
        # VERIFY TRANSACTION REFERENCE
        # ====================================================

        if transaction_data.get("reference") != reference:
            raise RuntimeError(
                "Paystack transaction reference mismatch."
            )

        # ====================================================
        # VERIFY PAYMENT STATUS
        # ====================================================

        if transaction_data.get("status") != "success":
            raise RuntimeError(
                "Featured Listing payment is not successful."
            )

        # ====================================================
        # VERIFY CURRENCY
        # ====================================================

        if transaction_data.get("currency") != "ZAR":
            raise RuntimeError(
                "Unexpected Paystack payment currency."
            )

        # ====================================================
        # VERIFY PAYMENT AMOUNT FORMAT
        # ========================================================
        #
        # Paystack reports the amount in cents.
        #
        # The product-specific finaliser must also
        # verify this amount against the price stored
        # for this Featured Listing.
        # ====================================================

        verified_amount = transaction_data.get("amount")

        if (
            isinstance(verified_amount, bool)
            or not isinstance(verified_amount, int)
            or verified_amount <= 0
        ):
            raise RuntimeError(
                "Invalid Paystack transaction amount."
            )

        # ====================================================
        # VERIFY TRANSACTION ID
        # ====================================================

        transaction_id = transaction_data.get("id")

        if (
            isinstance(transaction_id, bool)
            or not isinstance(transaction_id, (int, str))
            or not str(transaction_id).strip()
        ):
            raise RuntimeError(
                "Missing Paystack transaction ID."
            )

        # ====================================================
        # FINALISE FEATURED LISTING PAYMENT
        # ========================================================
        #
        # IMPORTANT:
        #
        # finalize_featured_listing_payment() must
        # validate the expected purchase amount and
        # handle repeated calls idempotently.
        # ====================================================

        finalize_featured_listing_payment(
            listing,
            transaction_data,
        )

        current_app.logger.info(
            (
                "[Featured Listing Callback] "
                "Payment confirmed "
                "reference=%s listing_id=%s "
                "transaction_id=%s"
            ),
            reference,
            listing.id,
            transaction_id,
        )

        flash(
            (
                f"{listing.plan_name} activated. "
                "Your event is now featured on Kalxa."
            ),
            "success",
        )

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Featured Listing Callback] "
                "Payment verification or finalisation "
                "failed reference=%s listing_id=%s"
            ),
            reference,
            listing.id,
        )

        flash(
            (
                "Your Featured Listing payment could not "
                "be confirmed yet. Please check its "
                "status shortly."
            ),
            "warning",
        )

    # ========================================================
    # RETURN TO FEATURED LISTING PAGE
    # ========================================================

    return redirect(
        url_for(
            "admin_featured_listing",
            event_id=listing.event_id,
        )
    )


