# ORGANIZER - BUY EVENT BOOST
# ============================================================

@app.route(
    "/admin/events/<int:event_id>/boost/purchase/<plan_code>",
    methods=[
        "POST",
    ],
)
def admin_purchase_event_boost(
    event_id,
    plan_code,
):

    auth = (
        require_ticketing_organizer()
    )


    if auth:

        return auth


    organizer = (
        get_current_organizer()
    )


    subscription_auth = (
        require_active_subscription(
            organizer
        )
    )


    if subscription_auth:

        return subscription_auth


    event = (
        TicketEvent.query
        .filter_by(
            id=
                event_id,

            organizer_id=
                organizer.id,
        )
        .first_or_404()
    )


    try:

        plan = (
            event_boost_plan(
                plan_code
            )
        )


    except ValueError:

        abort(
            400
        )


    if (
        event.status
        != "published"
        or not event.active
    ):

        flash(
            "Publish the event before buying an Event Boost.",
            "error",
        )

        return redirect(
            url_for(
                "admin_event_boost",
                event_id=
                    event.id,
            )
        )


    if (
        event.notification_latitude
        is None
        or event.notification_longitude
        is None
    ):

        flash(
            "Edit the event and save its Event Area / Town first.",
            "error",
        )

        return redirect(
            url_for(
                "admin_event_boost",
                event_id=
                    event.id,
            )
        )


    if (
        event.event_date
        and event.event_date
        < date.today()
    ):

        flash(
            "Past events cannot be boosted.",
            "error",
        )

        return redirect(
            url_for(
                "admin_event_boost",
                event_id=
                    event.id,
            )
        )


    if (
        plan_code
        == "pro"
        and (
            not event.event_date
            or not event.event_time
        )
    ):

        flash(
            (
                "Event Boost Pro needs both an event date "
                "and event time so Kalxa can schedule the "
                "3-day, tomorrow and Happening Now reminders."
            ),
            "error",
        )

        return redirect(
            url_for(
                "admin_event_boost",
                event_id=
                    event.id,
            )
        )


    audience = (
        get_local_push_subscriptions(
            event,
            float(
                EVENT_BOOST_RADIUS_KM
            ),
        )
    )


    if not audience:

        flash(
            (
                "There are currently no opted-in users "
                f"within {EVENT_BOOST_RADIUS_KM:g} km "
                "of this event, so Kalxa will not charge "
                "you for a boost yet."
            ),
            "error",
        )

        return redirect(
            url_for(
                "admin_event_boost",
                event_id=
                    event.id,
            )
        )


    boost = (
        EventBoost.query
        .filter_by(
            event_id=
                event.id
        )
        .first()
    )


    if (
        boost
        and boost.status
        == "active"
    ):

        flash(
            "This event already has an active paid boost.",
            "error",
        )

        return redirect(
            url_for(
                "admin_event_boost",
                event_id=
                    event.id,
            )
        )


    if (
        boost
        and boost.status
        == "pending"
        and boost.plan_code
        != plan_code
    ):

        db.session.delete(
            boost
        )

        db.session.commit()

        boost = None


    if not boost:

        boost = EventBoost(

            event_id=
                event.id,

            plan_code=
                plan_code,

            plan_name=
                plan[
                    "name"
                ],

            price=
                plan[
                    "price"
                ],

            radius_km=
                EVENT_BOOST_RADIUS_KM,

            campaign_limit=
                plan[
                    "campaign_limit"
                ],

            status=
                "pending",

            payment_reference=
                generate_event_boost_reference(),

            payment_provider=
                "paystack",

            audience_count_at_purchase=
                len(
                    audience
                ),
        )


        db.session.add(
            boost
        )

        db.session.commit()


    if (
        boost.paystack_authorization_url
        and boost.plan_code
        == plan_code
    ):

        return redirect(
            boost.paystack_authorization_url
        )


    callback_url = url_for(
        "paystack_event_boost_callback",
        _external=
            True,
        _scheme=
            "https",
    )


    payload = {
        "email":
            organizer.email,

        "amount":
            str(
                int(
                    (
                        Decimal(
                            str(
                                boost.price
                            )
                        )
                        * 100
                    )
                    .quantize(
                        Decimal("1"),
                        rounding=
                            ROUND_UP,
                    )
                )
            ),

        "currency":
            "ZAR",

        "reference":
            boost.payment_reference,

        "callback_url":
            callback_url,

        # Boost revenue belongs to Kalxa, not the event
        # organizer settlement subaccount.
        "channels": [
            "eft",
            "capitec_pay",
        ],

        "metadata":
            json.dumps(
                {
                    "payment_type":
                        "kalxa_event_boost",

                    "event_boost_id":
                        boost.id,

                    "event_id":
                        event.id,

                    "organizer_id":
                        organizer.id,

                    "plan_code":
                        boost.plan_code,

                    "radius_km":
                        str(
                            boost.radius_km
                        ),
                }
            ),
    }


    try:

        result = (
            paystack_api_request(
                "POST",
                "/transaction/initialize",
                payload,
            )
        )


        data = (
            result.get(
                "data"
            )
            or {}
        )


        authorization_url = (
            data.get(
                "authorization_url"
            )
        )


        if not authorization_url:

            raise RuntimeError(
                "Paystack did not return a boost checkout URL."
            )


        boost.paystack_access_code = (
            data.get(
                "access_code"
            )
            or None
        )

        boost.paystack_authorization_url = (
            authorization_url
        )


        db.session.commit()


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Event Boost Paystack] "
                "Checkout initialization failed "
                "boost_id=%s event_id=%s error=%s"
            ),
            boost.id,
            event.id,
            error,
        )


        flash(
            (
                "Event Boost checkout could not be started. "
                "Please try again."
            ),
            "error",
        )


        return redirect(
            url_for(
                "admin_event_boost",
                event_id=
                    event.id,
            )
        )


    return redirect(
        authorization_url
    )


# ============================================================
# PAYSTACK EVENT BOOST CALLBACK
# ============================================================


@app.route(
    "/payments/paystack/boost/callback",
    methods=["GET"],
)
def paystack_event_boost_callback():
    """
    Handle the customer's return from Paystack
    after purchasing an Event Boost.

    SECURITY:
        The callback URL is not proof of payment.
        Verify directly with Paystack.

    IDEMPOTENCY:
        The boost finaliser must prevent duplicate
        payment activation.

        The reminder processor must prevent duplicate
        notifications across repeated callbacks.

    REMINDERS:
        Attempt immediate processing after successful
        finalisation.

        A background processor may retry pending work.

    This callback does not initiate settlements,
    refunds, or organiser transfers.
    """

    # ========================================================
    # EXTRACT PAYMENT REFERENCE
    # ========================================================

    reference = request.args.get("reference", "")

    if not isinstance(reference, str):
        abort(400)

    reference = reference.strip()

    if not reference:
        abort(400)

    # ========================================================
    # FIND EVENT BOOST
    # ========================================================

    boost = (
        EventBoost.query
        .filter_by(
            payment_reference=reference,
        )
        .first_or_404()
    )

    # ========================================================
    # VERIFY PAYMENT DIRECTLY WITH PAYSTACK
    # ========================================================

    try:

        result = paystack_api_request(
            "GET",
            (
                "/transaction/verify/"
                + urllib.parse.quote(
                    reference,
                    safe="",
                )
            ),
        )

        if (
            not isinstance(result, dict)
            or result.get("status") is not True
        ):
            raise RuntimeError(
                "Paystack verification request failed."
            )

        transaction_data = result.get("data")

        if not isinstance(transaction_data, dict):
            raise RuntimeError(
                "Paystack returned invalid transaction data."
            )

        # ====================================================
        # VERIFY TRANSACTION REFERENCE
        # ====================================================

        if transaction_data.get("reference") != reference:
            raise RuntimeError(
                "Paystack transaction reference mismatch."
            )

        # ====================================================
        # VERIFY PAYMENT STATUS
        # ====================================================

        if transaction_data.get("status") != "success":
            raise RuntimeError(
                "Event Boost payment is not successful."
            )

        # ====================================================
        # VERIFY CURRENCY
        # ====================================================

        if transaction_data.get("currency") != "ZAR":
            raise RuntimeError(
                "Unexpected Paystack payment currency."
            )

        # ====================================================
        # VERIFY PAYMENT AMOUNT FORMAT
        # ========================================================
        #
        # The product-specific finaliser must compare
        # this amount with the stored Boost price.
        # ====================================================

        verified_amount = transaction_data.get("amount")

        if (
            isinstance(verified_amount, bool)
            or not isinstance(verified_amount, int)
            or verified_amount <= 0
        ):
            raise RuntimeError(
                "Invalid Paystack transaction amount."
            )

        # ====================================================
        # VERIFY TRANSACTION ID
        # ====================================================

        transaction_id = transaction_data.get("id")

        if (
            isinstance(transaction_id, bool)
            or not isinstance(transaction_id, (int, str))
            or not str(transaction_id).strip()
        ):
            raise RuntimeError(
                "Missing Paystack transaction ID."
            )

        # ====================================================
        # FINALISE EVENT BOOST PAYMENT
        # ========================================================
        #
        # This service must:
        #
        # - Verify the expected Boost price.
        # - Prevent duplicate payment activation.
        # - Commit the successful purchase.
        # ====================================================

        finalize_event_boost_payment(
            boost,
            transaction_data,
        )

        current_app.logger.info(
            (
                "[Event Boost Callback] "
                "Payment confirmed "
                "reference=%s boost_id=%s "
                "transaction_id=%s"
            ),
            reference,
            boost.id,
            transaction_id,
        )

        # ====================================================
        # PROCESS IMMEDIATE EVENT BOOST REMINDERS
        # ========================================================
        #
        # Reminder processing is intentionally separate
        # from payment finalisation.
        #
        # A reminder-processing failure must not undo
        # a successfully verified payment.
        #
        # This processor must be idempotent because
        # the customer may reload the callback URL.
        # ====================================================

        try:

            process_due_event_boost_reminders(
                boost_id=boost.id,
                limit=4,
            )

        except Exception:

            db.session.rollback()

            current_app.logger.exception(
                (
                    "[Event Boost Callback] "
                    "Immediate reminder processing failed "
                    "boost_id=%s reference=%s"
                ),
                boost.id,
                reference,
            )

        # ====================================================
        # SUCCESS MESSAGE
        # ====================================================

        flash(
            (
                f"{boost.plan_name} activated successfully. "
                "Kalxa will use your local 80 km audience."
            ),
            "success",
        )

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Event Boost Callback] "
                "Payment verification or finalisation "
                "failed reference=%s boost_id=%s"
            ),
            reference,
            boost.id,
        )

        flash(
            (
                "Your Event Boost payment could not "
                "be confirmed yet. Please check its "
                "status shortly."
            ),
            "warning",
        )

    # ========================================================
    # RETURN TO EVENT BOOST PAGE
    # ========================================================

    return redirect(
        url_for(
            "admin_event_boost",
            event_id=boost.event_id,
        )
    )

# ============================================================
# EVENT BOOST TRAFFIC-BASED FALLBACK
# ============================================================
#
# The secured cron endpoint remains the reliable scheduler.
# This fallback checks at most once every 10 minutes per
# Gunicorn process whenever Kalxa receives traffic. Atomic
# reminder claiming prevents duplicate sends across workers.
# ============================================================

_boost_fallback_lock = (
    threading.Lock()
)

_boost_fallback_last_run = 0.0


@app.before_request
def process_due_boosts_on_traffic():

    global _boost_fallback_last_run


    if (
        request.endpoint
        == "process_event_boost_cron"
    ):

        return None


    now_monotonic = (
        time.monotonic()
    )


    if (
        now_monotonic
        - _boost_fallback_last_run
        < 600
    ):

        return None


    if not _boost_fallback_lock.acquire(
        blocking=False
    ):

        return None


    try:

        now_monotonic = (
            time.monotonic()
        )


        if (
            now_monotonic
            - _boost_fallback_last_run
            < 600
        ):

            return None


        _boost_fallback_last_run = (
            now_monotonic
        )


        try:

            process_due_event_boost_reminders(
                limit=
                    10
            )


        except Exception as error:

            db.session.rollback()

            current_app.logger.exception(
                (
                    "[Event Boost Fallback] "
                    "Due reminder processing failed error=%s"
                ),
                error,
            )


    finally:

        _boost_fallback_lock.release()


    return None


# ============================================================
# EVENT BOOST CRON PROCESSOR
# ============================================================

@app.route(
    "/tasks/event-boosts/process",
    methods=[
        "GET",
        "POST",
    ],
)
def process_event_boost_cron():

    if not BOOST_CRON_SECRET:

        abort(
            503
        )


    supplied_secret = (
        request.headers.get(
            "X-Cron-Secret",
            "",
        )
        .strip()
        or
        request.args.get(
            "token",
            "",
        )
        .strip()
    )


    if (
        not supplied_secret
        or not hmac.compare_digest(
            supplied_secret,
            BOOST_CRON_SECRET,
        )
    ):

        abort(
            403
        )


    result = (
        process_due_event_boost_reminders(
            limit=
                50
        )
    )


    return {
        "ok":
            True,
        **result,
    }


