@app.route(
    "/admin/events/<int:event_id>/orders"
)
def admin_orders(
    event_id,
):

    auth = (
        require_ticketing_organizer()
    )


    if auth:

        return auth


    organizer = (
        get_current_organizer()
    )


    event = (
        TicketEvent.query
        .filter_by(
            id=
                event_id,

            organizer_id=
                organizer.id,
        )
        .first_or_404()
    )


    orders = (
        TicketOrder.query
        .filter_by(
            event_id=
                event.id
        )
        .order_by(
            TicketOrder.created_at.desc()
        )
        .all()
    )


    total_orders = len(
        orders
    )

    paid_orders = sum(
        1
        for order in orders
        if order.payment_status == "paid"
    )

    pending_orders = sum(
        1
        for order in orders
        if order.payment_status == "pending"
    )

    cancelled_orders = sum(
        1
        for order in orders
        if order.payment_status == "cancelled"
    )

    ticket_revenue = sum(
        (
            Decimal(
                str(
                    order.total_amount
                    or 0
                )
            )
            for order in orders
            if order.payment_status == "paid"
        ),
        Decimal("0.00"),
    )

    processing_total = sum(
        (
            Decimal(
                str(
                    order.processing_fee
                    or 0
                )
            )
            for order in orders
            if order.payment_status == "paid"
        ),
        Decimal("0.00"),
    )

    checkout_total = sum(
        (
            Decimal(
                str(
                    order.checkout_amount
                    or order.total_amount
                    or 0
                )
            )
            for order in orders
            if order.payment_status == "paid"
        ),
        Decimal("0.00"),
    )


    return render_template(
        "admin/orders.html",

        organizer=
            organizer,

        event=
            event,

        orders=
            orders,

        total_orders=
            total_orders,

        paid_orders=
            paid_orders,

        pending_orders=
            pending_orders,

        cancelled_orders=
            cancelled_orders,

        ticket_revenue=
            ticket_revenue,

        processing_total=
            processing_total,

        checkout_total=
            checkout_total,
    )

