# VERIFY PAYSTACK ORDER
# ============================================================

@app.route(
    "/admin/orders/<int:order_id>/verify-paystack",
    methods=[
        "POST",
    ],
)
def admin_verify_paystack_order(
    order_id,
):

    auth = (
        require_ticketing_organizer()
    )


    if auth:

        return auth


    organizer = (
        get_current_organizer()
    )


    order = (
        TicketOrder.query

        .join(
            TicketEvent,
            TicketOrder.event_id
            == TicketEvent.id,
        )

        .filter(
            TicketOrder.id
            == order_id
        )

        .filter(
            TicketEvent.organizer_id
            == organizer.id
        )

        .first_or_404()
    )


    event = (
        order.event
    )


    if (
        order.payment_provider
        != "paystack"
    ):

        flash(
            (
                "This order is not a Paystack order."
            ),
            "error",
        )


        return redirect(
            url_for(
                "admin_orders",
                event_id=
                    event.id,
            )
        )


    if (
        order.payment_status
        == "paid"
    ):

        flash(
            (
                "This Paystack order is already verified "
                "and marked paid."
            ),
            "success",
        )


        return redirect(
            url_for(
                "admin_orders",
                event_id=
                    event.id,
            )
        )


    try:

        result = (
            paystack_api_request(
                "GET",
                (
                    "/transaction/verify/"
                    + urllib.parse.quote(
                        order.payment_reference,
                        safe="",
                    )
                ),
            )
        )


        transaction_data = (
            result.get(
                "data"
            )
            or {}
        )


        if (
            transaction_data.get(
                "status"
            )
            != "success"
        ):

            flash(
                (
                    "Paystack has not confirmed this "
                    "payment as successful yet."
                ),
                "error",
            )


            return redirect(
                url_for(
                    "admin_orders",
                    event_id=
                        event.id,
                )
            )


        finalize_paystack_ticket_order(
            order,
            transaction_data,
        )


    except Exception as error:

        db.session.rollback()


        current_app.logger.exception(
            (
                "[Paystack Audit Verify] "
                "Verification failed organizer_id=%s "
                "order_id=%s reference=%s error=%s"
            ),
            organizer.id,
            order.id,
            order.payment_reference,
            error,
        )


        flash(
            (
                "Paystack verification could not be completed. "
                "The order was not changed."
            ),
            "error",
        )


        return redirect(
            url_for(
                "admin_orders",
                event_id=
                    event.id,
            )
        )


    flash(
        (
            "Paystack payment verified. "
            "The order is confirmed and its ticket is available."
        ),
        "success",
    )


    return redirect(
        url_for(
            "admin_orders",
            event_id=
                event.id,
        )
    )




def _kalxa_verified_paystack_transaction(reference):
    """Fetch a verified successful ZAR transaction from Paystack."""
    if not isinstance(reference, str) or not reference.strip():
        raise RuntimeError("Missing Paystack payment reference.")
    reference = reference.strip()
    result = paystack_api_request(
        "GET", "/transaction/verify/" + urllib.parse.quote(reference, safe="")
    )
    if not isinstance(result, dict) or result.get("status") is not True:
        raise RuntimeError("Paystack verification request failed.")
    data = result.get("data")
    if not isinstance(data, dict):
        raise RuntimeError("Paystack returned invalid transaction data.")
    if data.get("reference") != reference:
        raise RuntimeError("Verified Paystack reference mismatch.")
    if data.get("status") != "success" or data.get("currency") != "ZAR":
        raise RuntimeError("Paystack transaction is not a successful ZAR payment.")
    amount = data.get("amount")
    if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
        raise RuntimeError("Invalid verified Paystack amount.")
    return data





# ============================================================
# PAYSTACK TICKET PAYMENT CALLBACK
# ============================================================

@app.route(
    "/payments/paystack/callback",
    methods=["GET"],
)
def paystack_ticket_callback():
    """
    Customer return URL after Paystack checkout.

    Security:
        - Require payment reference.
        - Find the matching ticket order.
        - Verify payment directly with Paystack.
        - Finalize the ticket order only after verification.
        - Preserve KALXA's 4% commission accounting.
        - Never trust callback parameters as proof of payment.
    """

    # ========================================================
    # 1. GET PAYMENT REFERENCE
    # ========================================================

    reference = (
        request.args.get("reference") or ""
    ).strip()

    if not reference:
        abort(400)

    # ========================================================
    # 2. FIND TICKET ORDER
    # ========================================================

    order = (
        TicketOrder.query
        .filter_by(
            payment_reference=reference
        )
        .first_or_404()
    )

    # ========================================================
    # 3. VERIFY PAYMENT WITH PAYSTACK
    # ========================================================

    try:

        transaction_data = (
            _kalxa_verified_paystack_transaction(
                reference
            )
        )

        # ====================================================
        # 4. FINALIZE VERIFIED PAYMENT
        # ====================================================
        #
        # Your existing finalization function handles:
        #
        # - Payment verification
        # - Order payment status
        # - KALXA 4% commission recording
        # - Entry-pass generation
        # - Database commit
        #
        # Do not calculate commission again here.
        # ====================================================

        finalize_paystack_ticket_order(
            order,
            transaction_data,
        )

        flash(
            (
                "Payment confirmed. "
                "Your Kalxa ticket is ready."
            ),
            "success",
        )

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Paystack Ticket Callback] "
                "Verification/finalisation failed "
                "reference=%s"
            ),
            reference,
        )

        flash(
            (
                "Your payment could not be confirmed yet. "
                "Please check your booking status shortly."
            ),
            "warning",
        )

    # ========================================================
    # 5. REDIRECT TO BOOKING STATUS
    # ========================================================

    return redirect(
        url_for(
            "booking_status",
            reference=reference,
        )
    )
    
    
