@app.route(
    "/payments/paystack/subscription/callback",
    methods=["GET"],
)
def paystack_subscription_callback():
    """
    Legacy organiser subscription callback.

    Security:
        - Requires a valid payment reference.
        - Finds an existing local subscription payment.
        - Independently verifies the transaction.
        - Uses the existing finalization service.
        - Does not automatically approve organisers.

    IMPORTANT:
        finalize_paystack_subscription_payment()
        must enforce amount matching, ownership,
        idempotency, and valid payment state.
    """

    # ========================================================
    # 1. GET PAYMENT REFERENCE
    # ========================================================

    reference = (
        request.args.get("reference") or ""
    ).strip()

    if (
        not reference
        or len(reference) > 200
    ):

        abort(400)

    # ========================================================
    # 2. FIND LOCAL PAYMENT
    # ========================================================

    payment = (
        SubscriptionPayment.query
        .filter_by(
            payment_reference=reference
        )
        .first_or_404()
    )

    # ========================================================
    # 3. HANDLE CANCELLED CHECKOUT
    # ========================================================

    if payment.payment_status == "cancelled":

        current_app.logger.warning(
            (
                "[Legacy Subscription Callback] "
                "Cancelled payment requires "
                "manual reconciliation "
                "reference=%s payment_id=%s"
            ),
            reference,
            payment.id,
        )

        flash(
            (
                "This checkout was cancelled. "
                "Contact support if you were charged."
            ),
            "warning",
        )

        return redirect(
            url_for("admin_subscription")
        )

    # ========================================================
    # 4. VERIFY PAYMENT
    # ========================================================

    try:

        transaction_data = (
            _kalxa_verified_paystack_transaction(
                reference
            )
        )

        # ====================================================
        # 5. FINALIZE VERIFIED SUBSCRIPTION
        # ====================================================

        finalize_paystack_subscription_payment(
            payment,
            transaction_data,
        )

        current_app.logger.info(
            (
                "[Legacy Subscription Callback] "
                "Payment processed "
                "reference=%s payment_id=%s"
            ),
            reference,
            payment.id,
        )

        flash(
            (
                "Subscription payment confirmed. "
                "Event organiser approval is "
                "managed separately."
            ),
            "success",
        )

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Legacy Subscription Callback] "
                "Verification or finalization failed "
                "reference=%s"
            ),
            reference,
        )

        flash(
            (
                "Your subscription payment is still "
                "being verified. "
                "Please check again shortly."
            ),
            "warning",
        )

    # ========================================================
    # 6. REDIRECT
    # ========================================================

    return redirect(
        url_for("admin_subscription")
    )
    
 # ============================================================
# KALXA TICKETING
# SECURE EVENT TICKET CHECK-IN
# ============================================================

def perform_ticket_checkin(
    pass_id,
    organizer_id,
    checked_in_by,
    staff_account_id=None,
    allowed_event_ids=None,
):
    """
    Atomically check in a KALXA event ticket.

    Supported users:
        - Event organisers
        - Authorised event staff

    Security:
        - Verify organiser ownership.
        - Enforce staff event assignments.
        - Require confirmed payment.
        - Reject cancelled/refunded tickets.
        - Block tickets with active refunds.
        - Prevent duplicate check-ins.
        - Prevent simultaneous gate admissions.
        - Record check-in history.

    Returns:
        (
            success: bool,
            message: str,
            entry_pass: EntryPass | None,
        )

    IMPORTANT:
        The caller must authenticate the operator and
        derive organiser/staff/event permissions from
        trusted server-side state.
    """

    # ========================================================
    # 1. VALIDATE REQUIRED IDENTIFIERS
    # ========================================================

    if (
        isinstance(pass_id, bool)
        or not isinstance(pass_id, int)
        or pass_id <= 0
    ):
        return (
            False,
            "Invalid ticket identifier.",
            None,
        )

    if (
        isinstance(organizer_id, bool)
        or not isinstance(organizer_id, int)
        or organizer_id <= 0
    ):
        return (
            False,
            "Invalid organiser identifier.",
            None,
        )

    if (
        not isinstance(checked_in_by, str)
        or not checked_in_by.strip()
    ):
        return (
            False,
            "Invalid check-in operator.",
            None,
        )

    checked_in_by = checked_in_by.strip()

    # ========================================================
    # 2. VALIDATE STAFF ACCOUNT
    # ========================================================

    if staff_account_id is not None:

        if (
            isinstance(staff_account_id, bool)
            or not isinstance(staff_account_id, int)
            or staff_account_id <= 0
        ):
            return (
                False,
                "Invalid staff account.",
                None,
            )

    # ========================================================
    # 3. VALIDATE STAFF EVENT ASSIGNMENTS
    # ========================================================

    if allowed_event_ids is not None:

        try:
            allowed_event_ids = list(
                allowed_event_ids
            )

        except TypeError:
            return (
                False,
                "Invalid event assignments.",
                None,
            )

        if not allowed_event_ids:
            return (
                False,
                "You are not assigned to this event.",
                None,
            )

        if any(
            isinstance(event_id, bool)
            or not isinstance(event_id, int)
            or event_id <= 0
            for event_id in allowed_event_ids
        ):
            return (
                False,
                "Invalid event assignments.",
                None,
            )

    # ========================================================
    # 4. BEGIN DATABASE TRANSACTION
    # ========================================================

    try:

        query = (
            db.session.query(EntryPass)
            .join(
                TicketOrder,
                EntryPass.order_id == TicketOrder.id,
            )
            .join(
                TicketEvent,
                TicketOrder.event_id == TicketEvent.id,
            )
            .filter(
                EntryPass.id == pass_id,
                TicketEvent.organizer_id == organizer_id,
            )
        )

        if allowed_event_ids is not None:

            query = query.filter(
                TicketEvent.id.in_(
                    allowed_event_ids
                )
            )

        # ====================================================
        # 5. LOCK ENTRY PASS
        # ========================================================
        #
        # PostgreSQL SELECT FOR UPDATE prevents another
        # transaction from modifying this entry pass
        # while the current check-in is being processed.
        # ========================================================

        entry_pass = (
            query
            .populate_existing()
            .with_for_update(
                of=EntryPass
            )
            .one_or_none()
        )

        if entry_pass is None:

            db.session.rollback()

            return (
                False,
                "Ticket not found for your assigned events.",
                None,
            )

        # ====================================================
        # 6. VERIFY ORDER
        # ========================================================

        order = entry_pass.order

        if (
            order is None
            or order.event is None
        ):

            db.session.rollback()

            return (
                False,
                "This ticket record is incomplete.",
                None,
            )

        # ====================================================
        # 7. VERIFY PAYMENT
        # ========================================================

        if order.payment_status != "paid":

            db.session.rollback()

            return (
                False,
                (
                    "This ticket cannot be checked in "
                    "because payment has not been confirmed."
                ),
                None,
            )

        # ====================================================
        # 8. REJECT CANCELLED / REFUNDED TICKETS
        # ========================================================

        if entry_pass.status == "cancelled":

            db.session.rollback()

            return (
                False,
                "This ticket has been cancelled.",
                None,
            )

        if entry_pass.status == "refunded":

            db.session.rollback()

            return (
                False,
                "This ticket has been refunded.",
                None,
            )

        # ====================================================
        # 9. REJECT PREVIOUSLY USED TICKETS
        # ========================================================

        if (
            entry_pass.status == "used"
            or entry_pass.checked_in_at is not None
        ):

            db.session.rollback()

            return (
                False,
                "This ticket has already been checked in.",
                None,
            )

        if entry_pass.status != "valid":

            db.session.rollback()

            return (
                False,
                "This ticket is not valid.",
                None,
            )

        # ====================================================
        # 10. BLOCK ACTIVE OR COMPLETED REFUNDS
        # ========================================================
        #
        # A ticket may still have status="valid"
        # while Paystack processes a refund.
        #
        # It must not be admitted during this period.
        #
        # Failed/cancelled refund attempts do not
        # automatically prevent admission.
        # ========================================================

        active_refund_statuses = (
            "requested",
            "submitted",
            "pending",
            "processing",
            "succeeded",
        )

        active_refund = (
            db.session.query(
                TicketRefund.id
            )
            .join(
                TicketRefundItem,
                TicketRefundItem.refund_id
                == TicketRefund.id,
            )
            .filter(
                TicketRefund.order_id == order.id,
                TicketRefundItem.entry_pass_id
                == entry_pass.id,
                TicketRefund.status.in_(
                    active_refund_statuses
                ),
            )
            .first()
        )

        if active_refund is not None:

            db.session.rollback()

            current_app.logger.warning(
                (
                    "[Ticketing Check-In] "
                    "Blocked refunded/refunding ticket "
                    "pass_id=%s order_id=%s"
                ),
                entry_pass.id,
                order.id,
            )

            return (
                False,
                (
                    "This ticket cannot be checked in "
                    "because a refund is pending "
                    "or has been completed."
                ),
                None,
            )

        # ====================================================
        # 11. CHECK EXISTING CHECK-IN HISTORY
        # ========================================================

        existing_checkin = (
            db.session.query(
                CheckIn.id
            )
            .filter(
                CheckIn.entry_pass_id
                == entry_pass.id
            )
            .first()
        )

        if existing_checkin is not None:

            db.session.rollback()

            return (
                False,
                "This ticket has already been checked in.",
                None,
            )

        # ====================================================
        # 12. ATOMIC STATE TRANSITION
        # ========================================================

        now = datetime.utcnow()

        updated = (
            db.session.query(
                EntryPass
            )
            .filter(
                EntryPass.id == entry_pass.id,
                EntryPass.status == "valid",
                EntryPass.checked_in_at.is_(None),
            )
            .update(
                {
                    EntryPass.status: "used",
                    EntryPass.checked_in_at: now,
                },
                synchronize_session=False,
            )
        )

        if updated != 1:

            db.session.rollback()

            return (
                False,
                (
                    "This ticket has already been checked in "
                    "or is no longer valid."
                ),
                None,
            )

        # ====================================================
        # 13. CREATE CHECK-IN AUDIT RECORD
        # ========================================================

        checkin = CheckIn(
            entry_pass_id=entry_pass.id,
            checked_in_at=now,
            checked_in_by=checked_in_by,
            staff_account_id=staff_account_id,
        )

        db.session.add(
            checkin
        )

        # ====================================================
        # 14. COMMIT CHECK-IN ATOMICALLY
        # ========================================================

        db.session.commit()

        entry_pass = db.session.get(
            EntryPass,
            pass_id,
        )

        # ====================================================
        # 15. AUDIT LOG
        # ========================================================

        current_app.logger.info(
            (
                "[Ticketing Check-In] "
                "Ticket checked in successfully "
                "pass_id=%s "
                "organizer_id=%s "
                "staff_account_id=%s "
                "operator=%s"
            ),
            pass_id,
            organizer_id,
            staff_account_id,
            checked_in_by,
        )

        return (
            True,
            "Ticket checked in successfully.",
            entry_pass,
        )

    except Exception:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Ticketing Check-In] "
                "Check-in failed "
                "pass_id=%s "
                "organizer_id=%s "
                "staff_account_id=%s"
            ),
            pass_id,
            organizer_id,
            staff_account_id,
        )

        return (
            False,
            "Ticket check-in failed. Please try again.",
            None,
        )
