# STAFF CHECK-IN — QR / CODE LOOKUP
# ============================================================

@app.route(
    "/staff/checkin",
    methods=[
        "GET",
        "POST",
    ],
)
def staff_checkin():

    auth = require_staff_account()
    if auth:
        return auth

    staff = get_current_staff()
    event_ids = get_staff_event_ids(staff)

    assigned_events = (
        TicketEvent.query
        .filter(
            TicketEvent.id.in_(
                event_ids or [-1]
            )
        )
        .order_by(
            TicketEvent.event_date.asc(),
            TicketEvent.event_time.asc(),
        )
        .all()
    )

    selected_event_id = request.args.get(
        "event_id",
        type=int,
    )

    if request.method == "POST":
        selected_event_id = request.form.get(
            "event_id",
            type=int,
        )

    if (
        selected_event_id
        and selected_event_id
        not in set(event_ids or [])
    ):
        abort(403)

    entry_pass = None
    message = None

    if request.method == "POST":

        raw_value = (
            request.form.get(
                "entry_code",
                "",
            )
            .strip()
        )

        if not raw_value:
            message = (
                "No ticket code was provided."
            )

        else:

            entry_code = raw_value.upper()

            if "/TICKET/" in entry_code:
                entry_code = (
                    entry_code
                    .split(
                        "/TICKET/",
                        1,
                    )[1]
                    .split("?", 1)[0]
                    .split("#", 1)[0]
                    .strip()
                )

            lookup = (
                EntryPass.query
                .join(
                    TicketOrder,
                    EntryPass.order_id
                    == TicketOrder.id,
                )
                .join(
                    TicketEvent,
                    TicketOrder.event_id
                    == TicketEvent.id,
                )
                .filter(
                    EntryPass.entry_code
                    == entry_code,
                    TicketEvent.organizer_id
                    == staff.organizer_id,
                    TicketEvent.id.in_(
                        event_ids or [-1]
                    ),
                )
            )

            if selected_event_id:
                lookup = lookup.filter(
                    TicketEvent.id
                    == selected_event_id
                )

            entry_pass = lookup.first()

            if not entry_pass:
                message = (
                    "Ticket not found for your assigned events."
                )
            elif (
                entry_pass.order.payment_status
                != "paid"
            ):
                message = (
                    "Payment has not been confirmed."
                )
            elif entry_pass.is_used:
                message = (
                    "This ticket has already been used."
                )
            elif not entry_pass.is_valid:
                message = (
                    "This ticket is not valid."
                )

    return render_template(
        "staff/checkin.html",
        staff=staff,
        assigned_events=assigned_events,
        selected_event_id=selected_event_id,
        entry_pass=entry_pass,
        message=message,
    )


@app.route(
    "/staff/checkin/<int:pass_id>",
    methods=["POST"],
)
def staff_confirm_checkin(pass_id):

    auth = require_staff_account()
    if auth:
        return auth

    staff = get_current_staff()
    event_ids = get_staff_event_ids(staff)

    return_event_id = request.form.get(
        "event_id",
        type=int,
    )

    try:

        success, message, entry_pass = (
            perform_ticket_checkin(
                pass_id=pass_id,
                organizer_id=staff.organizer_id,
                checked_in_by=(
                    f"staff:{staff.id}:{staff.username}"
                ),
                staff_account_id=staff.id,
                allowed_event_ids=event_ids,
            )
        )

    except Exception as error:

        db.session.rollback()

        current_app.logger.exception(
            (
                "[Staff Check-In] Failed "
                "staff_id=%s pass_id=%s error=%s"
            ),
            staff.id,
            pass_id,
            error,
        )

        flash(
            "Ticket check-in failed. Please try again.",
            "error",
        )

        if (
            return_event_id
            and return_event_id
            in set(event_ids or [])
        ):
            return redirect(
                url_for(
                    "staff_event_guest_list",
                    event_id=return_event_id,
                )
            )

        return redirect(
            url_for("staff_checkin")
        )

    flash(
        message,
        "success" if success else "error",
    )

    if (
        return_event_id
        and return_event_id
        in set(event_ids or [])
    ):
        return redirect(
            url_for(
                "staff_event_guest_list",
                event_id=return_event_id,
            )
        )

    event_id = (
        entry_pass.event.id
        if entry_pass
        and entry_pass.event
        else None
    )

    return redirect(
        url_for(
            "staff_checkin",
            event_id=event_id,
        )
    )




# ============================================================
# ATTENDEE CRM-LITE HELPERS
# ============================================================

def parse_crm_date(
    value,
):

    value = (
        str(
            value
            or ""
        )
        .strip()
    )


    if not value:

        return None


    try:

        return datetime.strptime(
            value,
            "%Y-%m-%d",
        )


    except ValueError:

        return None


def build_attendee_crm(
    organizer,
    args,
):

    event_id_raw = (
        str(
            args.get(
                "event_id",
                ""
            )
        )
        .strip()
    )

    ticket_type_filter = (
        str(
            args.get(
                "ticket_type",
                ""
            )
        )
        .strip()
    )

    payment_status = (
        str(
            args.get(
                "payment_status",
                "paid",
            )
        )
        .strip()
        .lower()
    )

    checkin_status = (
        str(
            args.get(
                "checkin_status",
                "all",
            )
        )
        .strip()
        .lower()
    )

    search_value = (
        str(
            args.get(
                "q",
                ""
            )
        )
        .strip()
    )

    date_from_raw = (
        str(
            args.get(
                "date_from",
                ""
            )
        )
        .strip()
    )

    date_to_raw = (
        str(
            args.get(
                "date_to",
                ""
            )
        )
        .strip()
    )


    events = (
        TicketEvent.query
        .filter_by(
            organizer_id=
                organizer.id,
        )
        .order_by(
            TicketEvent.event_date.desc(),
            TicketEvent.created_at.desc(),
        )
        .all()
    )


    event_ids = [
        event.id
        for event in events
    ]


    query = (
        TicketOrder.query
        .filter(
            TicketOrder.event_id.in_(
                event_ids
                or [-1]
            )
        )
    )


    selected_event_id = None


    if event_id_raw.isdigit():

        candidate = int(
            event_id_raw
        )

        if candidate in set(
            event_ids
        ):

            selected_event_id = (
                candidate
            )

            query = query.filter(
                TicketOrder.event_id
                == candidate
            )


    if payment_status in {
        "paid",
        "pending",
        "cancelled",
    }:

        query = query.filter(
            TicketOrder.payment_status
            == payment_status
        )

    else:

        payment_status = (
            "all"
        )


    date_from = (
        parse_crm_date(
            date_from_raw
        )
    )

    date_to = (
        parse_crm_date(
            date_to_raw
        )
    )


    if date_from:

        query = query.filter(
            TicketOrder.created_at
            >= date_from
        )


    if date_to:

        query = query.filter(
            TicketOrder.created_at
            < (
                date_to
                + timedelta(
                    days=1
                )
            )
        )


    if search_value:

        pattern = (
            "%"
            + search_value
            + "%"
        )

        query = query.filter(
            or_(
                TicketOrder.customer_name.ilike(
                    pattern
                ),
                TicketOrder.customer_email.ilike(
                    pattern
                ),
                TicketOrder.customer_phone.ilike(
                    pattern
                ),
                TicketOrder.payment_reference.ilike(
                    pattern
                ),
            )
        )


    orders = (
        query
        .order_by(
            TicketOrder.created_at.desc()
        )
        .all()
    )


    rows = []


    for order in orders:

        event = (
            order.event
        )


        if not event:

            continue


        if order.order_items:

            line_items = (
                order.order_items
            )

        else:

            line_items = [
                None
            ]


        for item in line_items:

            ticket_name = (
                item.ticket_name
                if item
                else "General"
            )

            quantity = (
                item.quantity
                if item
                else (
                    order.quantity
                    or 1
                )
            )

            unit_price = (
                item.unit_price
                if item
                else order.ticket_price
            )

            line_total = (
                item.line_total
                if item
                else order.total_amount
            )

            passes = (
                item.entry_passes
                if item
                else order.entry_passes
            )


            checked_in_count = sum(
                1
                for entry_pass in passes
                if entry_pass.is_used
            )


            if checked_in_count <= 0:

                row_checkin_status = (
                    "not_checked_in"
                )

            elif checked_in_count >= quantity:

                row_checkin_status = (
                    "checked_in"
                )

            else:

                row_checkin_status = (
                    "partial"
                )


            if (
                ticket_type_filter
                and ticket_name.casefold()
                != ticket_type_filter.casefold()
            ):

                continue


            if (
                checkin_status
                in {
                    "checked_in",
                    "not_checked_in",
                    "partial",
                }
                and row_checkin_status
                != checkin_status
            ):

                continue


            rows.append(
                {
                    "event":
                        event.title,

                    "event_id":
                        event.id,

                    "customer_name":
                        order.customer_name,

                    "customer_email":
                        order.customer_email
                        or "",

                    "customer_phone":
                        order.customer_phone
                        or "",

                    "booking_reference":
                        order.payment_reference,

                    "ticket_type":
                        ticket_name,

                    "quantity":
                        quantity,

                    "checked_in_count":
                        checked_in_count,

                    "not_checked_in_count":
                        max(
                            0,
                            quantity
                            - checked_in_count,
                        ),

                    "checkin_status":
                        row_checkin_status,

                    "payment_status":
                        order.payment_status,

                    "unit_price":
                        unit_price,

                    "line_total":
                        line_total,

                    "purchase_date":
                        order.created_at,

                    "paid_at":
                        order.paid_at,
                }
            )


    ticket_types = sorted(
        {
            (
                item.ticket_name
                if item
                else "General"
            )
            for order in (
                TicketOrder.query
                .filter(
                    TicketOrder.event_id.in_(
                        event_ids
                        or [-1]
                    )
                )
                .all()
            )
            for item in (
                order.order_items
                or [None]
            )
        },
        key=lambda value:
            value.casefold(),
    )


    filters = {
        "event_id":
            (
                str(
                    selected_event_id
                )
                if selected_event_id
                else ""
            ),

        "ticket_type":
            ticket_type_filter,

        "payment_status":
            payment_status,

        "checkin_status":
            checkin_status,

        "date_from":
            date_from_raw,

        "date_to":
            date_to_raw,

        "q":
            search_value,
    }


    summary = {
        "rows":
            len(
                rows
            ),

        "tickets":
            sum(
                int(
                    row[
                        "quantity"
                    ]
                    or 0
                )
                for row in rows
            ),

        "checked_in":
            sum(
                int(
                    row[
                        "checked_in_count"
                    ]
                    or 0
                )
                for row in rows
            ),

        "revenue":
            sum(
                (
                    Decimal(
                        str(
                            row[
                                "line_total"
                            ]
                            or 0
                        )
                    )
                    for row in rows
                    if row[
                        "payment_status"
                    ] == "paid"
                ),
                Decimal(
                    "0.00"
                ),
            ),
    }


    return {
        "rows":
            rows,

        "events":
            events,

        "ticket_types":
            ticket_types,

        "filters":
            filters,

        "summary":
            summary,
    }


