@app.route(
    "/admin/attendees"
)
def admin_attendees():

    auth = (
        require_ticketing_organizer()
    )


    if auth:

        return auth


    organizer = (
        get_current_organizer()
    )


    subscription_auth = (
        require_active_subscription(
            organizer
        )
    )


    if subscription_auth:

        return subscription_auth


    crm = (
        build_attendee_crm(
            organizer,
            request.args,
        )
    )


    return render_template(
        "admin/attendees.html",

        organizer=
            organizer,

        **crm,
    )


@app.route(
    "/admin/attendees/export.csv"
)
def admin_attendees_export_csv():

    auth = (
        require_ticketing_organizer()
    )


    if auth:

        return auth


    organizer = (
        get_current_organizer()
    )


    subscription_auth = (
        require_active_subscription(
            organizer
        )
    )


    if subscription_auth:

        return subscription_auth


    crm = (
        build_attendee_crm(
            organizer,
            request.args,
        )
    )


    output = io.StringIO(
        newline=""
    )

    writer = csv.writer(
        output
    )


    writer.writerow(
        [
            "Event",
            "Attendee / Buyer",
            "Email",
            "Phone",
            "Booking Reference",
            "Ticket Type",
            "Quantity",
            "Checked In",
            "Not Checked In",
            "Check-In Status",
            "Payment Status",
            "Unit Price",
            "Line Total",
            "Purchased At",
            "Paid At",
        ]
    )


    for row in crm[
        "rows"
    ]:

        writer.writerow(
            [
                row[
                    "event"
                ],
                row[
                    "customer_name"
                ],
                row[
                    "customer_email"
                ],
                row[
                    "customer_phone"
                ],
                row[
                    "booking_reference"
                ],
                row[
                    "ticket_type"
                ],
                row[
                    "quantity"
                ],
                row[
                    "checked_in_count"
                ],
                row[
                    "not_checked_in_count"
                ],
                row[
                    "checkin_status"
                ],
                row[
                    "payment_status"
                ],
                (
                    f"{Decimal(str(row['unit_price'] or 0)):.2f}"
                ),
                (
                    f"{Decimal(str(row['line_total'] or 0)):.2f}"
                ),
                (
                    row[
                        "purchase_date"
                    ].strftime(
                        "%Y-%m-%d %H:%M:%S"
                    )
                    if row[
                        "purchase_date"
                    ]
                    else ""
                ),
                (
                    row[
                        "paid_at"
                    ].strftime(
                        "%Y-%m-%d %H:%M:%S"
                    )
                    if row[
                        "paid_at"
                    ]
                    else ""
                ),
            ]
        )


    filename = (
        "kalxa-attendees-"
        + datetime.utcnow().strftime(
            "%Y%m%d-%H%M"
        )
        + ".csv"
    )


    return Response(
        "\ufeff"
        + output.getvalue(),

        mimetype=(
            "text/csv; charset=utf-8"
        ),

        headers={
            "Content-Disposition":
                f'attachment; filename="{filename}"'
        },
    )


@app.route(
    "/admin/attendees/export.xlsx"
)
def admin_attendees_export_xlsx():

    auth = (
        require_ticketing_organizer()
    )


    if auth:

        return auth


    organizer = (
        get_current_organizer()
    )


    subscription_auth = (
        require_active_subscription(
            organizer
        )
    )


    if subscription_auth:

        return subscription_auth


    crm = (
        build_attendee_crm(
            organizer,
            request.args,
        )
    )


    workbook = Workbook()

    worksheet = (
        workbook.active
    )

    worksheet.title = (
        "Attendees"
    )


    headers = [
        "Event",
        "Attendee / Buyer",
        "Email",
        "Phone",
        "Booking Reference",
        "Ticket Type",
        "Quantity",
        "Checked In",
        "Not Checked In",
        "Check-In Status",
        "Payment Status",
        "Unit Price",
        "Line Total",
        "Purchased At",
        "Paid At",
    ]


    worksheet.append(
        headers
    )


    for row in crm[
        "rows"
    ]:

        worksheet.append(
            [
                row[
                    "event"
                ],
                row[
                    "customer_name"
                ],
                row[
                    "customer_email"
                ],
                row[
                    "customer_phone"
                ],
                row[
                    "booking_reference"
                ],
                row[
                    "ticket_type"
                ],
                int(
                    row[
                        "quantity"
                    ]
                    or 0
                ),
                int(
                    row[
                        "checked_in_count"
                    ]
                    or 0
                ),
                int(
                    row[
                        "not_checked_in_count"
                    ]
                    or 0
                ),
                row[
                    "checkin_status"
                ],
                row[
                    "payment_status"
                ],
                float(
                    Decimal(
                        str(
                            row[
                                "unit_price"
                            ]
                            or 0
                        )
                    )
                ),
                float(
                    Decimal(
                        str(
                            row[
                                "line_total"
                            ]
                            or 0
                        )
                    )
                ),
                row[
                    "purchase_date"
                ],
                row[
                    "paid_at"
                ],
            ]
        )


    worksheet.freeze_panes = (
        "A2"
    )

    worksheet.auto_filter.ref = (
        worksheet.dimensions
    )


    widths = {
        "A": 28,
        "B": 24,
        "C": 30,
        "D": 18,
        "E": 22,
        "F": 18,
        "G": 12,
        "H": 12,
        "I": 16,
        "J": 18,
        "K": 16,
        "L": 14,
        "M": 14,
        "N": 20,
        "O": 20,
    }


    for column, width in (
        widths.items()
    ):

        worksheet.column_dimensions[
            column
        ].width = width


    for cell in (
        worksheet[
            "L"
        ][1:]
        +
        worksheet[
            "M"
        ][1:]
    ):

        cell.number_format = (
            'R #,##0.00'
        )


    buffer = (
        io.BytesIO()
    )

    workbook.save(
        buffer
    )

    buffer.seek(
        0
    )


    filename = (
        "kalxa-attendees-"
        + datetime.utcnow().strftime(
            "%Y%m%d-%H%M"
        )
        + ".xlsx"
    )


    return send_file(
        buffer,

        as_attachment=
            True,

        download_name=
            filename,

        mimetype=(
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
        ),
    )

# ============================================================
# KALXA TICKETING
# REGISTER TICKET REFUND ROUTES
# ============================================================

REFUND_ENDPOINTS = {
    "kalxa_refund_csrf",
    "kalxa_initiate_ticket_refund",
    "kalxa_reconcile_ticket_refund",
}

existing_refund_endpoints = (
    REFUND_ENDPOINTS.intersection(app.view_functions)
)

if not existing_refund_endpoints:

    register_ticket_refund_routes(
        app,
        db=db,
        TicketOrder=TicketOrder,
        TicketOrderItem=TicketOrderItem,
        TicketRefund=TicketRefund,
        TicketRefundItem=TicketRefundItem,
        EntryPass=EntryPass,
        paystack_api_request=paystack_api_request,
        superadmin_guard=kalxa_refund_superadmin_guard,
    )

    app.logger.info(
        "[KALXA Refunds] Refund routes registered successfully."
    )

else:

    app.logger.warning(
        "[KALXA Refunds] Existing refund endpoints detected: %s",
        sorted(existing_refund_endpoints),
    )

    missing_refund_endpoints = (
        REFUND_ENDPOINTS - set(app.view_functions)
    )

    if missing_refund_endpoints:

        raise RuntimeError(
            "Partial refund route registration detected. "
            f"Missing endpoints: {sorted(missing_refund_endpoints)}."
        )


